INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892817326', 'Jogo 2 Pneus Speedmax Aro 16 Controlmax CP11 185/55R16 87V XL', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 871.13, 801.44, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwt-lygniniio6bq87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23892817326', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693954416', 'Transferidor de Grau 0-180 Graus Aço Inox 4GP EDA', 'Transferidor de Grau 0-180° com Régua de 140 mm em Aço Inox 4GP EDA – Alta Precisão e Durabilidade Ideal para medições angulares em marcenaria, mecânica, metalurgia e construção civil, o Transferidor de Grau EDA 4GP é fabricado 100% em aço inox, oferecendo excelente resistência à ferrugem, durabilidade e precisão. Medição Precisa com Fácil Leitura Conta com graduações duplas de 0 a 180º gravadas em baixo relevo e pintadas, permitindo leitura direta de ângulos e também de ângulos suplementares. O acabamento garante excelente visibilidade e vida útil estendida, mesmo em ambientes com alta umidade ou poeira. Fixação Segura e Versatilidade no Uso A lâmina com régua de 140 mm pode ser firmemente ajustada em qualquer ângulo por meio da porca de fixação, garantindo estabilidade na medição. A parte traseira plana permite melhor apoio sobre superfícies, facilitando o uso em diversas situações. Características Técnicas • Faixa de medição: 0 a 180 graus • Régua: 140 mm • Material: Aço inox • Dimensões: 19,5 cm x 1 cm x 5,5 cm • Fixação por porca • Leitura dupla de ângulos Resistente, prático e confiável, é uma excelente escolha para profissionais e hobbystas que exigem precisão nas medições. Deseja as palavras-chave para este produto também? Código de Fábrica: 4GP Marca: Eda Garantia: 3 meses * Imagens meramente ilustrativas.', 49.9, 49.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfi7-m96be58zs8158d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F22693954416', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698062604', 'Pneu Moto Michelin Aro 17 Road 6 190/55R17 (75W) TL - Traseiro', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores.Estar sobre duas rodas traz sensações únicas para motociclistas, que sentem as emoções de liberdade e aventura se misturarem a cada curva. Para melhorar essa experiência única, aposte no pneu que traz segurança e desempenho por muito mais tempo: o Michelin Road 6. Com novo composto de sílica, tecnologia de ponta e desenho moderno na banda de rodagem, o Michelin Road 6 oferece durabilidade 10% superior ao modelo anterior e mais de 15% de aderência no piso molhado, o que torna suas viagens mais prazerosas e seguras. Sobre a marca Michelin A marca Michelin foi fundada em 1889 em Clermont-Ferrand, França e com o passar dos anos tornou-se uma referência em pneus. Produz atualmente pneus para carros, motos, suvs, caminhonetes e muito mais. Os pneus Michelin se consagraram no mercado graças à excelente aderência, durabilidade e conforto. Hoje são utilizados como pneu original de fábrica por diversas montadoras de automóveis, desde carros compactos até superesportivos de alta potência, que precisam de toda a tecnologia dos pneus Michelin para obter os melhores resultados nas pistas.', 2039.88, 1876.69, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfgy-m3fa3l5dn9swfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23698062604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
