INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992935617', 'Magic Mixies Caldeirão Surpresa Mixlings The Crystal Woods', 'Desperte a magia com o Collector''s Cauldron da Série 3 Crystal Woods dos Magic Mixies Mixlings! Este extraordinário Caldeirão traz a terceira edição da série Mixlings, transportando os pequenos para a encantadora Floresta de Cristal. O Caldeirão do Colecionador é o portal para um mundo de surpresas mágicas. Ao levantar a tampa do caldeirão, desvende os ingredientes mágicos e prepare-se para o emocionante ritual de "Fizz and Reveal". Com as palavras mágicas "Magicus Mixus", testemunhe a revelação de um Mixling especial e de sua varinha única. A Série 3 Crystal Woods apresenta cinco novos poderes mágicos dos Mixlings, prontos para serem descobertos. Dos Glowlings que brilham no escuro aos Lucklings que revelam fortunas iminentes, cada Mixling reserva uma surpresa única. Com cabelos incríveis, mudança de cor e asas de anjo, a diversidade de poderes é fascinante. São mais de 40 Mixlings para conhecer Série 3 Crystal Woods. Cada peça é uma oportunidade emocionante para desvendar a magia e colecionar momentos inesquecíveis com os Magic Mixies Mixlings!', 109.99, 99.99, NULL, 'Mom & Baby > Toys > Pretend Play', 'https://cf.shopee.com.br/file/sg-11134201-7rcbz-lto120wmeaq18b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F22992935617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40672705105', 'Sandália Infantil Feminina Salto Plataforma Rosê Meninas Moda', 'TABELA DE MEDIDAS Nº 28 - 19 cm Nº 29 - 19,5 cm Nº 30 - 20 cm Nº 31 - 21 cm Nº 32 - 21,5 cm Nº 33 - 22 cm Nº 34 - 23 cm DESCRIÇÃO A sandália infantil feminina Bobibiu é perfeita para as meninas que adoram estilo, conforto e charme em cada passo. Com design moderno de plataforma, acabamento delicado em tom rosé e detalhes de pingentes divertidos, esse modelo é a escolha ideal para completar o look em festas, passeios e momentos especiais. DESTAQUES - Design moderno com plataforma leve e confortável - Cor delicada que combina com diversos looks infantis - Detalhes com pingentes fofos que dão um toque especial - Fecho ajustável para mais segurança e praticidade - Ideal para usar no Dia das Crianças, festas, passeios e no dia a dia - Disponível em numerações que acompanham o crescimento, essa sandália é a opção certa para quem procura beleza, segurança e conforto em um só calçado.', 149.9, 129.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sandals', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgxqnolkkp34a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296584125%2F40672705105', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
