INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397560674', 'Boneca Coleção Te Amo Bebê Menina Abre e Fecha os Olhos Super Toys - 577', 'A Boneca da Coleção "Te Amo Bebê" para meninas é mais do que um simples brinquedo; é uma expressão de amor e afeto em forma de boneco. Cada boneca nesta coleção é cuidadosamente projetada para transmitir ternura e carinho, oferecendo à criança um companheiro adorável para brincar e cuidar. Com suas feições delicadas e vestimentas encantadoras, as bonecas da coleção "Te Amo" capturam o coração das meninas instantaneamente. Seus detalhes amorosos e expressões faciais convidativas fazem com que cada boneco seja único e especial. Além de sua aparência cativante, os bonecos da coleção "Te Amo Bebê" são feitas com materiais de alta qualidade para garantir durabilidade e segurança durante o tempo de brincadeira. Essas bonecas não são apenas brinquedos; são companheiros confiáveis que incentivam a imaginação, a empatia e o cuidado. Ao brincar com uma boneca da coleção "Te Amo Bebê", as meninas criam laços afetivos e aprendem importantes valores de amor e compaixão desde cedo. Seja como presente para uma ocasião especial ou como parte da coleção de brinquedos de uma criança, uma boneca da coleção "Te Amo Bebê" é mais do que um simples objeto - é uma lembrança duradoura do amor e da ternura que sempre estarão presentes em sua vida. ESPECIFICAÇÕES: Material: Vinil Som: não possui som Idade recomendada: acima de 3 anos Medidas Aproximadas (AxLxC): 16 x 30 x 15 cm Peso (Aproximado): 0,863 Kg Características: - Marca: Super Toys - Modelo: 577 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: 1 - Boneca Te Amo Bebê Menina boneca bebê - boneca bebê menina - boneca para meninas - boneca para crianças - bonequinha - bonecas - brinquedos - brinquedos infantis - bonequinha - boneca te amo bebe', 104.2, 93.78, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rd50-lw4e6iy4idoo6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F22397560674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997796998', 'Luva Nitrílica Inoven Sem Pó Preta Pacote com 100 Un. Tamanho M', 'Luva Nitrílica Inoven - Preta - M - Pacote 100 Un. Proteção e higiene no trabalho. Ideal para uso em centros de estética por banhistas e tosadores. - Agilidade de movimentos; - Resistentes e impermeáveis; - Alto nível de sensibilidade, maleabilidade e destreza; - Não adere à sujeira e não retém odor; - Ajuste adequado às mãos; - Alta resistência durante o uso; - Maciez, conforto e flexibilidade; - Proteção do usuário e do produto; - Punho alongado e fácil calçamento; - Econômica, garante menos descarte. Advertências: - Produto de uso único; - Produto de uso não médico; - Proteja este produto do calor, umidade e da luz; - Em casos de rasgos ou furos, as luvas devem ser trocadas imediatamente por um novo par; - Produto não indicado para atividades abrasivas, ou em contato com contaminantes químicos agressivos e fluídos orgânicos; - Após o uso, remover e descartar em local apropriado Material: 100% borracha sintética nitrílica sem pó. Tipo: pacote com 100 unidades. Medidas: Comprimento: 24cm; Largura: 9,5cm. Marca: Inoven.', 38.4, 38.4, NULL, 'Health > Medical Supplies > Medical Gloves & Masks', 'https://cf.shopee.com.br/file/sg-11134201-7rdvy-lzgs8o3zamuk3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688030691%2F19997796998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
