INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6892575530', 'KIT 10 PLAQUINHAS DIVERTIDAS CHÁ DE PANELA SELFIE (COD 04)', 'DEIXE SEU CHÁ DE PANELA AINDA MAIS ANIMADO E MEMORÁVEL COM ESTE KIT DE 10 PLAQUINHAS DIVERTIDAS E TEMÁTICAS (CÓDIGO 04) PARA SELFIES! IDEAIS PARA FOTOS DESCONTRAÍDAS COM AS AMIGAS E FAMILIARES, CELEBRANDO A FUTURA NOIVA E GARANTINDO MUITAS RISADAS. CADA PLAQUINHA JÁ VEM COLADA EM UM PALITO DE PLÁSTICO RESISTENTE, PRONTA PARA USAR E AUMENTAR A DIVERSÃO DA SUA CELEBRAÇÃO! CONTEÚDO: 10 PLAQUINHAS COM FRASES VARIADAS TEMÁTICAS DE CHÁ DE PANELA. CADA PLAQUINHA JÁ VAI COLADA EM UM PALITO DE PLÁSTICO RESISTENTE. TAMANHO: PLAQUINHAS: TAMANHOS VARIADOS, APROXIMADAMENTE 15 CM A 20 CM DE LARGURA. PALITOS: APROXIMADAMENTE 20 CM DE COMPRIMENTO. MATERIAL: PRODUZIDAS EM PAPEL CARTONADO RESISTENTE COM IMPRESSÃO COLORIDA E VIBRANTE. PALITOS DE PLÁSTICO RESISTENTE. ATENÇÃO ❗: AS FRASES DAS PLAQUINHAS PODEM VARIAR LIGEIRAMENTE DEPENDENDO DO LOTE. TODAS AS PLAQUINHAS DESTE KIT ACOMPANHAM PALITO DE PLÁSTICO RESISTENTE. VERIFIQUE O PRAZO DE ENVIO 🚚 ANTES DE FINALIZAR A COMPRA. GARANTA MUITAS RISADAS E FOTOS INCRÍVEIS NO SEU CHÁ DE PANELA COM PALITOS DE PLÁSTICO! ADICIONE ESTE KIT AO SEU CARRINHO! 💖🎉🍳', 17.1, 17.1, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/576e6e2b45e6eea3da015d7d522024ae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F6892575530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
