INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18430834526', 'Kit Farol Milha Fusca 1300 Amarelo', 'Kit Completo Farol Milha Redondo 136MM A RG Auto Peças disponibiliza atendimento especializado em horário comercial, tire todas as suas duvidas no campo de perguntas nossos atendentes são especializados no ramo, prontos apara responder dúvidas técnicas e até mesmo ajudando com dicas de instalação. Pensado para satisfazer as necessidades do cliente esse kit conta com chicote feito pela TC Chicotes, empresa certificada com ISO 9001 o que traz uma garantia de qualidade e segurança na instalação elétrica, os faróis são 100% Nacional com Carcaça de Ferro e Lente de vidro, são altamente resistentes e bem acabados, as lampadas são super brancas de 6.000K o que garante uma melhor iluminação e um visual surpreendente. Geralmente nossos envios são feitos em até no máximo 24 Horas Úteis. O Kit Contém: 2 - Farol de milha Redondo 136MM 2 - Lampada H3 1 - Relé 4 Terminais 40ah 1 - Fusível 15Ah 1 - Botão de Farol de Milha universal 1 - Chicote elétrico universal Tire todas as suas dúvidas antes de comprar, temos profissionais especializados para melhor atende-los, horário de atendimento segunda as sextas 09:00-17:00hrs, sábados 09:00-12:00hrs. Produto novo com garantia. A RG Peças recomenda que a instalação seja feita por um profissional especializado, não nos responsabilizamos por mal uso ou má instalação do produto.', 199.0, 199.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lpfbbd2i881e41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F397441974%2F18430834526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
