INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208249971', 'Creme Hidratante Para As Mãos Vitamina De Banana Made In - Rrb5004 - Melu', 'CREME HIDRATANTE PARA AS MÃOS VITAMINA DE BANANA MADE IN- RRB5004 O Creme de Vitamina de Banana oferece hidratação intensa com textura leve, perfeita para o cuidado diário. Enriquecido com ingredientes hidratantes que deixam as mãos macias, nutridas e com um cheirinho doce e divertido de banana. Ideal para levar na bolsa e reaplicar sempre que quiser um toque de carinho na pele! Aplique sobre as mãos e massageie suavemente até a absorção do produto. Reaplique sempre que tiver Uso externo. Não aplicar em pele irritada ou lesionada. Em caso de irritação, suspender o uso e procure orientação médica. Manter fora do alcance das crianças. Conserve o produto bem fechado, longe da luz e do calor excessivo.', 23.69, 19.43, NULL, 'Beauty > Skincare > Face Scrub & Peel', 'https://cf.shopee.com.br/file/sg-11134201-81zu9-mmoyltc67qitca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1784827857%2F58208249971', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399547905', 'Kit 4 Cadeiras de Jantar Allegra Prática Empilhável', 'Cadeira de Jantar Allegra Prática Empilhável A Cadeira de Jantar Allegra é um item de decoração versátil e inovador, possui diversas linhas que se conectam para formar um design diferenciado e alegre no ambiente. Se destaca no conforto proporcionado pois suas curvas se encaixam perfeitamente ao nosso corpo, tornando-se muito aconchegante! Sua utilização pode ocorrer em diversos ambientes, varandas e sacadas com cores mais vibrantes ou até mesmo uma sala de jantar ou reuniões com cores mais neutras. Empilhável, ideal para organização da casa ou até mesmo eventos, facilitando o transporte e aumentando o espaço. Essa versão da Allegra é desmontável ideal para otimizar o seu espaço e facilitar o transporte do produto. Outro diferencial da Cadeira de Jantar Allegra é que ela é confeccionada em materiais de alta qualidade, feita 100% em polipropileno material que garante alta durabilidade e resistência. Especificações Técnicas: >Material: 100% Polipropileno >Resistencia: Aconselhável até 120,00kg >Peso aproximado: 5,00 Dimensões: > Altura Total(cm): 83,00 > Altura Do Assento(cm): 45,00 > Profundidade do Assento(cm): 44,00 > Largura do Assento(cm): 31,00 > Altura até o Braço(cm): 66,00 > Largura Total(cm): 51,00 > Profundidade Total(cm): 41,00 Importante: Produto enviado desmontado acondicionado em caixa de papelão reforçada, acompanha manual de montagem (não nos responsabilizamos pela montagem do produto). > Observações de Entrega: Os entregadores não são autorizados: > Entrar no domicílio, sem estar acompanhado pelo cliente; > Entrar ou subir desacompanhado em prédio residencial ou comercial, o cliente precisa receber o pedido na portaria; > Entregar por meios alternativos (exemplo: içar produto por janela, subir escadas); > Entregar em edifícios, entrega será realizada apenas na portaria; > Realizar montagens, instalação ou manutenção de produtos; > Abrir a embalagem do produto; > Realizar entrega em endereço diferente do que consta na Nota Fiscal; > Garantia: 03 Meses Contra Defeitos de Fabricação. > Marca: Magazine Decor', 859.9, 599.9, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdxk-mc223vxcufh41a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F347781606%2F21399547905', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10999131487', 'Kit Relacao Tracao Transmissao Cg Titan Fan 150 2004 2005 2006 2007 2008 2009 2010 2011 A 2015 Original Kmc Com Retentor', 'KIT RELACAO COMPLETO TITAN 150 (COROA/PINHAO E CORRENTE COM RETENTOR) - OFERTA LANCAMENTO!!! NOVO NA CAIXA - ORIGINAL KMC PRINCIPAIS APLICACOES: MOTOS: TITAN 150 (ES/KS/FAN/MIX/TODAS) ANO: 2004 A 2015, *Aco 1045 *Corrente 428HX118L (COM RETENTOR) *43 dentes da coroa *16 dentes do pinhao Funcao da Coroa e do Pinhao: A Coroa e o Pinhao juntamente com a corrente sao conhecidos como kit relacao, e sao fundamentais para uma pilotagem segura, sendo responsaveis por transmitir o movimento da saida da transmissao ate a roda traseira. Como detectar problemas? Verifique se ha desgastes nos dentes da coroa e do pinhao. Ao trocar verifique tambem: o ideal e realizar a troca do kit inteiro (coroa, pinhao e corrente) para garantir a durabilidade do conjunto, ruidos e folga na transmissao de forca. Diferenciais: Produzida em aco 1045 Endurecimento termico para aumentar a resistencia e durabilidade Numero de dentes conforme padrao original Dentes tratados termicamente ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 230.0, 173.24, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-820l7-mqhxiaz914w0b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F972424499%2F10999131487', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20199493701', 'Condicionador Meu Liso Escudo Antiporosidade 300ml', 'O Condicionador Equilíbrio do pH Meu Liso Escudo Antiporosidade condiciona e hidrata intensamente, deixando os fios macios e sedosos, proporcionando 96h de tratamento profundo e selamento das cutículas. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos lisos e alisados. Qual a indicação? Cabelo poroso, danificado e sem brilho. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Conta com a tecnologia Liss Expert que garante ação intensa, resultado rápido e proteção contra danos externos. <>MODO DE USO$& Qual a melhor forma de usar? Aplique no cabelo molhado, após a lavagem com o shampoo. Deixe agir por alguns instantes e enxágue. <>CARACTERÍSTICAS$& É produto vegano? O Condicionador Equilíbrio do pH Meu Liso Escudo Antiporosidade é vegano. É liberado? O Condicionador Equilíbrio do pH Meu Liso Escudo Antiporosidade não é liberado.', 21.0, 12.6, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/br-11134201-820l8-mp9hm87ijyme1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F20199493701', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
