INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41100661475', 'Bíblia Sagrada| ACF | Letra Gigante | Capa Luxo V|nho', 'Bíblia Sagrada| ACF | Letra Gigante | Capa Luxo V|nho Sinopse da Bíblia: A versão Almeida Corrigida Fiel (ACF) (revisada segundo o novo acordo ortográfico da língua portuguesa em 2011) é uma tradução fiel do Velho Testamento em Hebraico (Massorético) e do Novo Testamento em Grego (Textus Receptus), segundo o método de tradução formal (traduzindo cada palavra e mantendo a beleza linguística). Especificações do livro: Título: Bíblia Anote | ACF | Letra Gigante | Capa Luxo V|nho Linguagem: Almeida Corrigida Fiel Capa: V|nho Acabamento: Capa Flexível Borda: Dourada Índice: Não Harpa: Não Palavras de Jesus em destaque: Não Letra: Gigante Fitilho: Sim, fitilho Duplo Páginas: 1376 Dimensões: Altura: 21 cm Largura: 14 cm Profundidade: 3,5 cm Peso: 0,640 kg ISBN: 7898572202020 Editora: Sociedade Bíblica Trinitariana do Brasil', 88.54, 88.54, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ksqs3rb1tu9f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F41100661475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
