INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43777295778', 'Suporte para TV e monitores Tri articulado 23 a 65 polegadas Sonn', 'Suporte Tri-Articulado para TV 23” a 65” – Sonn | Alta Qualidade e Custo Benefício** Garanta mais segurança, praticidade e mobilidade para sua TV ou monitor com o Suporte Tri-Articulado Sonn, ideal para telas de 23" a 65" polegadas. Projetado para oferecer resistência e flexibilidade, ele suporta equipamentos de até 35 kg sem perder estabilidade. Características do Produto: Compatível com TVs e monitores de 23” a 65” Suporta até 35 kg com total segurança Padrão Vesa 400x400 máx inclinação de -5º a +15º Distância da parede: 43,5 cm 3 articulações, permitindo ajustes de ângulo, distância e posição Fabricado em aço de alta durabilidade Marca Sonn– nova no mercado, com foco em qualidade e custo-benefício Acompanha kit completo de parafusos para instalação Ideal para salas, quartos, escritórios e áreas de entretenimento, proporcionando liberdade para ajustar sua TV da maneira que preferir. Escolha Sonn e tenha qualidade sem pagar mais por isso!', 78.0, 56.6, NULL, 'Home Appliances > TVs & Accessories > TV Brackets', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mic1eedjbqwy74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1418840072%2F43777295778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
