INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498265387', 'Lona Plástica de Proteção Cobertura Impermeável Azul tamanhos', 'ENCERADO DE POLIETILENO - LONA 70g Composição: polietileno e metal. Aproximadamente 100 micras. Com ilhoses metálicos de 12 mm para amarração a cada 1 metro da lona. Variação de +/- 5% no peso da lona. Características e uso do produto Indicada para agricultura, acampamento, pesca, feiras livres e indústrias. Atenção: Não utilizar a lona diretamente sobre superfícies aquecidas ou expostas ao sol e caminhões. A exposição excessiva ao sol pode causar danos e/ou manchas. Não indicamos utilizar em contato com produtos químicos e resinas e para cobertura de peças perfurantes/cortantes. O esforço excessivo e a ação de ventos fortes podem provocar o rompimento dos ilhoses e da lona. Caso necessário, lavar com água e sabão neutro. Lona resistente a água, porém não é impermeável. 10x5m e 10x8m', 269.9, 175.44, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcm8efckhanm25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F21498265387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
