INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093478972', 'Cola Para Alimentos Confeitaria 15g Mago', 'Use a cola comestível para aplicar decorações em bolos e doces e auxiliar na colagem de modelagens com pasta americana e papel de arroz. Ingredientes: Água, Amido modificado, Conservantes alimentares (como sorbato de potássio), Glicerina, Aromatizantes ou estabilizantes alimentares. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 8.99, 8.99, NULL, 'Food & Beverages > Baking Needs > Baking Decoration', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mifwevih3b437b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F23093478972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
