INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498665657', 'Dinossauro Stegosaurus Articulado Jurassic World - Mattel', 'DESCRIÇÃO DO PRODUTO: A linha Jurassic World Hammond Collection criou um novo padrão para edições de colecionadores, com articulações de luxo e detalhes realistas. Este boneco do dino Estegossauro, uma espécie de grande porte, é fiel ao visual do filme "O Mundo Perdido: Jurassic Park" (1997). Suas icônicas placas ósseas e cauda espinhosa flexível garantem um visual único, além de detalhes premium, como olhos em vidro. Com 15 articulações, esta peça é perfeita para poses incríveis. Sem dúvidas, um item imperdível para colecionadores a partir dos 8 anos de idade! Cores e decorações podem variar. CARACTERÍSTICAS TÉCNICAS: Conteúdo da Embalagem: 1 Dinossauro. Dimensões Aproximadas do Produto: 18cm x 8cm x 34cm (Altura x Largura x Comprimento/Profundidade). Dimensões Aproximadas da Embalagem: 25cm x 14cm x 34cm (Altura x Largura x Comprimento/Profundidade). Material/Composição: Plástico. Idade Mínima Recomendada: A partir de 8 anos. Participantes: A partir de 1 pessoa. Marca: Mattel. Referência: JCH08 Outras informações: As cores podem variar entre as imagens mostradas acima e o produto. Imagens meramente ilustrativas. Aviso: As informações e imagens divulgadas são de total responsabilidade do fabricante/fornecedor. Produto lacrado e disponível a pronta entrega para todo Brasil! APROVADO PELO INMETRO', 415.39, 365.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7ra3m-mbdv0riuutzl76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F446413605%2F23498665657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258121945', 'Par Alto Falante 6x9 Bomber BBX 200W RMS 4 Ohms Quadriaxial Som Automotivo Potente', 'DANJASOM | Qualidade, confiança e envio rápido Alto-Falante 6x9 Bomber BBX 200W RMS 4 Ohms Multivias O Bomber BBX 6x9 é um alto-falante automotivo projetado para oferecer qualidade sonora, com graves firmes, médios equilibrados e agudos definidos. Possui construção resistente com cone em IMPP, bobina em Kapton e conjunto magnético otimizado, garantindo durabilidade e bom desempenho mesmo em volumes elevados. Cone em IMPP para maior rigidez e menor distorção Bobina de voz com corpo em Kapton e fio de cobre Estrutura metálica em aço estampado de alta resistência Excelente opção para upgrade do sistema original ESPECIFICAÇÕES TÉCNICAS - Modelo: BBX 6x9 - Tipo: Multivias QUADRIAXIAL - Potência RMS (unidade): 100 Watts - Potência RMS (par): 200 Watts - Impedância nominal: 4 Ohms - Resposta de frequência: 54 Hz a 20 kHz - Sensibilidade: 86 dB SPL - Material do corpo da bobina: Kapton Peso unitário: 0,49 kg Dimensões do produto (L x A x P): 261 x 104 x 211 mm CONTEÚDO - 2 Alto-falantes 6x9 Bomber BBX - Manual do fabricante DANJASOM ¬ Distribuidor oficial das maiores marcas ¬ Todos os produtos com NOTA FISCAL ¬ Envio rápido e seguro ¬ Garantia direto do fabricante Em caso de dúvidas, utilize o chat e converse conosco — nossa equipe está pronta pra ajudar você a montar seu projeto com segurança e performance.', 269.41, 199.36, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-820ll-mmkgnlcun18g55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F901722804%2F58258121945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
