INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698174731', 'Ar Condicionado LG DUAL Inverter AI Voice 12000 BTUs Quente e Frio 220V S3-W12JA31D', 'Ar Condicionado LG DUAL Inverter AI Voice 12000 BTUs Quente e Frio - Alto Desempenho, Economia de Energia e Climatização Rápida O Ar Condicionado LG DUAL Inverter de 12000 BTUs combina tecnologia avançada e alta eficiência para climatizar ambientes com precisão em qualquer estação. Com Inteligência Artificial, ajusta automaticamente a temperatura de acordo com os hábitos de uso e as condições do espaço. Possui Wi-Fi integrado pronto para uso, permitindo controle remoto pelo aplicativo LG ThinQ e compatibilidade com Google Assistente e Amazon Alexa para comando de voz. A tecnologia exclusiva DUAL Inverter com rotor duplo garante climatização até 40% mais rápida, temperatura estável e até 70% de economia de energia em comparação a modelos convencionais. Conta ainda com controle de consumo em quatro níveis, modo SLEEP, TIMER de até 24 horas, JET MODE para resfriamento ou aquecimento acelerado, auto limpeza e filtro antibactéria e antialérgico. Tecnologia inteligente que transforma o ambiente com conforto e equilíbrio. Especificações Técnicas: Marca: LG Modelo: S3-W12JA31D.EB2GAM1 Modelo da Evaporadora: S3NW12JA31D.EB2GAM1 Modelo da Condensadora: S3UW12JA31D.EB2GAM1 Tecnologia: DUAL Inverter Ciclo: Quente e Frio Capacidade: 12000 BTUs Voltagem: 220V Classificação Energética: A Consumo de Energia: 415.38 kWh/ano Vazão de Ar: 28 m³/min Nível de Ruído: Evaporadora 42 dB / Condensadora 54 dB Gás Refrigerante: R-32 Modos de Operação: Refrigerar, Aquecer, Ventilar, Desumidificar, Automático Funções: Modo SLEEP, TIMER, ENERGY CONTROL, JET MODE Conectividade Wi-Fi: Incluso Selo Anatel: Sim - Nº de homologação: 13131-20-04547 Material da Serpentina: Cobre Desnível Máximo entre Unidades: 7 m Dimensões Evaporadora: 90,9 L x 38,3 A x 25,6 P cm Dimensões Condensadora: 71,7 L x 49,5 A x 23 P cm Peso Evaporadora: 7,1 Kg Peso Condensadora: 20 Kg Garantia: 24 meses OBS: Kit de instalação não incluso. A instalação deve ser realizada por técnico especializado.', 4086.25, 2526.16, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/br-11134201-820lw-mn5ucg8qrg1u06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059412251%2F22698174731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
