INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18197912905', 'Cabo de Aço Color Black 140lb 5m - Maruri', 'Cabo de Aço 5m - Maruri O Cabo de Aço 5m da Maruri é o acessório ideal para os pescadores que procuram resistência e durabilidade nas suas pescarias. Desenvolvido para fazer encastoados e empatar anzóis de forma eficiente, este cabo garante segurança nas capturas, especialmente quando se trata de peixes com dentição afiada, como traíras e dourados. Com seu revestimento de nylon transparente, ele oferece não apenas uma excelente resistência, mas também um visual discreto que não intimida os peixes, aumentando as chances de sucesso nas capturas. Esse revestimento ainda ajuda a prolongar a vida útil do cabo, protegendo-o contra corrosões e desgastes comuns em ambientes aquáticos. O cabo de aço inoxidável da Maruri é um dos mais versáteis do mercado, ideal tanto para confecção de leaders para iscas artificiais quanto para empates de anzóis, garantindo que os peixes mais agressivos e de maior porte não rompam a linha durante a fisgada. Além disso, o produto inclui 70 luvas para encastoar, proporcionando ainda mais praticidade ao pescador na hora de montar seu equipamento. Com 5 metros de comprimento, o Cabo de Aço da Maruri oferece o equilíbrio perfeito entre força, flexibilidade e discrição, ideal para diversas situações de pesca. Especificações Marca: Maruri Cabo de aço inoxidável Revestimento de nylon transparente Acompanha 70 luvas para encastoar Comprimento: 5 metros', 25.9, 25.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/sg-11134201-7rdw5-m0kahcu342ix68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F18197912905', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
