INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297415511', 'Condicionador Monange Detoxterapia 325Ml', 'O Condicionador Monange Detox Terapia limpa profundamento os fios constantemente expostos a agentes poluentes e outros danos do cotidiano. Com menta, gengibre e capim limão, que possuem propriedades antioxidantes, o Condicionador nutre até a segunda camada da fibra capilar, além de suavizar as agressões externas, restaurando a beleza natural do cabelo. Produto livre de silicones, sal e parabenos. Modo de uso: Aplique nos cabelos úmidos, emulsione e deixe agir por alguns minutos e enxágue. #html-body [data-pb-style="646BA6528210C"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA65282120"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 23.99, 23.99, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lmg4rj4kp6qi20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F21297415511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54354158911', 'Box Pokemon Baralho Batalha de Liga Mewtwo EX da Equipe Rocket Copag 35874 Cartas TCG Geek Presente', 'OBS. Produto novo e Lacrado de fábrica, cartas em Português, originais da Copag. Mergulhe no mundo Pokémon com a Coleção Mega Mewtwo ex! Este conjunto especial traz uma impressionante carta laminada promocional de Mega Mewtwo ex, onde o filhote e sua mãe se unem em uma poderosa Megaevolução. Destaque-se nas batalhas com a Habilidade Faz Teu Corre, que permite comprar cartas adicionais, e surpreenda seus oponentes com o Combo de Disparo Rápido, um ataque que pode causar danos devastadores com base em jogadas de moeda. A coleção inclui 8 pacotes de booster do Pokémon Estampas Ilustradas, oferecendo ainda mais oportunidades para expandir sua coleção com cartas incríveis. Esta é uma oportunidade única para os treinadores fortalecerem seus decks com uma das duplas mais carismáticas do universo Pokémon. Ideal para colecionadores e jogadores que buscam adicionar uma carta promocional exclusiva ao seu arsenal competitivo. Características: - Marca:Copag - Modelo:35874 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01 Baralho com 60 cartas pronto para jogar - 01 folha com contadores de dano de papel-cartão - 01 Caixa de baralho - 01 Guia de estratégias - 01 Carta codificada para o Pokémon Estampas Ilustradas Live.', 125.91, 125.91, NULL, 'Hobbies & Collections > Collectible Items > Others', 'https://cf.shopee.com.br/file/sg-11134201-825zv-mj4fk6k3s16sfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F54354158911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097079302', 'O Homem-Cão desgovernado - Companhia das Letrinhas', 'Antes do Capitão Cueca, Jorge e Haroldo criaram um herói que bebe água da privada, rola sobre os bandidos e late na cara do perigo: O Homem-Cão! Essa é a continuação de suas aventuras (e confusões).Quando o oficial Rocha e seu cachorro Greg sofrem um acidente, o único jeito de os dois sobreviverem é fundindo a cabeça do cão com o corpo do policial — e é assim que nasce o Homem-Cão, o melhor policial da cidade! Mas ele ainda está aprimorando suas habilidades no trabalho.Pepê, o gato, seu maior inimigo, fugiu da Prisão dos Gatos mais uma vez e está apavorando a todos com seus atos criminosos. A vilania parece um peixe fora d’água solto pela cidade. Mas o Homem-Cão está à solta — e desgovernado! — Para deter os malvados da vez. Será que ele vai conseguir manter o foco longe dos brinquedos do pet shop e salvar a cidade mais uma vez?', 64.78, 64.78, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbmx-ln9yv0q7y01zc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23097079302', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
