INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21813670459', 'Paralama Dianteiro Cromo Forte Fan 2005/08', 'As carenagens e peças plásticas Cromo Forte são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricadas em ABS 100% virgem, são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Marca: Cromo Forte; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Moto compatível: Fan 125 2005 a 2008. Aplicação: - Preto Injetado: Fan 125 2005 a 2008. Atenção! -Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada.', 84.11, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/c93890ad6975349eb564c89fc165c838', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F21813670459', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251059037', 'Aspirador de Pó Sem Fio 3 em 1 Multifuncional Lava Aspira e Limpa Alta Sucção 12kpa Bivolt 110/220V', 'ASPIRADOR DE PÓ E LIMPEZA MULTIFUNCIONAL SEM FIO 3 EM 1 – OIH-5601 Potência, praticidade e versatilidade para o seu dia a dia! Transforme sua rotina de limpeza com o aspirador de pó multifuncional sem fio da Oasis Market. Com design moderno, alta performance e recursos 3 em 1, ele aspira, limpa e lava diversos tipos de piso com total praticidade – tudo isso sem fio, oferecendo muito mais liberdade de movimento. Destaques do Produto: - Multifuncional 3 em 1: Aspira, limpa e lava - Sem fio: Mobilidade total para alcançar todos os cantos - Alta performance de sucção: Nível de vácuo de 12kpa - Autonomia de até 40 minutos com uma única carga - Bateria potente: 4000mAh (tipo 21700) x6 - Reservatórios separados para água limpa (635ml) e suja (550ml) - Motor principal com 160W e até 70000rpm - Voltagem nominal de 25.2V - Tempo de recarga: aproximadamente 5 horas - Design ergonômico e leve: apenas 4,23kg - Tamanho total: 1750 x 210 x 280mm ITENS INCLUSOS: - 1 Aspirador OIH-5601 - 1 Suporte de carregamento - 1 Controlador de jatos de água - 2 Suportes de acessórios - 1 Carregador - 1 Elemento de filtro sobressalente - 1 Escova de limpeza - 1 Escova de rolo sobressalente - 1 Frasco de limpeza especial para piso - 1 Cistérna - 1 Dispositivo de água doce SEGURANÇA: - Produto com certificação INMETRO e selo Saron, garantindo segurança, eficiência e confiabilidade. INFORMAÇÕES TÉCNICAS: - Peso: 4230g - Potência nominal: 220W - Motor principal: 160W - Velocidade do motor: 70.000rpm - Capacidade da bateria: 4000mAh x6 - Tipo de bateria: 21700 - Voltagem nominal: 25.2V - Tempo de uso contínuo: até 40 minutos - Tempo de recarga: cerca de 5 horas - Reservatórios de água limpa/suj