INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098952194', 'Pegador Para Churrasco', 'Perfeito para os churrasqueiros que preferem assar na grelha, o Pegador para Churrasco é um item indispensável. Resistente, é produzido em aço inoxidável e seu cabo em madeira prolongado tem formato anatômico, conferindo ainda mais firmeza e garantindo mais segurança durante o manuseio dos alimentos na brasa. Ainda é possível pendurá-lo na sua cozinha ou junto à churrasqueira, tornando-o a facilidade que você necessitava para completar o seu churrasco!', 39.0, 39.0, NULL, 'Home & Living > Kitchenware > Grills & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824g7-mfbbjo31frwv28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23098952194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49156151164', 'Bíblia Diária | NVI | Leitura Perfeita | Tecido sobre capa dura Cinza', 'A Bíblia Diária é um convite às maravilhas da leitura da Palavra de Deus todos os dias. Nela, você encontra o texto bíblico dividido em porções do Antigo Testamento, do Novo Testamento, e dos livros poéticos, como Salmos e Provérbios, intercalados. Além disso, ela conta com o diferencial de um texto devocional sobre as leituras de cada dia, que serve como uma preparação para a porção que você lerá. É a Bíblia perfeita para acompanhar você todos os dias, pois ajudará a desenvolver profundidade no relacionamento com o Pai.Aprofunde seu conhecimento, desfrute do aprendizado da Palavra e receba uma porção do céu diariamente. Características que se destacam: • Texto revisado da Nova Versão Internacional (NVI). • Fonte Leitura Perfeita, uma tipologia exclusiva Thomas Nelson que promove conforto na leitura. • Texto bíblico organizado por dias do ano, com diagramação própria para textos poéticos e diálogos assinalados com travessões. • Textos diários não datados, para você escolher o melhor dia para iniciar sua leitura. Editora: Thomas Nelson Brasil Acabamento: Capa Brochura Dimensões: 16x20 Número de páginas: 1328', 89.9, 89.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8261m-mkmj0ebhwumb82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F49156151164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
