INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293890812', 'Creme de Pentear para Cachos Explosão de Hialurônico 800g bn.Cachos', 'O Creme de Pentear Explosão de Hialurônico conta com a tecnologia de nanopartículas do ácido hialurônico, que age dentro da fibra capilar promovendo regeneração e hidratação duradoura, além de garantir um cabelo macio, hidratado e com muito brilho! Controla o frizz e o ressecamento. devolvendo elasticidade e movimento para os fios opacos e quebrados. Efeito condicionante. Uma explosão de hidratação para cachos e crespos ainda mais perfeitos!_x000D_ _x000D_ MODO DE USAR: Espalhe o pentear uniformemente por todo o cabelo úmido. Para desembaraçar, use um pente de dentes largos. Caso você queira mais definição, amasse os fios com as mãos em forma de concha._x000D_ _x000D_ Ingredientes_x000D_ ÁGUA PURIFICADA, ÁLCOOL CETOESTEARÍLICO, ÓLEO MINERAL, SORBITOL, VASELINA SÓLIDA, MONOESTEARATO DE GLICERILA, GLICEROL, CLORETO DE BERRENILTRIMÔNIO, CLORETO DE CETRIMÔNIO, FENOXIETANOL, FRAGR NCIA (ALFA-ISOMETIL IONONA, SALICILATO DE BENZILA, CUMARINA, HEXIL CINAMAL, LIMONENO, LINALOL), ÁLCOOL ETÍLICO, ÁLCOOL ISOPROPÍLICO, EDETATO DISSÓDICO DI-HIDRATADO, ETILHEXILGLICERINA, HIETELOSE, ACETATO DE SÓDIO, ÁCIDO CÍTRICO, ÁCIDO HIALURÔNICO HIDROLISADO, CELULOSE MICROCRISTALINA, BENZOATO DE SÓDIO, SORBATO DE POTÁSSIO.', 42.99, 41.99, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7repm-m80n75xy4uc10b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F22293890812', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099608603', 'Revestimento Impermeabilizante Cimentício Viaplus 1000 18KG Viapol', 'Revestimento impermeabilizante, semi-flexível, bicomponente (A+B), à base de cimentos especiais, aditivos minerais e polímeros de excelentes características impermeabilizantes. Vantagens • Resistente às altas pressões hidrostáticas, tanto positivas quanto negativas. • Resiste até 60 m.c.a.(metros de coluna d’água). • Apresenta ótima aderência e resistência mecânica. • Não altera a potabilidade da água, sendo atóxico e inodoro. • Produto de fácil aplicação, com trincha ou vassoura de pelo. • Aplicado sobre superfícies de concreto, alvenaria e argamassa. • Permite assentamento direto de revestimentos sem a necessidade de proteção mecânica no caso de banheiros, cozinhas e lavanderias sem cota. Marca: Viapol Ambiente indicado: Internos e Externos Superfícies indicadas: Utilizado para impermeabilização de subsolos, cortinas, poços de elevadores, muros de arrimo, baldrames, paredes internas e externas, pisos frios em contato com o solo, reservatório de água potável (não elevado), piscinas em concreto enterradas e estruturas sujeitas a infiltração do lençol freático. Indicado como revestimento sobre contra piso antes de receber o assentamento de pisos cerâmicos Linha: Impermeabilizante Viaplus Modelo: Viaplus 1000 Tipo: Impermeabilizante Volume da embalagem: 18 KG Rendimento acabado (18 KG): • Umidade de solo ou água de percolação - 6 m² a 9 m² • Pressão hidrost. positiva. no mínimo 25 m.c.a - 4,5 m² a 6 m² • Pressão hidrost. negativa até 10 m.c.a. - 3,6 m² a 4,5 m² Secagem ao toque: 30 minutos Secagem entre demãos: 2 a 6 horas Secagem final: 5 dias É inflamável? Não Ferramenta indicada para aplicação: Trincha ou vassoura de pelo. Temperatura mín./máx. de aplicação: 10ºC a 35ºC Consumo: • Umidade de solo ou água de percolação 2 kg/m² a 3 kg/m² • Pressão hidrostática positiva até 25 m.c.a. 3 kg/m² a 4 kg/m² • Pressão hidrostática negativa no máximo 10 m.c.a. 4 kg/m² a 5 kg/m² Prazo de Validade (embalagem fechada e sem uso): 9 meses a partir da data de fabricação nas embalagens originais e intactas, em local coberto e seco, ventilado e longe de fontes de calor. A temperatura máxima para armazenagem é de 30ºC. Impermeabilizante 01 Revestimneto Impermeabilizante Cimentício Viaplus 1000 18KG Viapol', 68.88, 60.0, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-7rceq-m6ir0d3m7mvd86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1425275679%2F21099608603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
