INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997748376', 'Violão Giannini Gf-1d Elétrico Folk Brown Red Capa Reforçada', 'Somos a Eletromusic Loja Especializada a mais de 10 anos no Mercado. Qual é o nosso diferencial? Buscamos sempre oferecer qualidade com excelência por isso todos os nossos produtos são de Fornecedores Nacionais com rigoroso controle de qualidade, possuem nota fiscal eletrônica e garantia de fabrica. Você é bem vindo para fazer parte da nossa história. Violão Aço Eletroacústico Giannini Performance GF-1D CEQ Brown Red Burst (BRB) ACOMPANHA: -01 CAPA REFORÇADA EM NYLON 600 -03 PALETAS Tampo: Agathis Lateral e Fundo: Agathis Braço: Okoume com tensor bi-direcional Escala: Techwood Comprimento da escala: 648 mm (25,5”) Cavalete: Walnut maciço Tarraxa: Blindadas cromadas, 3+3 Pestana: ABS Largura da pestana: 43 mm (1,7”) Rastilho: ABS Largura do rastilho: 72 mm (2,83”) Equalizador: GN-3T, ativo 3 bandas com afinador, saída P-10 Acabamento: Verniz brilhante Cordas: Aço .011. Recomendamos para a troca os encordoamentos Giannini Acústico GESPW, Giannini Cobra GEEFLK, CA82SL e GEEFLKF Headstock: Logo “Giannini Performance” na cor prata com decorativo, placa adicional em agathis fosco Largura da caixa: 403 x 297 mm Altura da caixa: 100 x 120 mm Tamanho total: 103 cm (40,55”) Acompanha: Chave de ajuste do tensor, bateria 6F22 9V', 948.68, 948.68, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > String Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rd3x-lwydp9aw2ceg79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F20997748376', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499308526', 'ABA ASA TANQUE FAN 160 PRETO 22/23', 'A Sportive, empresa líder em peças plásticas para motocicletas com mais de 20 anos de atuação no mercado de moto peças, desenvolve seus produtos para atender as necessidades do exigente mercado de reposição 2 rodas. Nossos produtos buscam atender o público que procuram por um produto de qualidade com baixo custo. Especificações técnicas : • Marca: Sportive; • Não acompanha Parafusos ou Presilhas; • Observação: A cor (tonalidade) segue os mesmos padrões da Moto, Modelo e Ano Original; • Segue todos os padrões Originais (sem adaptações). Instalação: • A instalação deve ser feita por um profissional especializado. não se responsabiliza por instalação mal realizada. ABA TANQUE - FAN 160 PRETO 22/23', 109.82, 109.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdvt-lyaxapigabfmad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F362325018%2F19499308526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
