INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259907809', 'Liquidificador LN64 Power Max *2200W*JARRA 3,1 Litros Arno', 'O Liquidificador Arno Power Max LN64 a escolha ideal para quem busca potência, versatilidade e praticidade na cozinha. Com alto desempenho, ele facilita o preparo de diversas receitas, desde sucos e vitaminas até misturas mais elaboradas. Suas múltiplas velocidades permitem ajustar a intensidade conforme a necessidade, enquanto recursos como a função pulsar e triturador de gelo garantem mais eficiência no dia a dia. O copo com grande capacidade e tampa com dosador tornam o uso ainda mais prático, e o Mini Chopper incluso amplia as possibilidades de preparo, tornando este liquidificador um verdadeiro aliado na rotina culinária. Características: Modelo: Power Max LN64 Potência: 2200 W com o acessório Mini Chopper, 600W sem o acessório Mini Chopper Capacidade útil: 3,1 L Velocidades: 15 Função pulsar: Sim Função triturar gelo: Sim Função limpeza: Sim Comprimento do cabo: 100 cm Registro no INMETRO: UL-BR 25.0904 Conteúdo da Embalagem: 01 Liquidificador 01 Manual de Instrues 01 Certificado de Garantia Dimensões: Altura: 43 cm Largura: 22,6 cm Profundidade: 21,8 cm Peso: 1,88 kg Garantia do Fabricante: 12 Meses', 313.4, 282.06, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/br-11134207-820m0-mq7z77iymcqq6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F745165277%2F58259907809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43012331223', 'Painel Redondo 3 Palavrinhas Capa Painel Decoração Festa Em Tecido Sublimado C/Elástico - Licenciado', '>>> PAINEL REDONDO EM TECIDO COM ACABAMENTO EM ELÁSTICO <<< UTILIZAÇÃO EM ESTRUTURAS CIRCULARES ENTRE 1,20 ATÉ 1,50 DE DIÂMETRO. >>> PAINEL NÃO POSSUI EMENDA!!! Com impressão de alta qualidade, cores vivas, imagens nítidas e acabamento perfeito, o painel redondo da Criatema é o detalhe perfeito para ter resultado incrível em sua decoração, com ótimo custo x benefício. DETALHES DO PAINEL EM TECIDO: >>> Tecido Malha New (Que estica e não amassa). >>> Tecido Leve com ótimo caimento >>> Gramatura: 140g/m de excelente qualidade. >>> Composição do Tecido: 95% Poliéster e 5% de Elastano. >>> Elástico costurado ao redor do painel. >>> Acabamento em overloque evitando que o painel desfie. PORQUE ESCOLHER O PAINEL SUBLIMADO DA CRIATEMA: >>> Melhor opção para quem procura ótimo custo x benefício >>> Não amassa (por ser feito em tecido especial. Bem melhor do que os de lona) >>> Não desbota, por ser sublimado em tecido >>> Pode ser lavado quantas vezes desejar >>> Seca rapidamente depois de molhado >>> Pode ser passado (recomendamos não usar alta temperatura) >>> Instale na estrutura circular em alguns minutos >>> Sua decoração muito mais cheia de vida >>> Alta durabilidade >>> Não reflete luz na hora das suas fotos PRAZO DE PRODUÇÃO E ENVIO: - TODOS OS PEDIDOS ACOMPANHAM NOTA FISCAL. - Os nossos painéis são produzidos e postados em até 1 DIA ÚTIL após pagamento aprovado. - Nosso painel possui garantia contra defeito de fabricação.', 89.9, 62.9, NULL, 'Home & Living > Party Supplies > Backdrops & Banners', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdarotn0vk8i54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F4301233122