INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697098562', 'Kit Hidratei Shampoo e Condicionador + Super Máscara 250g', 'Shampoo: O Shampoo Hidratei é o shampoo perfeito para todo o tipo de cabelo. Ele fornece o cuidado perfeito para os seus fios. Hidrata e limpa na medida certa. Possui em sua composição ácido hialurônico, blend de óleos poderosos e pantenol que evitam danos causados pela lavagem. Assim você terá um couro cabeludo mais saudável e cabelos macios, hidratados e protegidos. ● PH equilibrado entre 5,5- 6,5. Condicionador: O Condicionador Hidratei promove um condicionamento efetivo em todos os tipos de cabelos. Para isso, ele contém ativos altamente condicionantes, umectantes, nutritivos e emolientes. Seus fios revitalizados, mais hidratados, brilhantes e macios! ● Livre de parabenos, petrolatos e corantes sintéticos. ● PH de 3,5 a 4,5. Super Máscara 250g: A Máscara Hidratei foi formulada com o objetivo de hidratar e nutrir profundamente os fios de maneira prática e eficaz. Especialmente desenvolvida com ácido hialurônico, óleo de buriti, manteigas de murumuru e cupuaçu.', 419.7, 249.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7thpfn8qsgk04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555452587%2F22697098562', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
