INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25544766183', 'Cronograma Capilar SOS Cachos', 'O kit contém shampoos e condicionadores S.O.S Cachos nas versões Super Óleos, Óleo de Coco e Óleo de Manga, ideais para nutrir, hidratar e definir os cabelos cacheados e crespos, deixando-os mais saudáveis, macios e brilhantes. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos Ondulados, Cacheados e Crespos. Qual a indicação? Cabelos desnutridos, sem brilho, sem definição, com frizz, ressecados. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Kit Shampoo + Condicionador SOS Cachos Óleo de Manga Óleo de manga: rico em vitaminas para o cabelo e sais minerais, os benefícios da manga incluem ação hidratante e nutritiva, fortalecimento dos fios, brilho intenso e cabelos macios. Queratina: excelente para uma reconstrução capilar profunda, devolve os nutrientes que o cabelo perde ao longo do tempo. Kit Shampoo + Condicionador SOS Cachos Super Óleos A combinação entre os óleos de Coco, Argan, Karité, Macadâmia, Oliva, além de outras sementes, ervas e frutos, promove ação nutritiva, pois atua nas camadas mais profundas das fibras capilares, repondo seus nutrientes, garantindo brilho e vitalidade. Kit Shampoo + Condicionador SOS Cachos Óleo de Coco Óleo de coco: rico em vitaminas e ácidos graxos, hidrata e nutre, além de fortalecer os fios, proporcionando brilho e maciez. Manteiga de coco: possui ácidos graxos, ideal para restaurar o cabelo danificado. Além disso, é um excelente hidratante natural, com extrema capacidade umectante, proporcionando força e brilho aos fios. <>MODO DE USO$& Qual a melhor forma de usar? Kit Shampoo + Condicionador SOS Cachos Óleo de Manga, Kit Shampoo + Condicionador SOS Cachos Super Óleos, Kit Shampoo + Condicionador SOS Cachos Óleo de Coco Shampoo SOS Cachos Aplique o shampoo no cabelo úmido, massageie e enxágue. Se necessário, repita a aplicação. Condicionador SOS Cachos Aplique o produto no cabelo úmido e espalhe uniformemente. Deixe agir entre 1 e 3 minutos. Enxágue bem por toda a extensão dos fios. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos são veganos. É liberado? Nenhum dos produtos são liberados.', 93.0, 88.84, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rffq-m95z7n50ueuhec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F25544766183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18999303253', 'Cápsulas Café L''OR Ristretto Decaffeinato 10 Un', 'CARACTERÍSTICAS DO BLEND Um blend que contrasta notas doces e refinadas de marzipã com uma explosão cítrica. O sabor e o aroma dessa cápsula de café se aliam para criar uma sinfonia de sensações em uma experiência verdadeiramente intensa. Elaborado pelos Artistas do Café L\''OR. PERFIL AROMÁTICO E SABOR O Perfil do Ristretto Decaffeinato é marcado por suas notas amadeiradas e de amêndoas. HARMONIZAÇÃO Este blend pode ser perfeitamente harmonizado com biscoitos amanteigados ou doces a base de creme.', 29.9, 29.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/sg-11134201-7rdxw-lxcoccwvzht5fa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281578116%2F18999303253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093143087', 'Café Torrado e Moído L''OR Intenso 250g', 'CARACTERÍSTICAS DO BLEND Aprecie L\''OR Intenso, um café torrado e moído encorpado, de acidez leve e com uma torra acentuada que irá despertar os seus sentidos. Surpreenda-se com as sensações únicas que diferentes intensidades de torra podem proporcionar.', 27.9, 27.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mefq668n6e4hc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281578116%2F22093143087', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9586056039', 'Pastilha de Freio GTA P08- Resina 8765', 'Pastilha de Freio GTA P08- Resina 8765 Pedale com frenagens eficientes e seguras com a Pastilha de Freio GTA P08. Ideal para o uso urbano ou de diferentes modalidades de mountain bike (mtb), oferece composição reisinada, é indicada para o uso em situações de maior regularidade de uso, esquentando menos e garantindo mais eficiência nas frenagens mais longas e contínuas. A composição da Pastilha de Freio GTA P08- Resina 8765, permite que os atritos contra os discos de freios seja minimizada, garantindo assim, muito mais durabilidade para seu sistema de freios. Especificações da Pastilha de Freio GTA P08- Resina 8765 - Alta compatibilidade - pode ser utilizada com os mais variados modelos de freios - Tipo Shimano; - Composição orgânica - mais eficiência nas frenagens longas e contínuas, gerando menos calor e mais eficiência.', 14.7, 14.7, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/477b1fa21b708087a3f95dc144fab5f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F9586056039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
