INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697458025', 'Válvula Termostática Fiat Punto 2008 a 2016 - 842210 - AVTS03001T87', 'Válvula Termostática Fiat Punto 2008 a 2016 842210 AVTS03001T87 1.4 8/16v - Kit = Flange + Válvula A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 56.37, 56.37, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7r99l-ln7jevbzn6x202', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19697458025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
