INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19998090528', 'Pré Filtro Combustível Vw Gol 2017 a 2025 - 1354483 - T040206', 'Pré Filtro Combustível Vw Gol 2017 a 2025 1354483 T040206 G7 1.6 8v Fire Flex - sistema Bosch - Copo, filtro externo e internoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 58.76, 58.76, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822wr-mo9uutg6kljd0b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19998090528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
