INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57504964782', 'Mesa de Apoio Oval G7003 com Pés em Metal', 'A Mesa de Apoio G7003 é a escolha perfeita para quem busca praticidade com design sofisticado. Seu tampo oval em MDP de 22 mm, a base metálica oferece estabilidade e um visual moderno. Compacta e funcional, é ideal para apoiar livros, bebidas ou objetos decorativos ao lado do sofá ou poltrona. Um toque de estilo que faz toda a diferença no seu ambiente. Modelo: Mesa de Apoio G7003; Formato do móvel: Oval; Material do tampo: MDP de 22mm; Material dos pés: metal; Dimensões: 31 cm(L) x 63,3 cm(A) x 44,5 cm(P); Peso suportado: até 5 kg distribuídos; Requer montagem: Sim (kit montagem incluso); Embalagem do envio: Papelão e plástico. Tonalidade de Cores: Preto: Fosco; Nature: Fosco. Informações adicionais: - Os objetos que ambientam as fotos não acompanham o produto; - É de inteira responsabilidade do cliente a montagem do produto e/ou instalação, assim como possíveis irregularidades provenientes de manuseio inadequado; - Embora o produto acompanhe o manual de montagem, verifique a complexidade antes de decidir montá-lo sozinho, recomendamos que contrate um profissional de sua confiança; - Fique atento, nossas cores podem sofrer alterações dependendo do seu monitor; - ANTES DE MONTAR O SEU PRODUTO, verifique se há alguma peça danificada, caso esteja, prestaremos a devida assistência dentro do prazo da garantia.', 179.99, 167.4, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-8260s-mjpxqr6ugzyafe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401986069%2F57504964782', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
