INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793959726', 'Filtro Óleo Renault Megane 2006 a 2013 - 509136 - WO200', 'Filtro Óleo Renault Megane 2006 a 2013 509136 WO200 (Grand Tour - Extreme / Dynamique / Privilége) - Motor 1.6/2.0 16v Hi-Flex - (Automático/Mecânico) - (Blindado) Basicamente, os filtros lubrificantes devem atender às funções de reter todos contaminantes que possam causar danos ao perfeito funcionamento do motor, mantendo as características de estrutura do óleo, uniformidade de circulação e eficiência no período de uso pelo motor. O Filtro do Óleo retém os contaminantes contidos no sistema de lubrificação, principalmente os abrasivos (metais) , provenientes do atrito das partes móveis do motor que permanecem em suspensão no óleo lubrificante.', 33.41, 33.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rfif-m9azixz2hytt35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22793959726', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898024176', 'Reparo Bico Injetor Vw Polo 2002 a 2008 - 515841 - 1203', 'Reparo Bico Injetor Vw Polo 2002 a 2008 515841 1203 1.6 8v - (Sistema Bosch/Rochester) (Multi Point) (4 Filtros + 8 O''rings) Tem a finalidade de evitar entupimento do bico injetor devido às impurezas e contaminações do combustível. Outra função é vedar a entrada falsa de ar no coletor de admissão evitando vazamentos. Ao fazer a limpeza do bico injetor, devemos trocar o(s) filtro(s) e os anéis, pois eles retêm as impurezas que diminuem o volume de combustível injetado provocando assim, algumas irregularidades como perda de potência, dificuldade na partida e funcionamento irregular do motor.', 38.12, 38.12, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7reos-m2f7mhwxo51xf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22898024176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
