INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792972086', 'Jogo Velas Ignição SCENIC 2000/2012 - 7763 - GV6R92', 'Jogo Velas Ignição SCENIC 2000/2012 MOTOR 2.0 16v ( F4R ) GASOLINA (Vela Resistiva) Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 58.58, 58.58, NULL, 'Automobiles > Automobile Spare Parts > Electronics', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-luffvzikgt2166', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22792972086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
