INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297672182', 'Filtro Gasolina OPALA 1968/1993 - 43660 - FCC2160', 'Filtro Gasolina OPALA 1968/1993 MOTOR 2.5/4.1 - (Comodoro / Diplomata) - Gasolina - Mecânico (PEQUENO BICO 6mm) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 14.62, 14.62, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rd5a-luf1wsl1h3tc28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20297672182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
