INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997981448', 'Máquina Para Assentar Piso A Bateria Com Ventosa 12V Vonder', 'Máquina para assentar piso a bateria, com ventosa, 12 V, MAP 125, VONDER Equipamento prático e eficiente, tornando a instalação rápida. Possui alto poder de sucção e vibração. Conta com 5 níveis para regulagem de vibração com identificação no display, proporcionando maior controle de acordo com a aplicação. Além de punho auxiliar, proporcionando maior facilidade e ergonomia no manuseio do equipamento. Indicada para assentar porcelanatos e pisos em geral. Usar a ventosa somente em pisos com superfície lisa. Para pisos até 100 cm x 100 cm. Bateria indicada para reposição: 93.24.120.001. Especificações Técnicas: Modelo: MAP 125 Potência do motor: 180 W Tipo de bateria: Íons de Lítio 12V - 2,2 Ah Diâmetro da ventosa: 145 mm Capacidade de carga: 50 kgf Número de vibrações por minuto (vpm): 1° nível: 1.500/min; 2° nível: 3.200/min; 3° nível: 4.200/min; 4° nível: 4.800/min; 5° nível: 6.000/min Tensão de saída da fonte: 12 V DC Tensão de entrada da fonte: 100 V~ - 240 V~ - Bivolt automático Tempo de carregamento: 2 horas Dimensões: 390 mm x 145 mm x 135 mm Nível de ruído (dB(A)): Sem carga: 60 dB(A) / Com carga: 80 dB(A) Aceleração transmitida nas mãos - braços do operador - ah: 1° nível: 32 m/s²; 2° nível: 53 m/s²; 3° nível: 75m/s²; 4° nível: 110 m/s²; 5° nível: 190 m/s² Incerteza da aceleração transmitida nas mãos - braços do operador - k: 1,5 m/s² Conteúdo Da Embalagem: 1 Máquina de assentar piso com ventosa. Acompanha: 1 maleta plástica, 1 bateria 12 V e 1 fonte bivolt automático.', 930.61, 704.05, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7renu-m1y5s4mi1w9s45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F93944