INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794068604', 'Kit garrafa de tinta Brother InkBenefit Tank BTD1002PK Preto com 2 unidades', 'Apresentamos o Refil para InkTank Preto BTD1002PK da Brother, uma solução eficiente para atender as suas necessidades de impressão do dia a dia. Ideal para quem busca qualidade e durabilidade, este refil promete resultados incríveis, permitindo que seus documentos ganhem vida com textos nítidos e gráficos impressionantes. Com ele, suas impressões se manterão sempre em alta resolução, sem comprometer a qualidade. A inovação do sistema InkTank da Brother proporciona maior economia e praticidade. O BTD1002PK é projetado para impressoras que exigem alta capacidade de tinta, garantindo que você imprima mais por menos. Com uma instalação simples e rápida, você não perderá tempo na hora de reabastecer sua impressora, permitindo que você se concentre no que realmente importa: criar, imprimir e compartilhar suas ideias e projetos. Detalhes: - Cor: Preto - Alta capacidade de impressão - Instalação fácil e rápida - Impressões de qualidade profissional - Este kit acompanha 2 garrafas de tinta preta de ultra rendimento (BTD100BK), que rendem até 7.500 páginas/cada. - Compatibilidade: DCPT230, DCPT430W, DCPT436W, DCPT530DW, DCPT730DW E DCPT830DW', 123.8, 119.9, NULL, 'Computers & Accessories > Printers & Scanners > Inks & Toners', 'https://cf.shopee.com.br/file/sg-11134201-7rave-mamqtu87slj771', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F23794068604', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
