INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12494338915', 'Bomba do Óleo - Ford KA / Fiesta / Ecosport / Focus / Escort / Courier - Zetec Rocam - Schadek 10210', 'CONTEÚDO DA EMBALAGEM: 01 BOMBA DO ÓLEO - SCHADEK CÓD. 10210 PRODUTO NOVO, ORIGINAL, COM GARANTIA E NOTA FISCAL. APLICAÇÃO: FORD COURIER 1.6 8V ZETEC ROCAM (1999-2013), ECOSPORT 1.0 8V SUPERCHARGER ZETEC ROCAM (2003-2006), ECOSPORT 1.6 8V ZETEC ROCAM (2003-2012), ESCORT 1.6 8V ZETEC ROCAM (2000-2003), FIESTA 1.0 8V ZETEC ROCAM (1999-2014), FIESTA 1.6 8V ZETEC ROCAM (1999-2014), FIESTA 1.0 8V SUPERCHARGER ZETEC ROCAM (2002-2006), FIESTA STREET 1.0 8V ZETEC ROCAM (1999-2006), FIESTA STREET 1.6 8V ZETEC ROCAM (1999-2006), FOCUS 1.6 8V ZETEC ROCAM (2003-2009), KA 1.0 8V ZETEC ROCAM (1999-2014), KA 1.6 8V ZETEC ROCAM (2001-2014). ATENÇÃO: A RESPONSABILIDADE DA COMPATIBILIDADE DO PRODUTO E SUA APLICAÇÃO É DO COMPRADOR; NÃO NOS RESPONSABILIZAMOS POR PREJUÍZOS ADVINDOS DA APLICAÇÃO INCORRETA DO PRODUTO. CONSULTE O FABRICANTE DO SEU EQUIPAMENTO E CONFIRME A COMPATIBILIDADE COM O INSTALADOR. A MARTINS AUTOPEÇAS DISPÕE DE PEÇAS AUTOMOTIVAS PARA TODA A LINHA LEVE E MÉDIA DE VEÍCULOS, SE NÃO ENCONTRAR O QUE PROCURA, DEIXE UMA PERGUNTA E RESPONDEREMOS O MAIS BREVE POSSÍVEL.', 315.0, 315.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3w2dpgs0hy3f6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F538200526%2F12494338915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251213567', 'Gel Lubrificante Íntimo K-med Hot 50g', 'Gel Lubrificante Íntimo K-Med Ice 50g: Aquecimento e Prazer K-Med Hot é um lubrificante íntimo com efeito de aquecimento suave que desperta novas experiências na relação sexual. Com uma formulação mais fluída, pensada para aumentar a temperatura e deixar o que é bom ainda melhor. Para um sexo prazeroso, gostoso e deslizante. Lubrificante à base de água que oferece sensação de aquecimento suave e efeito quente para intensificar o prazer durante o contato íntimo. Dermatologicamente testado, é seguro para uso com preservativos de látex e indicado para quem busca inovação e conforto na hora do prazer. Ideal para casais que desejam explorar novas experiências ou para pessoas que valorizam uma lubrificação eficaz com um diferencial sensorial. Diferenciais: - Efeito Hot (aquecimento): estimula os sentidos e intensifica o prazer - Base aquosa: fácil de limpar, não mancha e não gruda - Dermatologicamente testado: seguro para uso íntimo - Compatível com preservativos: não compromete a proteção - Unissex: pode ser usado por qualquer pessoa Como Usar o Gel Lubrificante Íntimo K-Med Hot? K-Med Hot pode ser aplicado ao redor da superfície da vagina, diretamente no órgão genital ou no preservativo. Uso com preservativo: colocar o preservativo em seguida, aplicar K- Med Hot sobre o preservativo ou diretamente na área a ser lubrificada. Potencialize a Experiência com o Gel Lubrificante Íntimo K-Med Hot com Brinquedos K-Toys: - Vibrador de Ponto G e Clitóris K-Toys K-Med Entra y Vibra 1 Unidade - Anel Peniano K-Med K-Toys Sex Education 1 Unidade - Plug Anal Sex Toy K-Med K-Toys Plug-In 1 Unidade - Massageador de Silicone K-Toys K-Med Magic Mexe 1 Unidade - Estimulador de Clitóris Sex Toy K-Med K-Toys Suga Baby 1 Unidade Perguntas Frequentes: 1. O K-Med Hot pode ser usado com preservativo? Sim, ele é compatível com preservativos de látex, garantindo proteção e prazer. 2. Posso usar o gel mais de uma vez na mesma relação? Sim, você pode reaplicar sempre que sentir necessidade. 3. Ele é comestível? Não. Este gel não é comestível. Evite ingestão. O Gel Lubrificante Íntimo K-Med Hot 50g é a escolha ideal para quem deseja sensações únicas, conforto e segurança nos momentos íntimos.', 35.73, 35.73, NULL, 'Health > Sexual Wellness > Lubricants', 'https://cf.shopee.com.br/file/sg-11134201-8226e-mhma694lzcowa9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F58251213567', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
