INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294017856', 'Micro-ondas Electrolux 20L Branco com Função Tira Odor e Descongelar (MTO30)', 'O micro-ondas 20 litros Electrolux MTO30 oferece alta potência para elevar o preparo de diferentes pratos. Com classificação energética A, o modelo promove maior eficiência no consumo de energia e conta com painel inteligente com funções que facilitam o preparo dos alimentos e a limpeza, como as receitas pré-programadas e a função tira odor. Tudo isso com design compacto e moderno, que combina com diferentes estilos. Tecnologias do micro-ondas 20 litros Electrolux Equipado com as melhores tecnologias, o micro-ondas 20 litros branco facilita o preparo das suas receitas. Alta potência: prepare receitas com mais rapidez com o micro-ondas de 1300W de potência; Aquecer Prato Pronto: acione a tecla para aquecer uma refeição pronta e deixá-la na temperatura ideal para servir; Função Manter Aquecido: mantenha o prato aquecido até o momento de servir para uma refeição com mais qualidade e sabor; Função Mudo: aperte a tecla 0 por 4 segundos e o som do “bip” desaparece, com mais silêncio e bem-estar para a sua cozinha; Função Relógio: ganhe facilidade na rotina com o mostrador de horário disponível no painel do micro-ondas; Função Tira Odor: mantenha seu micro-ondas mais fresco e higiênico com a função que minimiza os odores deixados pelos alimentos; Menu Descongelar: descongele carne, frango, peixe e feijão com apenas uma tecla e a temperatura e tempo ideais para o preparo; Menu Dia a Dia: faça as receitas mais comuns da rotina, como arroz, macarrão e batata, com mais praticidade e apenas um toque no painel; Menu Kids: prepare as receitas favoritas das crianças com o tempo e a temperatura ideais: bolo de caneca, pipoca e brigadeiro; Menu Light: cozinhe receitas saudáveis com facilidade no menu light, que inclui sopas, frutas e vegetais; QR Code com receitas: acesse o QR code no produto e confira o passo a passo do modo de preparo das receitas do painel; Tecla início/+30s: acione o micro-ondas com um único toque e programação de tempo rápida e descomplicada; Tecla potência/porções: escolha a potência e a quantidade de alimentos para um preparo no ponto ideal; Trava de segurança: trave o acionamento do aparelho e promova mais segurança para as crianças na cozinha.', 569.0, 549.0, NULL, 'Home Appliances > Kitchen Appliances > Microwaves', 'https://cf.shopee.com.br/file/sg-11134201-7rfg8-m9yiu770vpxy07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F23294017856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
