INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199285386', 'Parabarro Dianteiro Jetta 2011 2012 2013 2014 2015 Plástico de Alta Resistência Lameiro', 'RENOVE A PROTEÇÃO E O ACABAMENTO DO SEU VEÍCULO O parabarro dianteiro é uma peça essencial para proteger a parte interna do para-lama contra sujeira, lama, água e detritos da estrada, além de contribuir para a conservação do conjunto de suspensão e acabamento do veículo. Este parabarro dianteiro para Volkswagen Jetta foi desenvolvido em plástico de alta resistência, garantindo encaixe sob medida e reposição direta no padrão original. PRINCIPAIS BENEFÍCIOS: Protege a estrutura interna do veículo contra sujeira e detritos Reposição ideal para parabarros danificados ou ausentes Fabricado em plástico resistente, indicado para uso automotivo Encaixe preciso, sem necessidade de adaptações Mantém o padrão original de acabamento do veículo CARACTERÍSTICAS DO PRODUTO: Produto novo de ótima qualidade Fabricado em plástico resistente Acabamento perfeito Não acompanha presilhas nem kit de fixação Cor preta OPÇÕES DE LADO: Lado direito (passageiro) Lado esquerdo (motorista) Valor anunciado referente à unidade ESPECIFICAÇÕES TÉCNICAS: Substituição direta no local da peça original Compatível com padrão original de encaixe e medidas COMPATÍVEL COM OS MODELOS: Jetta 2011 Jetta 2012 Jetta 2013 Jetta 2014 Jetta 2015 INSTALAÇÃO: A instalação deve ser realizada utilizando os pontos originais do veículo. Recomenda-se que a montagem seja feita por um profissional especializado. Não nos responsabilizamos por instalação mal realizada. CONTEÚDO DA EMBALAGEM: 01 Parabarro Dianteiro para Volkswagen Jetta (conforme lado escolhido) PERGUNTAS FREQUENTES (FAQ) O parabarro encaixa perfeitamente no Jetta? Sim. O produto segue o padrão original de encaixe dos modelos compatíveis, não exigindo adaptações. O anúncio refere-se ao par ou à unidade? O valor anunciado é referente a uma unidade. É necessário selecionar o lado desejado. O produto acompanha presilhas ou kit de fixação? Não. As presilhas e o kit de fixação não acompanham o produto. O material é resistente? Sim. O parabarro é fabricado em plástico de alta resistência, adequado para uso automotivo. É recomendado instalar por conta própria? A instalação é simples, porém recomenda-se que seja feita por um profissional para garantir fixação correta e segurança.', 130.0, 126.24, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Mud Flaps', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mja2r01p19mu3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1645878596%2F22199285386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799664856', 'Aparelho de Depilar Gillette Venus Suave 2 Unidades', 'O Aparelho de Depilar Gillette Venus Suave contém fita lubrificante com um toque de aloe vera para um melhor deslizamento, que te proporciona uma depilação suave com menos irritação. A cabeça móvel se ajusta perfeitamenta ás curvas do seu corpo e suas três lâminas proporcionam uma depilação rente e macia por mais tempo. Para uma experiência incrível, use o Gel de Depilação Gillette SatinCare. Minha pele, do meu jeito. - Três (3) lâminas Gillette; - Fita Lubrificante com um toque de aloe vera para facilitar o deslizamento; - Depilação confortável para pele sensível; - Pele macia com menos irritação; - Cabeça móvel;', 35.73, 35.73, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd44-m76ucorjlfdt00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F19799664856', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
