INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898876456', 'Escova Dental Oral-B Indicator Plus 30 - 2 Unidades', 'Escova com sistema de cerdas Indicator®, com pontas arredondadas, que sinaliza o momento ideal da troca da escova e possui cabo emborrachado que permite maior conforto durante a escovação (Cabo é Comfort Grip). -Gentis com seus dentes e gengivas -Cerdas Indicator® que sinaliza o momento ideal da troca da escova -Cabo emborrachado que permite maior conforto durante a escovação -Contém 2 Unidades -Tamanho 30 Macia', 36.32, 36.32, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-824j8-mefyg63gym1273', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23898876456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098326413', 'Protetor Solar Facial Neutrogena Sun Fresh Derm Care Pele Mista a Oleosa FPS30 40g', 'Neutrogena Sun Fresh Derm Care Facial FPS 70 possui textura levinha e sequinha que não derrete. A excluisva tecnologia HELIOPLEX®XP oferece muito alta proteção ampla e eficaz contra os raios UVB, UVA e ajuda a proteger contra a luz visível.', 108.24, 108.24, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-7rd72-m770lykdvul7b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23098326413', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298545978', 'Amend Specialist Blonde Máscara Matizadora 300g', 'Amend Specialist Blonde Máscara matizadora para cabelos loiros descoloridos e com mechas. Amend Specialist Blonde Máscara Matizadora neutraliza o tom e deixa um brilho platinado saudável, com muita maciez. Também traz ativos que nutrem e protegem os fios. Amend Specialist Blonde Máscara Matizadora possui alta concentração de pigmentos violetas que eliminam o amarelado ou alaranjado do cabelo. Ainda fortalece a fibra capilar e recupera a resistência e o brilho. Seu loiro ganha um tom platinado incrível e com muita saúde. Conselho de Aplicação Depois de usar o shampoo, retire o excesso de água com uma toalha e aplique a máscara do comprimento às pontas. Deixe agir de 1 a 5 minutos, de acordo com o quanto os fios estiverem amarelados. Verifique sempre a cor do cabelo durante o uso. Quando atingir a nuance desejada, enxágue completamente.', 80.7, 67.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7raut-ma4h9l0p2gem03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F22298545978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
