INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204057338', 'Macaquinho Mykonos Estampa Onça Rosa Poliamida Com Bojo', 'Macaquinho Mykonos Estampa Onça Rosa | Funcional e Elegante Conforto e essencial O Macaquinho Mykonos Onça Rosa foi desenvolvido para oferecer conforto, estilo e praticidade. Apresenta corte reto, com costura pespontada ao centro por toda a peça e outra abaixo do busto, criando um efeito alongador na silhueta. Conta com alças finas e reguláveis para melhor ajuste e conforto, além de forro na região do busto Características Principais Costura abaixo do busto - Efeito alongador Bojo Removível - Flexibilidade para adaptar conforme preferência Costura Reforçada - Durabilidade durante os movimentos Design Exclusivo Alças Finas e Reguláveis - Personalização do ajuste para máximo conforto e suporte Decote em "U" - Toque moderno e feminino Estampa Animal Print Rosa - Padrão felino vibrante POSSUI FORRO NA REGIÃO DO BUSTO NÃO POSSUI FORRO TRASEIRO COMPRE AGORA - Estilo e conforto garantidos para todos os momentos', 144.33, 144.33, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Others', 'https://cf.shopee.com.br/file/sg-11134201-8261e-mjy99j62rc3l55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1576910750%2F58204057338', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
