INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897320718', 'Sensor De Estacionamento Ré Visor Slim Nissan March Todos', 'Sensor de Estacionamento 4 Pontos Cores Preto, Prata ou Branco Display LED Colorido Chega de sofrer na hora de fazer baliza, com esse Sensor de Estacionamento de 4 pontos você vai conseguir colocar seu carro até naquelas vagas mais apertadas, ou então deixar seu carro bem centralizado no estacionamento do prédio ou do shopping. Os sensores ficam super discretos no para-choque traseiro do seu carro e o produto já vai completo para instalação, incluindo chicotes, central, serra no tamanho ideal para realizar as furações e o display digital que vai ao painel do carro e alerta sobre o nível de proximidade dos obstáculos conforme eles se aproximam. Cor Disponível: - Preto - Prata - Branco OBS: As cores que não estiverem disponíveis não aparecerão no botão comprar do anúncio. Especificação Técnica: - Modelo Universal - Pode ser Pintado na Cor do seu Veículo (Não Realizamos Pinturas) - Sensores Ultrassônicos com Exata Precisão de Distância entre Veículos e Obstáculos - Confirmação de Instalação Adequada - Operam Normalmente com Quaisquer Condições Climáticas - Sistema Ativado Automaticamente Quando Acionada a Ré - Identificação de Obstrução ( Da Esquerda e da Direita) - Auto Inspeção de Função: o Display irá Mostrar Qual o Sensor está Quebrado, ou se um não Funciona Quando se Inicia - Tensão Nominal: 12V - Faixa de Voltagem Operacional: 10,5 ~200 mA - Distância de Detecção: 0,5 ~1,0 m - Frequência Ultrassônica: 40 KHz - Temperatura de Trabalho da Caixa de Comando: -30 ~+80°C - Medidas Aproximadas do Sensor (D. Int. x D. Ext.): 1,3x2,1 cm - Medidas Aproximadas do Display (CxA): 10x2 cm OBS: Em veículos com para-choque de ferro, é necessário isolar os sensores com uma leve camada de borracha para que não haja interferência. Conteúdo da Embalagem: - 4 Sensores - 1 Display Digital - 1 Central - Cabos para Instalação - Serra Copo Importante: - Valor do Kit. - Imagens Meramente Ilustrativas. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 98.93, 98.93, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lr7gwc8z8lxpac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414508631%2F22897320718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
