INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19355107669', 'COPO ACRÍLICO SANTA CEIA MINI 10 ML – 100 A 500 UNIDADES', '🥃 COPO ACRÍLICO SANTA CEIA MINI 10 ML – 100 A 500 UNIDADES✝️ 💎 ESCOLHA A QUANTIDADE DESEJADA NA VARIAÇÃO DO ANÚNCIO! 🎉 PERFEITO PARA SANTA CEIA, EVENTOS RELIGIOSOS, COMUNHÕES OU DEGUSTAÇÕES! O COPO ACRÍLICO MINI DE 10 ML TRAZ PRATICIDADE, HIGIENE E UM TOQUE DE SOFISTICAÇÃO PARA CELEBRAÇÕES ESPECIAIS. RESISTENTE E TRANSLÚCIDO, É UMA OPÇÃO FUNCIONAL E DISCRETA PARA MOMENTOS DE FÉ E COMUNHÃO. 🙏🍷 📦 DETALHES DO PRODUTO: 🔹 QUANTIDADE: DE 100 A 500 UNIDADES (ESCOLHA NA VARIAÇÃO DO ANÚNCIO) 🔹 MODELO: MINI COPO PARA SANTA CEIA 🔹 CAPACIDADE: 10 ML 🔹 MATERIAL: ACRÍLICO TRANSPARENTE DE ALTA QUALIDADE 💡 INDICADO PARA: ✝️ CELEBRAÇÕES DE SANTA CEIA 🛐 EVENTOS RELIGIOSOS E CULTOS 🍮 DEGUSTAÇÕES OU AMOSTRINHAS GOURMET 🎁 LEMBRANCINHAS EM MINIEVENTOS ⚠️ ATENÇÃO: 📷 IMAGENS ILUSTRATIVAS – NÃO ACOMPANHA LÍQUIDOS OU ACESSÓRIOS 📦 A QUANTIDADE SERÁ CONFORME ESCOLHIDO NA VARIAÇÃO DO ANÚNCIO ⏳ CONFIRA O PRAZO DE ENVIO NO ATO DA COMPRA 🔎 CONFIRA MAIS ITENS PARA FESTAS E EVENTOS EM “VER MAIS PRODUTOS DESSE VENDEDOR” 🛒 🚀 COPO ACRÍLICO 10 ML – PRATICIDADE E FÉ EM UM SÓ PRODUTO! 💖✝️🍷', 45.24, 45.24, NULL, 'Home & Living > Party Supplies > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98s-ll7uccrljbcscb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F19355107669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200109375', 'Jogo Kit Pontas Brocas Bits 68 Peças V-line Bosch Metal Com Maleta Completa', 'Distribuído por Ismafer Ferramentas Conjunto de Pontas e Brocas V-LINE 68 Peças com Maleta O Conjunto de Pontas e Brocas V-LINE 68 Peças da Bosch, é uma solução completa e versátil para todas as suas necessidades de fixação e perfuração. Composto por uma ampla variedade de pontas e brocas, esse conjunto oferece qualidade superior e desempenho excepcional para uma variedade de aplicações. Fabricado pela renomada marca Bosch, líder em ferramentas e acessórios, esse conjunto é construído com materiais de alta qualidade, garantindo durabilidade e resistência. As pontas e brocas são projetadas para suportar o uso intensivo, proporcionando resultados consistentes ao longo do tempo. Com 68 peças, esse conjunto abrange uma variedade de tamanhos e tipos de pontas e brocas, atendendo a diversas necessidades. As pontas incluídas abrangem os principais tipos de fixação, como pontas Phillips, pontas de fenda, pontas Tork e pontas hexagonais, entre outras. Além disso, as brocas são adequadas para perfurações precisas em diferentes materiais, como madeira, metal e concreto. A organização e o armazenamento das peças são facilitados pela caixa compacta incluída no conjunto. Cada item tem seu próprio espaço designado, o que permite um acesso rápido e fácil à ferramenta necessária, além de ajudar a evitar perdas ou danos. Seja você um profissional da construção, um entusiasta ou um usuário doméstico, o esse conjunto é uma escolha confiável. Com sua qualidade superior, variedade de peças e caixa organizadora, você terá as ferramentas certas ao seu alcance para lidar com qualquer projeto de fixação ou perfuração. Em suma, esse conjunto oferece qualidade, confiabilidade e versatilidade em um único pacote. Composto com 68 peças, é uma solução completa para atender às suas necessidades de trabalho. Invista nesse conjunto e experimente resultados precisos e eficientes em suas tarefas de fixação e perfuração, tornando seu trabalho mais fácil e produtivo. Especificações Técnicas: - Material: Metal - Comprimento: 22,5cm - Largura: 32,1cm - Altura: 7,1 cm Conteúdo da Embalagem: - 1 Barra magnética expansível - 1 Estilete - 1 A parafusadora angular - 8 Brocas para metal de 2 a 6 mm - 9 Brocas para pedra de 4 a 10 mm - 8 Brocas para madeira de 3 a 10 mm - 2 Brocas chatas de 16 a 20 mm - 29 Pontas a parafusadoras - 1 Suporte de pontas universal magnético - 6 Chaves de caixa - 1 Adaptador para chave de caixa - 1 Escareador Marca: Bosch Garantia do fabricante: 3 meses SKU: 25012 Distribuído por Ismafer Ferramentas', 299.0, 209.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh2f2t4copokb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617570446%2F58200109375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
