INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898209795', 'Jogo de Pontas e Brocas X-Line com 34 Peças e Maleta - BOSCH', 'O kit de pontas e brocas em titânio X-Line Bosch é um produto completo e ideal para quem busca praticidade para executar diferentes tipos de trabalho. O kit inclui uma variedade de pontas e brocas, além de diversos acessórios que auxiliam em aplicações de parafusamento, perfuração e fixação. O design das pontas foi desenvolvido para evitar o desgaste da cabeça dos parafusos trazendo maior firmeza durante as aplicações, e possuem o encaixe em formato hexagonal que evita o deslizamento na ferramenta. São acompanhadas também por um suporte universal magnético que possibilita trocas rápidas e a fixação segura das pontas. O kit possui um variado portfólio de brocas com diferentes diâmetros, sendo as de aço rápido em titânio para aplicações em metal, brocas com ponta de metal duro para perfurações em alvenaria e brocas de três pontas para aplicações em diferentes tipos de madeira. Os revestimentos de titânio nas brocas de aço rápido proporcionam maior velocidade e durabilidade durante as aplicações. Com sua ampla variedade de acessórios, o kit pode ser utilizado em diversas aplicações desde reparos, instalações e montagens, até pequenos trabalhos em obras, serralherias e marcenarias, além de acompanhar uma maleta robusta que facilita a armazenagem, transporte e acesso de todo o conteúdo de forma bastante organizada. Características Para parafusar, fixar e perfurar Kit completo e versátil para diferentes tipos de trabalho Mais desempenho para sua ferramenta. Design das pontas para parafusar evita o desgaste da cabeça do parafuso e seu encaixe hexagonal evita o deslizamento na ferramenta Possui suporte universal magnético que permite trocas rápidas e fixação segura das pontas Acompanha maleta robusta que permite o armazenamento e transporte prático de todos os acessórios Especificações Técnicas Dimensões da embalagem: 4,6 x 17,2 x 16,4 Conteúdo da Embalagem 1 Kit de pontas e brocas 1 Maleta Garantia 6 meses. Já incluso o período legal.', 128.99, 95.87, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcf2-m68atct83f0gf1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F22898209795', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297924995', 'Pasta Americana Arcolor 800g • Sabores Variados • Ideal para Cobertura e Modelagem', 'A Pasta Americana Arcolor une praticidade, sabor e acabamento profissional em uma só cobertura. Textura macia, fácil de abrir e modelar — ideal para confeiteiros que buscam beleza e sabor em cada criação. Peso líquido: 800g Textura: Macia, elástica e fácil de manusear Apresentação: Embalagem unitária Sabores: disponíveis (Morango, baunilha e Tutti-Frutti) Perfeita para bolos de aniversário, casamentos e doces personalizados. Indicada para confeiteiros profissionais e artesanais. • Não contém glúten. • Armazenar em local fresco e seco. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002.', 34.99, 34.99, NULL, 'Food & Beverages > Baking Needs > Baking Decoration', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0xdx20o7t5y3f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F22297924995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
