INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497560518', 'Cadeira Iguape Preta com Braços Suporta 154kg Piscina Praia Camping - Tramontina', 'Loja do Mecânico – O que você precisa, nós temos! A Cadeira Iguape Preta com Braços – Linha Basic da Tramontina é uma excelente opção para compor ambientes internos ou externos com praticidade e elegância. Seu design versátil e moderno combina com qualquer estilo de decoração, enquanto a estrutura ergonômica oferece mais conforto para o dia a dia. Fabricada em polipropileno de alta qualidade, é resistente, leve e fácil de limpar. Além disso, conta com certificação do Inmetro, garantindo mais segurança e confiabilidade no uso. Principais Características - Marca: TRAMONTINA - EAN: 7898187047931 - Cor: Preta - Com braços: Mais conforto e apoio - Material: Polipropileno - Design versátil: Ideal para áreas internas ou externas - Produto certificado conforme Portaria Inmetro nº 342/2014 - Capacidade de carga estática: 154 kg Cuidados de Uso - Limpar com pano macio levemente umedecido com água - Armazenar em local protegido quando não estiver em uso - Evitar exposição prolongada ao sol - Não subir no assento ou apoiar-se apenas nas pernas traseiras Benefícios - Conforto e praticidade em qualquer ambiente - Fácil de transportar e armazenar - Design atemporal, combina com diversos estilos - Garantia de qualidade Tramontina Importante - Garantia de 01 ano; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 88.99, 83.65, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-7rd4c-lw4ec9hw911806', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F22497560518', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202445476', 'Camiseta Térmica Segunda Pele Proteção UV50+ Verde Claro - Snugg', 'Encare o inverno com conforto e segurança com a Camiseta Térmica Segunda Pele Proteção UV50+ Verde Claro - Snugg, desenvolvida para quem precisa de proteção térmica eficiente, liberdade de movimento e um toque macio na pele. Ideal como camada base, essa peça é indispensável para dias frios, viagens internacionais, aventuras outdoor ou mesmo para o cotidiano no inverno. Tecnologia Térmica com Forro Flanelado, sendo fabricada com tecido leve e elástico. A camiseta conta com interior flanelado tipo pelúcia, que cria uma barreira térmica altamente eficaz, mantendo o calor corporal mesmo em ambientes de frio intenso. Sua composição com Poliéster e Elastano garante elasticidade, conforto e ajuste anatômico, acompanhando o corpo sem limitar os movimentos. Ideal para viagens e atividades ao ar livre, perfeita para uso em climas frios, ambientes com vento ou variações de temperatura, essa camiseta térmica é recomendada para atividades como trilhas, caminhadas, ciclismo, pesca, acampamento, motociclismo e viagens de inverno. Também é indicada para uso urbano, compondo looks casuais ou esportivos sob agasalhos. Benefícios do Produto: - Forro interno flanelado/pelúcia: retenção eficiente do calor. - Extremamente macia, leve e confortável. - Modelagem anatômica com ajuste ao corpo. - Alta elasticidade para liberdade de movimento. - Ideal como primeira camada em climas frios. - Versátil: ideal para esportes, lazer e uso diário. Tabela de Medidas: Tamanho P - Tórax/Busto: 85-90 cm. - Manga: 70 cm. - Cintura: 69-75 cm. - Quadril: 62-67 cm - Comprimento: 68 cm Tamanho M. - Tórax/Busto: 91-97 cm. - Manga: 70 cm. - Cintura: 83-88 cm. - Quadril: 92-97 cm - Comprimento: 69 cm. Tamanho G. - Tórax/Busto: 98-103 cm. - Manga: 70 cm. - Cintura: 93-98 cm. - Quadril: 104-109 cm - Comprimento: 70 cm Tamanho GG - Tórax/Busto: 107-113 cm. - Manga: 70 cm. - Cintura: 106-111 cm. - Quadril: 114-119 cm. - Comprimento: 71 cm Não perca tempo e garanta já sua Camiseta Térmica Segunda Pele Proteção UV50+ Verde Claro - Snugg na Dispropil! Especificações Técnicas: - Marca: Snugg - Modelo: Camiseta Térmica Segunda Pele Proteção UV50+ Verde Claro - Snugg - Material: 92% Poliéster e 8% Elastano. - Material Interno: Flanelado - Leve e de secagem rápida. - Cor: Verde Claro. Itens Inclusos: 01 - Camiseta Térmica Segunda Pele Proteção UV50+ Verde Claro - Snugg', 83.03, 83.03, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Swimming Attire', 'https://cf.shopee.com.br/file/sg-11134201-81ztm-miq8cj89tkw81a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1063297286%2F58202445476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
