INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593695542', 'Carrinho Multiuso Dobrável Reforçado Até 20kg Compras Transporte Multifunções', 'CARRINHO DE COMPRAS DOBRÁVEL MULTIUSO PORTÁTIL COM RODAS E ALÇA EXTENSÍVEL – 20 Kg Chega de carregar sacolas pesadas! Com o Carrinho de Compras Portátil Dobrável Multiuso, você ganha praticidade, conforto e organização nas atividades do dia a dia. Ideal para feiras, supermercados, praia, camping, eventos e muito mais! Seu design dobrável permite que seja facilmente guardado em qualquer cantinho. Com capacidade de até 60 litros e suportando até 20 kg, ele é o companheiro ideal para idosos, gestantes, pessoas com mobilidade reduzida ou para quem busca mais praticidade. BENEFÍCIOS E DIFERENCIAIS: - Dobrável e portátil: Use quando precisar, dobre e guarde com facilidade - Multiuso: Perfeito para feira, mercado, churrasco, viagens, praia e camping - Alta capacidade: 60 litros internos e suporta até 20 kg de carga - Alça extensível em alumínio: Ajustável em 2 alturas, resistente e ergonômica - Rodas de alta aderência: Estáveis em diferentes tipos de solo - Compacto e leve: Cabe no porta-malas, armário ou lavanderia ESPECIFICAÇÕES TÉCNICAS: - Modelo: Carrinho de Compras Dobrável Multiuso - Cor: Preto - Material da Estrutura: Polipropileno (PP) resistente - Alça: Alumínio com 2 níveis de ajuste - Capacidade Interna: 60 Litros - Suporte de Peso: Até 20 kg - Rodinhas: 2 unidades com alta resistência e aderência - Portátil: Sim, com sistema dobrável compacto - Peso Aproximado: Leve e fácil de transportar - Dimensões: 36 x 40 x 33 cm IDEAL PARA: - Feiras livres e supermercados - Transporte de itens em festas e eventos - Uso em viagens, acampamentos ou praias - Pessoas com dificuldade de locomoção - Quem busca praticidade no dia a dia Não sofra mais com peso excessivo! Adquira agora seu Carrinho Dobrável Multiuso e transforme suas tarefas em algo mais leve e prático!', 199.99, 111.99, NULL, 'Home & Living > Tools & Home Improvement > Trollies', 'https://cf.shopee.com.br/file/br-11134207-820lf-mnfsnllw7jsw47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F22593695542', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
