INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293520116', 'Kit com 3 Dobradiças Colonial Silvana', 'Leve para sua casa uma peça que combina durabilidade, funcionalidade e beleza com o Kit de Dobradiças Coloniais Silvana. Transforme suas portas com elegância atemporal e qualidade superior. Vantagens: Durabilidade: Feita de metal de alta qualidade, esta dobradiça é projetada para suportar o uso diário intenso sem perder sua eficácia ou beleza. Elegância Atemporal: O acabamento metálico dourado não só complementa o design colonial como também adiciona um toque de luxo às suas portas. Funcionalidade Superior: O pino central permite uma rotação suave, facilitando a abertura e fechamento das portas sem esforço. Versatilidade no Uso: Ideal para uma variedade de aplicações em portas interiores e exteriores, especialmente em ambientes que requerem um toque clássico. Especificações Técnicas: Marca: Silvana Material: Construção robusta em metal, garantindo maior durabilidade e resistência. Acabamento: Metálico dourado que proporciona um visual sofisticado e elegante. Estilo: Design colonial, ideal para complementar portas de estilo clássico e tradicional. Tamanho: Cada tamanho oferece o ajuste perfeito para diversas portas. Kit Completo: Inclui 3 dobradiças, permitindo uma instalação completa e prática. Garantia: - 3 meses por problemas de fabricação.', 42.9, 29.9, NULL, 'Home & Living > Safety & Security > Door Hardware & Locks', 'https://cf.shopee.com.br/file/sg-11134201-7rd6q-m6ofy3gp63rd86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23293520116', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
