INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18296932011', 'Escova Espanador De Balcão Max', 'Nada de poeira ou sujeira. O Espanador de balcão tem as cerdas macias, ideal para limpeza de locais que não podem arranhar ou levantar muita poeira. Super leve e portátil, te ajudará a manter seu ambiente mais limpo, livre de poeira e sujeiras. Seu uso é muito comum para limpeza de ambientes altos, fora do chão, pois se torna mais fácil e cômodo.', 41.9, 29.5, NULL, 'Home & Living > Home Care Supplies > Dusters', 'https://cf.shopee.com.br/file/sg-11134201-7qvg4-lgl4ankshrpd77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F18296932011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699666809', 'Interruptores Tomadas Linha Stylus - Ilumi', 'Os interruptores e tomadas da linha Stylus, da Ilumi, são desenvolvidos para oferecer praticidade, segurança e um design moderno para diferentes tipos de ambientes, sejam residenciais ou comerciais. Os interruptores e tomadas Stylus da Ilumi são ideais para quem busca uma solução elétrica confiável, funcional e com um acabamento moderno, agregando qualidade e sofisticação ao ambiente. Vantagens: Design moderno e sofisticado: Possui acabamento clean e elegante, com opções em cores neutras como branco e preto, permitindo fácil combinação com diversos estilos de decoração. Alta durabilidade: Fabricados com materiais de qualidade, garantindo maior resistência ao desgaste e longa vida útil. Fácil instalação: O sistema de fixação inteligente possibilita um encaixe rápido e seguro, tornando a montagem simples e eficiente. Variedade de opções: A linha conta com diferentes configurações para atender todas as necessidades, incluindo: Interruptores: Simples, paralelos, intermediários, pulsadores Tomadas: Padrão brasileiro (2P+T), TV, telefone e RJ45 (internet). Segurança garantida: Projetados dentro das normas técnicas vigentes, oferecendo mais proteção contra sobrecargas e garantindo o uso seguro no dia a dia. Dados Técnicos: Marca: Ilumi Linha: Stylus Material: Polipropileno (PP) Peso: 200g Dúvidas Frequentes: É fácil de instalar? -Sim, sua instalação pode ser feita com facilidade por um profissional, utilizando as ferramentas corretas, EPI e desligando a energia elétrica. O material é de alta resistência? -Sim, fabricados em Termoplástico de alta resistência, garantem durabilidade e um acabamento clean.', 29.9, 20.5, NULL, 'Home Appliances > Electrical Circuitry & Parts > Switches', 'https://cf.shopee.com.br/file/sg-11134201-7rd6o-m7la2hjqntko25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F18699666809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
