INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16579017164', 'Alicate Universal 8" Isolado e Forjado Tramontina', 'Alicates são ferramentas essenciais em qualquer kit, e o Alicate Universal 8" Tramontina é uma escolha confiável. Projetado para oferecer desempenho superior, ele é feito de aço especial temperado, garantindo resistência e durabilidade excepcionais. Com isolamento de 1000V, ele proporciona segurança em trabalhos elétricos. Seu design ergonômico facilita o manuseio, tornando-o ideal para tarefas que exigem precisão e força. A construção robusta permite que ele seja usado tanto em ambientes domésticos quanto profissionais, atendendo a múltiplas necessidades com eficácia. Vantagens: Formato anatômico para maior conforto Cabo isolado de PVC com proteção de 1000V Alta resistência ao desgaste e corrosão Versátil para apertar, dobrar, fixar e cortar Acabamento de qualidade assegurando longa vida útil Leveza que facilita o transporte e manuseio Especificações técnicas: Marca: Tramontina Tipo: Universal Modelo: 41001/108 Dimensões: 20,3 cm x 6,35 cm x 1,5 cm Peso do Produto: 0,39 kg Material: Aço especial temperado Material do Cabo: PVC amarelo Conteúdo da embalagem: Alicate Universal 8" Tramontina Garantia: Garantia de 12 meses pelo fabricante', 88.9, 60.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfhz-m3xidgmpteug11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F16579017164', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
