INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5257428441', 'Papel De Parede Marmore Silver Gold Vinilico Auto Colante', 'IMPORTANTE!! INFORME A MEDIDA DE SUA PAREDE EM ALTURA E LARGURA PARA QUE POSSAMOS AUXILIAR EM SUA COMPRA. Pedidos em datas diferentes ou separados, possuem cores diferentes, compre tudo em uma única vez em caso de dúvidas fale com nossos atendentes. Produto em tons predominantes de cinza, não tem relevo e brilho. Papel de parede é um adesivo vinílico, autocolante e lavável. Produzido em impressão digital, sem relevo. Ideal para decoração de sala, quarto, cozinha, banheiro ou outros ambientes. Cada unidade contem a medida de 3,00 metros de altura x 40 centímetros de largura. Papel de parede, autocolante, lavável e fosco. Impresso em material 0.10 Material: PVC vinílico, polimérico fosco e não tem cheiro. Antibactericida, Antimofo e não propaga chamas Dica para aplicação: Limpe o local com um pano úmido, certifique-se de retirar todo o pó da parede para melhor fixação do produto. Abra o papel em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Vitalidade da aplicação, média esperada: Interna 5 anos. Externa 2 anos.', 54.9, 32.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/4f492b9bf6404b100398443a038e25e0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F5257428441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19499561767', 'Tênis Infantil Menino Kidy Equilíbrio Fecho Duplo Preto Verde', 'Descrição O tênis infantil Kidy Ultra Soft é a escolha ideal para os meninos cheios de energia. Feito com cabedal em napa que facilita a limpeza, possui tecnologia Super Soft e Ultra Flex para máximo conforto durante todo uso . Além disso, conta com forma anatômica e solado antiderrapante garantindo saúde e segurança em cada passo.', 139.99, 119.99, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-7rffu-m33wbm4nrwc876', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F19499561767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41369513436', 'Sandália Infantil Menino Kidy Toys Baby Confortável Antiderrapante Flexível Escola Casual Anatômica', 'Diversão e conforto para os primeiros passos! A Sandália Kidy Toys Baby vem acompanhada de um lindo brinquedo, tornando cada momento ainda mais especial. Com fechamento em fita adesiva, o calce é rápido e prático, garantindo autonomia para os pequenos. Possui solado em TR antiderrapante, oferecendo mais segurança, além da tecnologia do equilíbrio, que contribui para passos firmes. Seu design anatômico e flexível proporciona conforto e liberdade em cada movimento. Mais do que uma sandália, é uma experiência cheia de alegria! Formato Anatômico Sempre pensando na saúde e conforto das crianças, todos os calçados Kidy possuem formato anatômico que auxilia no crescimento e desenvolvimento saudável dos pés. Tamanhos: do 22 AO 27 ; Fechamento: Fita Adesiva ; Cabedal: Sintético ; Forro: Têxtil ; Palmilha: EVA; Sola: TR Antiderrapante;', 159.99, 144.0, NULL, 'Baby & Kids Fashion > Boy Shoes > Sandals', 'https://cf.shopee.com.br/file/sg-11134201-824ic-mermi1iyrgu9a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045812437%2F41369513436', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
