INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40981193266', '21V Martelete Furadeira rompedor eletrico profissional Martelo de impacto Rompedor 2 Bateria', 'Descrição Característica: MARTELO ROTATIVO PODEROSO: Design ergonômico: Usando design auxiliar antiderrapante, a alça auxiliar rotativa de 360 ° aumenta a flexibilidade e melhor aderência, facilitando a operação em qualquer ângulo. O mandril de alta resistência não vai deixar cair a broca e bloquear a broca firmemente. Placa de circuito selada borracha, dustproof, impermeável e shockproof. 1 Botão3 Funções: Adapte-se a vários cenários de trabalho e tem quatro funções, incluindo perfuração, perfuração do martelo, ajuste da posição do cinzel e cinzel. Se ficar entupida, a broca pode ser facilmente desligada ajustando os interruptores dianteiro e reverso. Parâmetro: Martelo energia: 2.8J Tensão (110v/220v) Frequência do impacto: 0-980r/min 0-6200Cl/min Perfuração diâmetro: Cobre: 13mm Madeira: 28mm Concreto: 26mm Velocidade regulada modo: velocidade continuamente variável Brocas aplicáveis: haste redonda, dois poços e dois sulcos Potência máxima: 800W Peso neto: 6.2kg Tamanho máquina: 31cm * 20cm * 8cm Tamanho com caixa plástica: 42*13*34cm Peso do conjunto de brocas de 8 peças: 873g Tensão: 21V Velocidade sem carga r/min: 6200 Freqüência: 3200W Conteúdo do Kit: 1 - Furadeira 21V 1 - Precisão Marcador (para medições exatas nas suas tarefas) 1 - Alça ajustável em ângulo(ajustável para maior conforto e controle durante o uso) 4 - 6/8/10/12*150 Brocas (para perfuração em madeira, metal e concreto) 1 - 14*350 Broca 1 - 14*230 Cortador plano 1 - 14*230 Ponta afiada 2 - Baterias de Lítio de(para uma autonomia prolongada em trabalhos de longa duração) 1 - Carregador Rápido 1 - Caixa de Ferramentas (para manter todas as ferramentas organizadas e acessíveis)', 826.33, 378.9, NUL