INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392624044', 'Buzina Caracol Hyundai HB20 após 2019 Grave - Fiamm - AM80SXLKUM', 'A AM80 S é a buzina caracol 80mm preferida das montadoras em todo o mundo. A AM80 S é projetada e desenvolvida pela FIAMM COMPONENTI ACCESSORI - F.C.A. produzindo mais de 30 milhões de unidades por ano. As dimensões pequenas permite uma fácil instalação. O aftermarket kit, vem em caixa com marca FIAMM, matérias para fixar e relê. O produto projetado e desenvolvido na Itália é famoso pelo seu som e pela suas elevadas caraterísticas técnicas. A AM80 S é produzida para veículos 12V, com conexão standard e 2 terminais. Veículos APLICAÇÃO: HYUNDAI: HB20 - após 2019', 78.99, 78.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-lnsqwqm2z5f5c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1005342012%2F22392624044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797729313', 'Conjunto 4 x 2 Tramontina com Interruptor Simples e Tomada 2 Pinos + Terra 10A 250v Branco - 57170/264', 'As placas e módulos da linha Liz são fabricadas em termoplástico com acabamento brilho na cor branca, que não retém poeira, unindo qualidade e praticidade. O sistema é modular, com gradual ajuste entre placa e suporte, proporcionando perfeito acabamento da placa com a parede. Possuem furo oblongo para facilitar a fixação e a regulagem da placa à parede. Além disso, possuem furos para a fixação em parede de madeira. A fixação não é aparente. Acompanham suporte e parafusos para a instalação.', 23.9, 23.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electric Sockets & Extension Cords', 'https://cf.shopee.com.br/file/sg-11134201-7rd53-lwzrqxn8rn9m21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F18797729313', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20898568325', 'Cabo da Abertura do Capô com Maçaneta Celta 1.4 8v MPFI Life Spirit Super Flex 2003 2004 2005 2006 2007', 'Similar ao original: 93280665 1385 mm Garantia: 90 dias Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 34.99, 34.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134201-7qukw-lhi3twbqvek7ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F20898568325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20698004718', 'Kit Rodízios 2 Pol PVC Fixo 50kg Para Móveis e Utilidades JST', 'Kit Rodízios 2 Pol PVC Fixo 50kg JST Rodízios desgastados podem dificultar a movimentação de móveis e acessórios, exigindo maior esforço durante o uso. O Kit de Rodízios 2 Pol Fixo JST é produzido em composto termoplástico com PVC e núcleo em polipropileno copolímero reciclável, suporta até 50 kg por rodízio e contribui para uma movimentação com baixo nível de ruído, proteção do piso e excelente durabilidade. Indicado para móveis e acessórios de utilidades no atacado e varejo. Benefícios Principais Produzido em composto termoplástico com PVC. Suporta cargas de até 50 kg. Protege o piso durante a movimentação. Necessita de menor esforço para deslocamento. Produz baixo nível de ruídos no deslocamento. Possui excelente resistência química. Boa resistência ao desgaste e aos impactos. Estrutura adequada para móveis e acessórios de utilidades. Compatibilidade e Aplicação Indicado para móveis e acessórios de utilidades destinados ao atacado e varejo. Não indicado para utilização em carrinhos ou cadeiras com movimentação de pessoas. Especificações Técnicas Produto: Kit de Rodízios 2 Pol Fixo PVC Marca: JST Categoria: Rodízio Tipo de produto: Rodízio fixo Material: Composto termoplástico com PVC e núcleo em polipropileno copolímero reciclável Capacidade de carga: 50 kg Dureza: 80 Shore A (-10°C a +50°C) Diâmetro: 2" (50 mm) Largura da roda: 19 mm Altura: 95 mm Rosca: Espiga roscada 3/8" Peso: 0,140 kg', 11.34, 10.55, NULL, 'Home & Living > Furniture > Others', 'https://cf.shopee.com.br/file/sg-11134201-7ra1o-m4rneu9gb0de93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F20698004718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15104213221', 'Rodapé Moldura Flexível EVA Autocolante 7x1cm RP07 - 20 Metros | Decoração Quarto', 'Se você busca o que há de mais moderno, solução autocolantes com qualidade, instalação rápida, fácil e sem sujeiras que seja prático e inovador na decoração, muito prazer! Nós somos a Meu Rodapé! (e nós te ajudamos a fazer isso!). NÚMERO 1 do Brasil em vendas de rodapés, roda meios e roda tetos autocolantes. —————————————————————— Este modelo é ideal para dar maior acabamento ao seu ambiente, sendo instalado como rodapé. Mas, também pode ser utilizado para outros fins, como moldura de portas, janelas, painéis ripados ou cabeceiras. Do que o produto é feito? Nossos produtos são feitos em uma borracha sintética (EVA) específica para a decoração. O material possui alta resistência e flexibilidade, se adaptando a qualquer tipo de parede. Como é o processo de colagem? Não usamos fita dupla-face. Desenvolvemos uma cola específica para a decoração, mais forte e resistente, que garante a fixação do seu produto por anos e anos, sem dor de cabeça. A cola é protegida por uma película. Basta você retirar essa película e aplicar na sua parede. O modelo de sobrepor é o único que não é autocolante (mas sua fixação também é bastante fácil). Tem outras cores? Posso pintar A maior parte dos nossos produtos está disponível na cor branca (acabamento fosco). Alguns modelos possuem variação, sendo oferecidos na cor preta. Nos modelos brancos a pintura é recomendada, apesar de não ser obrigatória. Você pode pintar com tintas à base de água ou solvente (as mesmas que já utilizadas nas paredes). Quais as vantagens de comprar um produto com a material de EVA: 1. Durabilidade: O rodapé de EVA é resistente e possui boa durabilidade, sendo capaz de suportar impactos e desgaste do dia a dia. 2. Fácil instalação: O rodapé de EVA é leve e flexível, o que facilita sua instalação. Ele pode ser fixado com adesivos ou fitas especiais, dispensando a necessidade de pregos ou parafusos. 3. Facilidade de limpeza: O EVA é um material de fácil limpeza, sendo resistente a manchas e sujeira. Basta utilizar um pano úmido ou produtos de limpeza suaves. —————————————————————— Enviamos o produto de acordo com a disponibilidade em nosso estoque, geralmente em múltiplos de 2,5 metros. Se precisar de uma metragem linear maior, por favor, entre em contato conosco pelo chat com o vendedor e nos informe. Estamos aqui para garantir que seu pedido seja atendido conforme suas necessidades. —————————————————————— Qualquer dúvida que surgir sobre o produto você pode chamar aqui mesmo no chat, vamos ter o prazer em tirar as suas dúvidas. Até breve💚', 362.6, 344.47, NULL, 'Home & Living > Decoration > Photo Frames & Wall Decoration', 'https://cf.shopee.com.br/file/br-11134207-7r98p-llw6d7qm6sja08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401374403%2F15104213221', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19298094825', 'Cômoda Infantil 4 Gavetas Labirinto Henn', 'Cômoda Infantil 4 Gavetas Labirinto Henn foi desenvolvida para dar aquela sofisticação e modernidade ao quarto do seu filho, sem contar na qualidade. Produzido com materiais de alta qualidade o que garante uma ótima durabilidade do produto. Características: Material MDP/MDF 3, 12 e 15mm 4 Gavetas Puxadores em ABS Corrediças metálicas Gaveta suporta 3kg Tampo suporta 8kg Acabamento pintura UV Material do Puxador Gaveta: ABS Dimensões: Altura: 80 cm Largura: 65 cm Profundidade: 40 cm Peso: 20 kg Garantia do fornecedor de 3 meses.', 419.9, 375.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820lu-mptrja9sbl6pb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F19298094825', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299221799', 'Esticador hidráulico com capacidade de 10 toneladas MEH-10 - Marcon', '- Robustez e confiança são as características fundamentais dos hidráulicos Marcon, contando, ainda com uma rede de assistência técnica em nível nacional - Fundamentais para a realização de lanternagem, reparos em chassis e em monoblocos desalinhados, o MEH-10 tem capacidade de até 10 toneladas Ficha Técnica: • Curso do pistão: 103 mm • Comprimento: 700 mm • Largura: 178 mm • Altura: 151 mm • Capacidade: 10 Toneladas • Comprimento do pistão hidráulico (mín. / máx. ): 320/423 mm • Comprimento total da bomba: 361 mm • Comprimento total da alavanca: 400 mm • Comprimento total da mangueira: 1500 mm • Peso: 27 Kg Acompanha: - C-001: 01 Bomba hidráulica - C-011: 01 Mangueira de pressão - C-012: 01 Tubo de 695mm - C-013: 01 Tubo de 500mm - C-014: 01 Tubo de 300mm - C-015: 02 Ponteira - C-016: 01 Luva de 200mm - C-017: 01 Luva de 100mm - C-018: 01 Conexão - C-019: 02 Base reta - C-020: 01 Pistão hidráulico Comp.(mín/máx): 360/490mme pressão.', 1449.93, 1406.44, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luto8gahqkx185', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F272868574%2F18299221799', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
