INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16404614297', 'Espelho Retrovisor Pro Tork Mini Articulado Titan 150 / Titan 1999 Honda (Par)', 'A Pro Tork traz mais uma novidade para seu catálogo: os Retrovisores Modelo Articulado. São vários modelos para você escolher, todos baseados nos moldes dos modelos originais das principais motos do mercado nacional. Produzidos com materiais de alta qualidade, estes retrovisores são excelentes, suas hastes articuladas permitem ao piloto posicioná-lo para alcançar um maior campo de visão. Especificações: - Cor: Preto; - Modelo articulado; - Injetado em Polipropileno; - Peça de reposição; - Valor referente ao Par; - Marca: Pro Tork. Aplicação Honda: - Honda Titan 1999. - Honda Titan 150 2004; - Honda Titan 150 2005; - Honda Titan 150 2006; - Honda Titan 150 2007; - Honda Titan 150 2008. Instalação: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação; - Para realizar a instalação, leve sua moto à uma oficina especializada; - A Sportbay não se responsabiliza pela má instalação do produto. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 84.11, 57.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Side Mirrors', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxl1t4hut5yu1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F16404614297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298707140', 'Porta Taças para Lava-Louças Electrolux', 'Elegantes, mas frágeis, suas taças merecem um tratamento especial. Por isso, a Electrolux criou o Porta Taças para Lava-Louças. Com capacidade para até 8 taças, ele é versátil e flexível, sendo perfeito para você apreciar o que há de melhor, uma boa taça de vinho sem nenhuma preocupação.', 289.9, 289.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvt-mbpzo5wz4ih9bd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1526836548%2F22298707140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697644095', 'Fundo Fotográfico Halloween Cenário Casa Monstro Painel Em Tecido Sublimado para Foto - FFH-113', 'Todos os nossos Fundos Fotográficos Sublimados são confeccionados em tecido especial, com excelente acabamento e imagens nítidas que possibilitam fotos incríveis sem reflexos no resultado final. Por serem muito práticos, os fundos podem ser utilizados em estruturas como tripés (presos por garras) ou fixado em paredes e até mesmo placas de MDF com o auxílio de fita crepe ou dupla face (de formato largo, preferencialmente). Características: Tecido: Malha (estica e não amassa) Composição: 95% Poliéster + 5% elastano Gramatura: 140g m² Acabamento: Pode ser em overloque ou à laser, à depender da demanda. Ambos com acabamento perfeito que garantem sua durabilidade. ** Itens inclusos: 1 fundo fotográfico em tecido Malha ** Indicação de uso: Produção de fotos em estúdio fotográfico Informação complementar: As cores podem variar nas fotografias devido à qualidade da câmera fotográfica, ajustes/configurações da câmera, lente e iluminação do ambiente. Além disso, as configurações brilho e contraste do monitor ou celular onde a imagem está sendo visualizada, também podem dar a impressão das cores serem mais ou menos vivas, mais ou menos intensas. ** Todos os nossos produtos passam pelo processo de sublimação, sendo uma etapa onde passam por uma temperatura muito alta, podendo ter uma pequena variação em seu tamanho de até 5cm.** Nossos fundos fotográficos têm uma qualidade incomparável e é simplesmente incrível! Nosso tecido é maravilhoso, proporciona um toque suave e sem marcas de dobras, as cores são bem vivas e a nitidez da resolução incrível. Praticidade e economia de espaço, podem ser lavados, dobrados, guardados e é só esticar e arrasar nas fotografias. Possui acabamento impecável, não desbota e o caimento é perfeito! Uma combinação de qualidades especiais.', 78.9, 37.9, NULL, 'Cameras & Drones > Camera Accessories > Lighting & Studio Equipments', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me610o2uslxdc9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F776725570%2F23697644095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251117262', 'Regata Básica Infantil Lisa Soletex Cinza', 'A Regata Básica Infantil Lisa Soletex é confeccionada em 100% algodão, garantindo conforto, maciez e excelente respirabilidade para o dia a dia. Com design simples e versátil, possui mangas cavadas que oferecem liberdade total de movimentos e decote redondo que proporciona caimento leve. Ideal para dias quentes, é perfeita para compor looks frescos e práticos, acompanhando as crianças em todas as atividades com estilo e bem-estar.', 39.99, 39.99, NULL, 'Baby & Kids Fashion > Baby Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-82634-mm6j6klmnv9d18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F58251117262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
