INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497799822', 'Limpador de Parabrisa Renault 19 Sedan ano 89 a 01 Universal', 'Descubra a excelência em limpeza de para-brisa com nossa linha de produtos premium. Projetados para oferecer durabilidade superior e desempenho sem ruído, nossos limpadores em silicone garantem uma visibilidade impecável, independentemente das condições climáticas. Encontre a solução ideal para manter sua visão nítida e sua jornada segura em todas as viagens. Compatível com: Limpador de Parabrisa Renault 19 Sedan ano 89 a 01 Universal. Acompanha: 1 - Palheta Limpador de Para-brisa dianteiro Motorista 20" 1 - Palheta Limpador de Para-brisa dianteiro Passageiro 20" 1 - LIMPA PARA-BRISAS FORCE ONE 100ML Universal Investindo em qualidade e confiança, nossos produtos também incluem a garantia do fabricante de 90 dias. Adquira já e desfrute de uma visibilidade máxima com nossos limpadores de para-brisa premium', 29.9, 29.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz81eyobqudd84', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F18497799822', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207966286', 'Par Cilindro Freio Dianteiro Roda Fusca 1200 1300 57 A 84', 'Este anúncio contém: 02 (Dois ) Cilindros de freio das rodas dianteiras. Conteúdo da embalagem: 02 (Dois ) Cilindros completos. Informações técnicas: Diâmetro interno: 22mm ou 7/8. Aplicável nos seguintes veículos: Fusca 1200 / 1300 / 1500 / 1600 1957 A 1984 Todos. Importante: Preço do par; Garantia 3 Meses; Alta Durabilidade; Qualidade Original; Produto Com Nota Fiscal. Quem somos? Loja de Auto Peças e Acessórios para carros nacionais e importados, há 35 anos atendendo o mercado de reposição. Temos em estoque uma enorme variedade de produtos para motor, câmbio, suspensão, freios e diversos acessórios para seu carro, trabalhamos com marcas originais e paralelas, todas as peças com preços que cabem no seu bolso. Dúvidas frequentes: O Produto é novo? Sim, todos os nossos produtos são novos diretamente de fábrica. Produtos de qualidade ? Todos os nossos produtos seguem um rigoroso processo de qualidade fazendo com que se tornem itens de primeira linha no mercado de reposição. O produto é igual ao da foto? Sim. Todas as fotos são fiéis ao que você receberá, são feitas para facilitar a sua compra. Tem garantia? Sim, temos garantia para defeito de fábrica. Todos os nossos produtos têm 3 meses de garantia. Tem a pronta entrega? Temos sim, todos os nossos envios demoram no máximo 24 horas para serem retirados pela transportadora do Mercado Livre. Enviam pelos correios? Todos os produtos são retirados exclusivamente pelo transporte do Mercado Livre, não enviamos pelos correios. Envia ainda hoje? Pedidos liberados pelo Mercado Livre até as 12:00 são retirados no mesmo dia, após esse horário serão enviados no dia seguinte, a coleta do Mercado Livre passa de segunda a sábado em nossa unidade. Em quanto tempo recebo minha compra? É muito simples, ao clicar em comprar, basta colocar seu CEP no calculador de frete do anúncio que irá aparecer o valor do frete e a data de entrega. Emite nota fiscal ? Sim, todos os nossos produtos saem com nota fiscal. Importante: No ato da compra, caso necessário, enviaremos uma mensagem confirmando algumas informações, para evitar enganos no envio e transtornos posteriores, caso não haja a confirmação, enviaremos conforme o anúncio que a compra foi feita. Tem alguma dúvida sobre o produto ou sobre a compra? Deixe sua pergunta abaixo, que responderemos prontamente. Garantia de fábrica: 90 dias', 127.91, 126.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-820l9-mmhjkh565l3a79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1037769766%2F58207966286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
