INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208814655', 'Bola Tenis De Mesa 3 Estrelas Kit Com 3 Unid Mbfit', 'Bola Tenis de mesa 3 estrelas kit com 3 unid mbfit A bola Tênis de mesa são feitas em acetato de celulóide e possuem 40mm de diâmetro, medida aprovada pela Federação Internacional de Tênis de Mesa. Com sua tecnologia 3 estrelas, você tem um melhor controle da velocidade e das batidas da bola, perfeito para seu jogo! Composição: ABS Peso aproximado: 3g Diâmetro: 40mm Contem : 1 cx com 3 Bolinhas', 10.0, 10.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Shoe Bags', 'https://cf.shopee.com.br/file/sg-11134201-81zvn-mn1loe4pcglea8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F58208814655', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398086668', 'Suporte Para Bolsa De Gelo Ksn026 Kestal', 'Anvisa : Registro isento conforme resolução RDC 27 de 06 de agosto de 2010 - anexo 1. Suporte para Bolsa de gelo Kestal KSN026 Com o Suporte para Bolsa de gelo Kestal proporciona suporte e compressão, utilizando os benefícios do calor e do frio em regiões dos ombros e costas Ajustável e em tamanho único, é indicada para uso com a Bolsa Térmica Gel. É o método mais prático e eficiente para aplicação de calor ou frio terapêuticos em casos de: Dores na coluna, lombalgias, cervicalgias, dores reumáticas, contraturas musculares, stress muscular, entorses, contusões e distensões. Único, Tamanho único - ajustável Medidas aproximadas: 27cm de largura aproximados 40cm comprimento aproximados na parte do suporte 66cm comprimento aproximados das tiras Composição: Borracha de cloropreno revestida com tecido 100% poliamida. ITENS INCLUSOS: 01 unidade do Suporte para Bolsa de gelo Kestal Não acompanha Bolsa para Gelo. IMPORTANTE - A orientação de um profissional qualificado para uso é inpresindível - A Bolsa de gel quente e frio não acompanha a cinta - Quando utilizada com bolsa térmica deve-se proteger a região com uma toalha Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 89.0, 89.0, NULL, 'Health > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rffs-m3w244bc07x77a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F23398086668', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
