INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394018294', 'Raspador Multiuso 100mm para Remoção e Raspagens em Geral Vonder', 'Indicado para remoção de tintas, silicones, colas e raspagens em geral em superfícies planas. Conteúdo da Embalagem: 1 Raspador. Possui cabo emborrachado proporcionando mais conforto ao usuário. Características: - Lâmina: aço carbono; - Corpo: liga de alumínio; - Cabo: borracha termoplástica (TPR) - Comprimento total: 305,0 mm - Comprimento da lâmina: 100,0 mm - Largura da lâmina: 13,5 mm - Espessura da lâmina: 0,38 mm - Massa aproximada (peso): 0,16 kg', 69.9, 36.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfig-m9sr96itrl3l98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F22394018294', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893866506', 'Chave de Impacto SGT7500A c/ 2 Bateria 20V Bruchless Sigma', 'A Chave de Impacto SGT7500A 20V Brushless SIGMA é a ferramenta ideal para quem busca alta performance e durabilidade em seus trabalhos de manutenção e reparos. Com motor sem escovas (brushless), ela oferece maior eficiência, prolongando a vida útil da ferramenta e reduzindo o desgaste. A chave de impacto possui um design ergonômico e robusto, proporcionando conforto e controle durante o uso, além de um sistema de impacto potente, capaz de lidar com tarefas pesadas, como aperto e desaperto de parafusos e porcas em diversas aplicações. Acompanha 2 baterias de 20V, garantindo autonomia prolongada para execução de trabalhos sem interrupções, e um carregador para recarregar as baterias rapidamente, aumentando a produtividade. Além de seu alto desempenho, a Chave de Impacto SGT7500A 20V Brushless SIGMA é equipada com características de segurança, como proteção contra sobrecarga e superaquecimento, garantindo maior confiabilidade no uso. Sua estrutura compacta e leve torna a ferramenta fácil de manusear, ideal para trabalhos em espaços apertados e para uso contínuo. Seja para profissionais ou entusiastas de bricolagem, essa chave de impacto oferece a combinação perfeita de potência, eficiência e durabilidade para suas necessidades de fixação. Características: • Dispensa uso de compressor; • Desenho ergonômico; • Regulagem de torque em 3 níveis; • Maior autonomia (2 baterias 20V de Lithium-Ion); • Autonomia de até 200 parafusos (aproximadamente 50 rodas com 4 parafusos); • Possui botão de reversão para aperto e desaperto. Aplicações Indicado para operações de aperto e desaperto de parafusos e porcas em geral, onde há exigência de alto torque. Aplicações de uso automotivo, montagens e desmontagens. Acessórios Inclusos: – Maleta; – 2 Baterias (1 na ferramenta e 1 avulsa); – 1 carregador rápido (carga em até 2 horas).', 1575.0, 914.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-81zu9-mkjvhl45ghz611', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333540705%2F22893866506', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
