INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40177959270', 'Tênis Everlast Solo Preto - Masculino', 'Estilo e proteção para encarar todos os desafios do dia! Tênis Everlast Solo Preto - Masculino Parte superior do formulário Ficha Técnica: Marca: Everlast Gênero: Masculino Cor: Preto Indicado: Dia a dia Cabedal: Mesh laminado leve e respirável Palmilha: EVA com forro têxtil confortável Sola: EVA com borracha antiderrapante Fechamento: Cadarço Amortecimento: Entressola em EVA Estabilidade: Neutro Tecnologias: E-shield - Camada protetora contra impactos, odores e desgaste Tipo de pisada: Neutra Detalhes: Logo e escrita Everlast nas laterais Sinta a diferença em cada passo com o Tênis Everlast Solo! Seu visual marcante combina com a resistência que o dia a dia exige. Porque investir: O cabedal respirável proporciona frescor prolongado, enquanto a entressola em EVA garante amortecimento leve e eficaz. A sola com borracha antiderrapante oferece estabilidade em diferentes terrenos, seja na cidade ou em trilhas leves. E com a tecnologia E-shield, você tem proteção contra impactos, odores e desgaste, elevando a durabilidade ao máximo. Um modelo versátil, funcional e com estilo esportivo. Conteúdo da embalagem: 1 par de Tênis Everlast Solo Preto - MasculinoParte superior do formulário Parte superior do formulário Parte superior do formulário Parte superior do formulário Parte superior do formulário', 229.99, 187.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82635-mjeajt4hh43lad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F40177959270', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212788348', 'Protetor Solar Facial em Pó Compacto Episol Color FPS 50 | Tom 3 - Médio 10g', 'O Protetor Solar em Pó Episol Color no tom 3, Morena, faz parte da linha de proteção solar com cor da Mantecorp Skincare. Ele promove a uniformidade da pele, sendo ideal para a reposição do protetor solar e reforço da maquiagem ao longo do dia. Este produto está disponível, ao todo, em cinco tonalidades: pele extra clara, clara, morena, morena mais e pele negra, sendo todas com a opção de FPS 50.Além disso, o Protetor Solar em Pó Episol Color protege contra os raios UVA, UVB, infravermelho A e luz visível.', 169.9, 169.9, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-824j6-mpmn290cg00b0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F58212788348', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598777902', 'Rejuvenescedor Facial Reviline Retinol Sérum - 30ml', 'ORejuvenescedorFacialRevilineRetinolSérumtemaçãointensaepotente,comresultadosvisíveiseduradouros.Suafórmulaúnicaeavançadacombinaativosinovadoresparacombateraté20sinaisdeenvelhecimento,comolinhasdeexpressão,estresseoxidativo,perdadeelasticidade,entreoutros,proporcionandoumapelemaisjovem,firmeeradiante. Sua formulação exclusiva conta com Retinoato Nanoencapsulado, a forma mais inovadora e eficaz de retinoide disponível, e Retinol Nanoencapsulado, que garante uma ação prolongada e eficaz no estímulo de colágeno e elastina. Esses dois ativos poderosos trabalham em sinergia para promover a regeneração da pele e intensa renovação celular, enquanto suavizam rugas e linhas de expressão. Além disso, a tecnologia Progenesis, que combina Tripeptídeos e Triplo Ácido Hialurônico (alto, médio e baixo pesos moleculares), é responsável por prolongar a longevidade celular, devolvendo à pele a vitalidade e a atividade celular semelhante a de 22 anos. Essa tecnologia proporciona hidratação profunda e contínua por até 24 horas, o que deixa sua pele mais macia, luminosa e densificada. Sua textura leve e de rápida absorção com toque seco faz com que oRejuvenescedorFacialRevilineRetinolSérumsejaidealparatodosostiposdepele,mesmoasoleosasesensíveis. Não comedogênico e acnegênico, é um tratamento de cuidado diário, que oferece hidratação profunda, elasticidade, luminosidade e reparação da pele, promovendo uma pele mais firme e rejuvenescida.', 259.9, 259.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-820l9-mm9hl84yy5tw44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1392870796%2F22598777902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
