INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093480162', 'JORNADAS AUTOBIOGRÁFICAS NARRATIVAS E MEMÓRIAS PARA A FORMAÇÃO DO EDUCADOR', 'JORNADAS AUTOBIOGRÁFICAS NARRATIVAS E MEMÓRIAS PARA A FORMAÇÃO DO EDUCADOR A educadora e antropóloga Adriana Friedmann reflete sobre as origens e raízes multiculturais como caminho para a compreensão das identidades e comportamentos dos sujeitos, pois não escutamos e conhecemos as crianças se não criarmos processos de escuta da nossa própria história. As reflexões dialogam com pensadores e teóricos de diversas áreas de conhecimento, com propostas de jornadas de autoconhecimento para a formação do educador.. Informações Adicionais Autor: FRIEDMANN, ADRIANA Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: JORNADAS AUTOBIOGRÁFICAS NARRATIVAS E MEMÓRIAS PARA A FORMAÇÃO DO EDUCADOR Idioma: INDEFINIDO Páginas: 136 Edição: 1 ISBN-13: 9786588457214 ISBN-10: 6588457219', 62.9, 62.9, NULL, 'Books & Magazines > Books > Education & School', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-lqlfee6ldgh601', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23093480162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898766616', 'Farol de Neblina Milha Led Chevrolet Agile 2010 2011 20000lm', 'Lâmpada Led Force One Adquira já as lâmpadas automotivas com melhor custo benefício do mercado Efeito Xênon! Conteúdo da Embalagem: - 2 Super LED H3 - Milha - 2 Pingo Led - Chicotes - Manual do Usuário KIT COMPLETO PARA INSTALAÇÃO Aplicação: Chevrolet Agile 2010 e 2011 Lâmpadas Super Led ? 20000Lumêns e 6500k Aumente a projeção e alcance de luz com a tecnologia LED, com o Par de Lâmpadas, trazendo maior segurança e visibilidade durante a direção noturna. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor, melhora consideravelmente a luminosidade proporcionando muito mais visualização das vias! *PAR DE LÂMPADAS SUPER LED V10* Especificações Técnicas: Tecnologia Alemã. Design Compacto. Tonalidade: 6500K (Kelvins) Extremamente Branca. Tecnologia Alemã. Resistente a Água. Base e Corpo da Lâmpada em Metal. Eficiência de 20000 Lúmens do Par. Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais Potência máxima de 30 Watts. Economiza a Bateria Resistente ao Calor (Contém um Cooler por Lâmpada) Excelente Resistência a Vibrações e Emissão de Luz Estável. Opera em 12V. Acompanha Fontes Embutidas. Chip Importado de Alta Potência. Mais Segurança e Eficiência. Dimensões: 9cm altura x 4cm de comprimento. - Aumente o poder do farol de seu carro ou moto. Instalação: Não é necessário cortar fios. O chicote vem Pronto para se conectar ao sistema original do veículo. Produto com melhor durabilidade, mais foco e materiais mais nobres. Dicas de Instalação (IMPORTANTE): Para o perfeito foco da Lampada, os leds sempre devem ficar na posição horizontal, mantendo o foco perfeito. É necessário o ajuste, sem isso a iluminação não foca. Garantia: 90 dias.', 49.9, 46.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-7rdyp-mcw963v7wfh053', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F413680793%2F23898766616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
