INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893546893', 'Blusa Básica Feminina Gola Alta Em Malha Canelada De Viscose', 'Blusa feminina feita em malha canelada de viscose. A blusa básica é a peça perfeita para o seu dia a dia, ela te acompanha em todos os momentos. Apresentando um modelo com caimento mais ajustado, essa peça conta com gola alta e mangas longas. Além disso, ela foi feita em malha canelada, tendo o seu diferencial por apresentar textura canelada e oferecendo excelente caimento e conforto no vestir. Aposte com jeans Malwee para ter um visual prático e estiloso sem esforço! • Blusa Básica em Malha Canelada de Viscose • Gola Alta • Mangas Longas • Situação de Uso: Casual e Dia a Dia', 89.9, 80.91, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-7rfh3-m315wt1ipm5j11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939838662%2F22893546893', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699261403', 'KIT MINI VINHOS DEL GRANO GOLD 3X250ML', 'Kit Del Grano Gold com 3 Vinhos 250ml. Uma marca conhecida nacionalmente por oferecer produtos de qualidade, produzidos por uma empresa com tradição de mais de 80 anos, que leva ao mercado sempre o que há de melhor, reflexo da dedicação na produção e do cuidado com que os produtos são tratados. Vinho Del Grano Gold Tinto Seco: É um vinho feito com as uvas Isabel e Bordô, produzidas na região da Serra Gaúcha, durante sua vinificação as uvas são esmagadas e fermentadas em tanques de aço inox com controle de temperatura, permanecem uma semana em contato com as cascas para extrair a cor, o aroma e o sabor das uvas Vinho Del Grano Gold Tinto Suave: Vinho feito com as uvas Isabel e Bordô, produzidas na região da Serra Gaúcha, durante sua vinificação as uvas são esmagadas e fermentadas em tanques de aço inox com controle de temperatura. Vinho Del Grano Gold Rosé Bordô Suave: É um vinho de visual sedutor e tonalidade rosé cereja. Aroma característico, notas típicas das uvas Bordô como morangos, cerejas e amora e notas florais como rosas e violeta. Contém 250ml cada. Vinho nacional.', 73.82, 73.82, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7rd4e-lw5y8plv7pjfc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844012318%2F19699261403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
