INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9349581287', 'KIT LAMPADA AUTOMOTIVA LED CODE H1 6000K KC-Z-1308', 'Bem Vindo(a) a AT4U. Kit Super Led Standard 6000K H1 TechOne Quem quer unir personalização, segurança e custo-benefício no sistema de iluminação do carro, a Code, marca chancelada pela Tech One, traz o kit super led 6000K com efeito semelhante ao do Xenon. Feito para os mais variados modelos de carros, o Super Led Code possui dois chips de led por lâmpada. Desenvolvida em parceria com os laboratórios da Tech One, a lâmpada vem com o chip CD757, que garante uma resistência incrível ao super led, diminuindo os riscos de danos no momento da instalação e em caso de trepidações durante as viagens. O produto também possui resistência à água, reator interno e resfriamento composto por uma combinação de ventoinha e dissipador de calor. O kit aqui apresentado é constituído por um par de lâmpadas Super Led 6000K de encaixe H1 (removível para facilitar a instalação), com feixe de luz emitido na cor branca. Características: - Encaixe: H1 - Chip de Led: CD 757 - Quantidade de Led: 2x por lâmpada - Ângulo de emissão: 360° - Voltagem: 12V DC - Classificação: IP67 (resistente à água) - Temperatura de cor: 6000K - Temperatura de operação: -40°C a 95°C Medidas: - Peso: 0.15Kg - Largura: 6cm - Comprimento: 12.5cm - Altura: 6cm Conteúdo da Embalagem: - 02 Lâmpada Led H1 6000K IMPORTANTE: * Postagem em até 24h. * Entrega Garantida. * COMPRE COM SEGURANÇA. * Tire suas dúvidas via chat com nossos especialistas.', 156.85, 156.85, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/f41307f2cf231dc5ad8bafca5b276baa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349249646%2F9349581287', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
