INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994031439', '2 Pares de Pastilha Freio a Disco Mecânico Paco, Absolute, Gts, Tsw, Veloforce', 'Desenvolvida para fornecer uma excelente frenagem em condições secas ou úmidas, da mais cotidiana a mais agressiva. Possui uma excelente dissipação de calor. Pastilhas duráveis e bastante resistentes e com dimensões aproximadas de 3 x 2cm. Especificação: - ACOMPANHA MOLA - Marca: Paco - Modelo: P01 Furada - Compatível: Com freios que usam Imã e Mola - Cor: Vermelha - Composição: Resina e Pó Metálico (Semi-Metálica). - Ideal: clima seco ou úmido. - Dimensões: aproximadamente 3 x 2cm. - Kit Acompanha: 2 Pares de Pastilha - Par de pastilhas de freio a disco compatíveis com freio Paco P01 160mm. Paco / Absolute/ Gts/ Zoon/ Veloforce / Raid/ Tsw entre outras -------------------------------------------------------------------------------------------------------------------------------------- Dúvidas Frequentes: • Os produtos são novos e originais? Todos os produtos comercializados pela Oliveira Bikes são novos e originais. Precisa de ajuda? Utilize o Chat e esclareça suas dúvidas, nós estamos à disposição para qualquer informação!', 24.61, 24.61, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rauc-ma7qfuqvo7mz7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F22994031439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
