INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41676500053', 'Macacão bebê Tricô Premium Lucas', 'Tamanho P. Veste de 0 a 3 meses. Mede 50cm do ombro ao pé. Pé aberto. Acompanha bodie branco. Conforto absoluto: tecido macio, maleável e quentinho, perfeito para a pele sensível do bebê. Cores suave que dão um ar moderno, delicado e sofisticado. Acabamento premium: tricô uniforme, detalhes bem trabalhados e modelagem confortável para o bebê se mexer à vontade', 99.0, 89.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134201-820m9-mqy71nelo3d0b0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F432637056%2F41676500053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15396167423', 'Conjunto Ciclismo Masculino Várias Cores Camiseta Bicicleta + Bermuda Acolchoada', 'Kit Camisa Pro de Ciclismo + Bermuda Acolchoada Composto por tecidos que permitem alta performance e liberdade de movimentos; Sobre a camisa: -Confeccionada em tecido esportivo que mantém o corpo seco e a temperatura estável; -Possui proteção solar UV 50 +, tratamento antibacteriano, tratamento antimicrobiano; -Parte traseira mais comprida que a frontal e com 3 bolsos traseiros; -Elástico na parte de baixo da camisa; -Confeccionada em alta resolução com nitidez nas cores. Sobre a Bermuda: -Bermuda com corte anatômico e material que garante ótima compressão, conforto e rápida evaporação do suor, mantendo a pele ventilada e seca. Forro em espuma garante alta proteção contra absorção de impacto sendo indicado para pedaladas mais longas de estradas e Mountain Bike, montado em camadas de espuma com tecido de poliéster. Com espuma 100% poliuretano ,Densidade 70; Ideal para Mountain Biking, Ciclismo ou Cicloturismo. ATENÇÃO - FAVOR CONFERIR TABELA DE MEDIDAS', 159.9, 79.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/sg-11134201-23010-dwa536dymjmv2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F15396167423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
