INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597462897', 'Sensor Temperatura Toyota Corolla 1992 a 2007 - 186627 - 4138', 'Sensor Temperatura Toyota Corolla 1992 a 2007 186627 4138 1.6 16v - 2 Pinos - Branco - Água Cebolinha de temperatura ou Sensor Temperatura - Informa com precisão para o painel do veículo, como para o computador da injeção eletrônica o valor exato dessa temperatura, para evitar imprevistos e grandes prejuízos. Veículos mais novos aciona a ventoinha no lugar do Interruptor Térmico e a partida a frio nos veículos Flex. É possível encontrar o sensor de temperatura no cabeçote, ou seja, a parte mais quente do motor e onde a temperatura pode ser medida com uma precisão mais assertiva.', 141.95, 141.95, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd45-lufag8f31fd8a6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23597462897', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20298090529', 'Pré Filtro Combustível Vw Golf 1994 a 2025 - 1354411 - T040203', 'Pré Filtro Combustível Vw Golf 1994 a 2025 1354411 T040203 Gasolina - sistema Bosch - Copo, filtro externo e internoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 54.54, 54.54, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mq1xqrvhzj0v9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20298090529', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
