INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898234286', 'MANGUEIRA DO RESPIRO MONZA 2.0 1989 1990 1991 1992 1993 - 94006 - 0121', 'MANGUEIRA DO RESPIRO MONZA 2.0 1989 1990 1991 1992 1993 Ventilação Filtro de Ar à Tampa Comando Válvulas 1.8/2.0 8V MFIEssa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 30.46, 30.46, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822wk-mo9qd5b6lzbjcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23898234286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
