INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698243868', 'Tubo Água PALIO COM AR 1.5 1996/2000 - 98146 - VC211', 'Tubo Água PALIO COM AR 1.5 1996/2000 VALCLEI VC211 Motor 1.0/1.5 8v Álcool/Gasolina - (Com ACD/Ar Quente/Desembaçador) (Tubo do Fluxo D''Água do Motor) O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 42.54, 42.54, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rasb-majbzw1pfaz40e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23698243868', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
