INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53605084468', 'Tapete higiênico Ultra Pads Carvão 60x80 cm 30 unidades', 'O Tapete Higiênico Ultra Pads Carvão foi desenvolvido para cães, oferecendo maior absorção e auxílio no controle de odores no dia a dia. Sua camada com carvão ativado contribui para neutralizar cheiros, mantendo o ambiente mais limpo e agradável. Com tamanho de 60x80 cm, é ideal para diferentes portes e facilita o treinamento higiênico. A embalagem com 30 unidades garante praticidade, bom rendimento e reposição frequente. FICHA TÉCNICA • Indicação: Higiene diária para cães • Finalidade: Auxiliar na absorção e controle de odores • Tipo de produto: Tapete higiênico descartável • Tecnologia: Camada com carvão ativado • Dimensões: 60 cm x 80 cm • Apresentação: Pacote com 30 unidades • Público alvo: Cães CUIDADOS COM O PRODUTO Descartar após o uso conforme necessidade. Manter em local seco e protegido da umidade. Não reutilizar após saturação. Utilizar em local apropriado para o animal. Manter fora do alcance de crianças e animais não destinados ao uso.', 97.44, 64.9, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjsiy4hdbima82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F53605084468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
