INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23499160518', 'Chocalho Mordedor Bebê Textoy Látex Leão Laranja E Rosa', 'Chocalho Mordedor Textoy Infantil Leão Laranja E Rosa O Chocalho Mordedor Textoy Infantil em formato de leão, nas cores laranja e rosa, é perfeito para aliviar o desconforto da dentição, combinando textura macia com som suave que estimula os sentidos do bebê. Fabricado com material seguro, atóxico e design ergonômico para facilitar a pegada e o manuseio pelas mãozinhas pequenas. Características: Formato: Leão Cores: Laranja e Rosa Funções: Mordedor e chocalho Material: Atóxico e seguro para bebês Textura macia para massagear gengivas Som suave que estimula a audição Design ergonômico para fácil manuseio Marca: Textoy Indicação: Recomendado para bebês em fase de dentição e desenvolvimento sensorial Informações Adicionais: Tamanho: Único Cor:Rosa Referência:02202 Marca: Textoy', 21.9, 21.9, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgrzj9p9pblx7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23499160518', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494196284', 'Trenzinho Brinquedo Monte Líbano Loco Baby Educativo Amarelo', 'Trenzinho Brinquedo Monte Líbano Loco Baby Educativo O Loco Baby Monte Líbano é uma escolha encantadora e educativa para crianças a partir de 18 meses. Este brinquedo é projetado para promover o desenvolvimento das habilidades motoras e cognitivas dos pequenos enquanto oferece diversão sem fim. O trenzinho é equipado com rodinhas para facilitar o movimento e um ábaco colorido que ajuda na introdução de conceitos básicos de contagem e habilidades numéricas. Além disso, possui um sino que emite sons suaves, estimulando a percepção auditiva e o desenvolvimento da coordenação motora. Feito de materiais não tóxicos, o brinquedo garante a segurança dos pequenos durante o uso. Além de seu valor educativo, o trenzinho Loco Baby também proporciona um momento de diversão e aprendizado. A movimentação das rodinhas e a interação com os componentes do ábaco e do sino ajudam a aprimorar a coordenação motora e a percepção sensorial das crianças. Ideal para brincar tanto em casa quanto ao ar livre, este brinquedo é perfeito para incentivar a exploração e o desenvolvimento enquanto oferece entretenimento seguro e estimulante. Um presente excelente para estimular o aprendizado e a diversão desde os primeiros anos. Informações Adicionais: Tamanho: Único Referência: 4140 Medidas aproximadas: 22cm x 11cm x 26cm Marca: Monte Líbano', 41.9, 41.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-7rdy7-mbqsq1ombk7u9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22494196284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294973563', 'Ração para Cães Qualidy Bifinho Adultos Carne 55g - Embalagem com 20 Unidades', 'Características do Produto: Marca: Qualidy Tipo: Bifinho para cães Idade: Adultos Sabor: Carne Peso Líquido: 55 g EAN: 17898363312157 Características Adicionais: Mastigável Bifinho sabor carne Saboroso e divertido Sem corantes artificiais Indicado para cães adultos Ingredientes balanceados e de alta qualidade Ideal como recompensa ou para enriquecer a rotina do pet Composição: Proteína texturizada de soja, rim de suíno, óleo de aves, cloreto de sódio, glicerina, carbonato de cálcio, BHT (Butilhidroxitolueno), ácido cítrico, BHA (Butilhidroxianisol), tripolifosfato de sódio, propionato de cálcio, sorbato de potássio, benzoato de sódio, nitrito de sódio, nitrato de sódio, aroma de carne, vermelho ponceau 4R, amarelo tartrazina, vermelho amaranto e azul brilhante. Contém, na composição, ingrediente geneticamente modificado: soja*. Espécies doadoras de gene: Agrobacterium tumefaciens* e Bacillus thuringiensis*. Eventuais substitutivos: Farinha de soja*, farinha de mandioca, farinha de trigo, farinha de carne de bovino, farinha de carne e ossos de bovino, carne mecanicamente separada de aves, fígado de bovino, fígado de suíno, baço suíno, baço bovino, pulmão de bovino, pulmão de suíno, rim de bovino, aroma de fumaça e goma xantana Fornecedor: Adimax Industria e Comercio', 83.07, 83.07, NULL, 'Pets > Pet Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-824i9-mpib9c52n8ch20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F22294973563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
