INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998740595', 'Sensor Nivel Boia Combustivel Ka 2008 2009 2010 Original Ds', 'SENSOR DE NÍVEL DE COMBUSTÍVEL ORIGINAL DS (23116) - PREÇO REFERENTE A 01 UNIDADE APLICAÇÕES FORD KA 1.0 / 1.6 2008 2009 2010 TODOS OS NOSSOS PRODUTOS SÃO NOVOS, COM GARANTIA E NOTA FISCAL GARANTIA DE 12 MESES DO FABRICANTE ***RECOMENDAMOS QUE A INSTALAÇÃO SEJA REALIZADA POR PROFISSIONAIS ESPECIALIZADOS!*** NÓS DA EQUIPE GOLDSPEED, AGUARDAMOS SUA COMPRA! O SENSOR NIVEL COMBUSTIVEL DS oferece uma solução eficaz para o monitoramento do nível de combustível do seu veículo. Fabricado com materiais de alta qualidade, como plástico e metal, garante durabilidade e resistência, essenciais para o desempenho em condições adversas. Escolher este sensor é garantir a integridade do sistema de abastecimento e, consequentemente, a eficiência do seu veículo, proporcionando uma experiência de condução otimizada e sem preocupações.', 94.68, 93.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rdyt-mcl3yj7b43lsa7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F969248320%2F23998740595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693067162', 'Condicionador Elseve Pure Hialuronico 400ml', 'O Condicionador Reidratante, desenvolvido com a dupla ação do poder de Ácido hialurônico + Ácido salicílico, devolve o nível ideal de hidratação do comprimento às pontas para uma transformação instantânea sem pesar. Indicado para cabelos oleosos, que precisam de raízes purificadas e pontas hidratadas. Para controle de oleosidade e pontas hidratadas por 72H.', 36.95, 36.95, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rd6c-lvoz099dyfdk76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23693067162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
