INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41232141739', 'Escada 100% Alumínio 3 Ou 4 Degraus Até 120Kg Dobrável Resistente Doméstica Flexível Reforçada Aço', 'Desfrute de praticidade e segurança com a Escada Alumínio Dobrável Reforçada 4 Degraus. Esta escada é uma escolha ideal para consertos rápidos e acesso a lugares elevados em sua casa. Fabricada com estrutura e chapas em alumínio, ela é leve, durável e resistente à corrosão, inclusive em áreas litorâneas, garantindo longa vida útil. As peças plásticas em polipropileno de alta resistência proporcionam ainda mais durabilidade. Com pés antiderrapantes e travamento automático na plataforma superior, você desfruta de estabilidade máxima durante o uso, suportando até 120 Kg com total segurança. Especificações: MATERIAL: Estrutura de Alumínio ITENS INCLUSOS: 01 Escada 4 Degraus de Alumínio Palavras-Chave: Banqueta Alumínio, Escada Alumínio 4 Degraus, Dobrável, Reforçada, 4 Degraus, Uso Doméstico, Consertos, Leve, Durável, Resistente, Corrosão, Estabilidade, Pés Antiderrapantes, Travamento Automático, Capacidade 120 Kg, Escada.', 249.98, 169.99, NULL, 'Home & Living > Tools & Home Improvement > Ladders', 'https://cf.shopee.com.br/file/br-11134207-820me-mpw7uha0l43ne2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F41232141739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23696393303', 'ABIB Heartleaf Calming Toner Skin Booster, 200ml', 'Produto: Tônico calmante Heartleaf Aumento da pele Fabricante: COSMAX, INC. País de Origem: Coreia do Sul Cuidado de uso 1. Pare de usar o produto se ocorrer vermelhidão, inchaço, irritação ou erupção cutânea quando a pele estiver expo seda à luz solar direta; se os sintomas persistirem, consulte um médico. 2. Não use em feridas ou outras áreas infectadas. 3. Manuseio e armazenamento de manuseio 1) Mantenha fora das crianças. 1 2) Mantenha fora da luz solar direta. 4. Evite o uso deste produto para crianças menores de 3 anos.', 124.09, 118.0, NULL, 'Beauty > Skincare > Toner', 'https://cf.shopee.com.br/file/sg-11134207-7rd3m-lvtps12lhi1653', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F23696393303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
