INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263482928', 'Creme de Avelã Lã Lã Com Cacau Zero Açúcar 150G', 'Creme de Avelã Lã Lã Com Cacau Zero Açúcar 150G O Creme de Avelã Zero Flormel é a combinação perfeita entre sabor e bem-estar. Com zero adição de açúcar, sem glúten e adoçado com taumatina, um adoçante natural, ele é ideal para quem busca uma alimentação equilibrada sem abrir mão de um doce delicioso. Fonte de fibras e com textura cremosa, é perfeito para consumir puro, com frutas, pães, panquecas ou no preparo de diversas receitas. Desenvolvido com ingredientes cuidadosamente selecionados, proporciona uma experiência irresistível em cada colherada, unindo qualidade, praticidade e muito sabor. Ingredientes Gordura vegetal, pasta de avelã, polidextrose, cacau em pó, leite em pó desnatado, soro de leite em pó parcialmente desmineralizado, edulcorantes maltitol e taumatina, emulsificantes mono e diglicerídeos de ácidos graxos, polirricinoleato de poliglicerol e lecitina de soja, aromatizante e antioxidante natural tocoferol. Alérgicos Não contém glúten. Contém lactose. Contém avelãs, leite e derivados. Pode conter amêndoas, amendoim, nozes, soja, castanha-do-caju, castanha-do-pará. Armazenamento O produto deve ser armazenado em embalagem fechada, em local livre de sujidades, protegido de umidade, luz, calor e do ataque de insetos e roedores.', 36.15, 28.92, NULL, 'Food & Beverages > Beverages > Chocolate Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8257u-mq4vmaiz1wxt4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674436044%2F58263482928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
