INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094155103', 'Bola Futsal Penalty Max 100 Xxiv Infantil Sub 9 e Sub 11 - Selo CBFS', 'Indicado para faixa etária entre 9 e 11 anosApresentamos a nova Bola de Futsal Penalty Max 100 Ultra Fusion , que é recomendada para Indicada para categoria Sub 9 e Sub 11 de futsal, uma escolha excelente para jogadores que buscam o melhor desempenho em quadra. Desenvolvida com tecnologia de ponta e materiais de alta qualidade, esta bola eleva o seu jogo para o próximo nível. A Bola de Futsal Penalty Max 100 Ultra Fusion proporciona maciez e conforto durante os toques, chutes e defesas, deixando o jovem confiante para marcar um golaço de bicicleta e ser o craque da partida. Benefícios: Maciez e conforto. Durabilidade. Velocidade no jogo. Alguns diferenciais técnicos : A Bola de Futsal Penalty Max 100 possui tecnologia Ultra Fusion utilizada em sua fabricação, que proporciona uma junção perfeita dos materiais, garantindo resistência e durabilidade superiores. Sua câmara 6D e sistema de forro Termofixo proporcionam uma resposta consistente em cada jogada. Camada Interna de Neogel oferece amortecimento superior e redução do impacto, proporcionando conforto e proteção aos jogadores. Eleve o seu jogo com esta bola de Futsal de última geração! Bola de Futsal Max 100 : adequada para faixa etária entre 9 e 11 anos.', 249.99, 249.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/sg-11134201-81zwk-mimr82i29zwn0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F919401703%2F23094155103', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56450658197', 'Ração VetLife Gastro-Intestinal para gatos adultos 2,0kg', 'Ração VetLife Gastro-Intestinal para gatos adultos 2,0kg Pet: Gatos Idade: Adultos Porte de Raça: Todas Condição: Gatos com problemas de absorção de nutrientes e reabilitações Tamanho de grão: Específico para todas as raças A Ração VetLife Gastro-Intestinal para gatos adultos é um alimento Super Premium desenvolvido para gatos com debilidades nutricionais de absorção intestinal de nutrientes. A Ração Vetlife garante em sua fórmula uma ótima qualidade de vitaminas e eletrólitos, rico em prébióticos MOS e FOS, boa quantidades de ômegas 3 e ingredientes de alta digestibilidade facilitante sua absorção. Por que a Ração VetLife Gastro-Intestinal para gatos adultos é um alimento Super Premium? Os alimentos Super Premium apresentam um nível nutricional mais elevado, e atendem os requisitos mínimos estabelecidos pelo Conselho de Nutrição Animal, os níveis nutricionais devem estar em equilíbrio entre os níveis mínimos e máximos apresentados pela AAFCO (Association of American Feed Control Officials). A Ração VetLife Gastro-Intestinal para gatos adultos foi produzida atendendo todos os requisitos. Esses níveis são determinados pelas pesquisas, que buscam ótimas condições de pelagem, desenvolvimento de musculatura e, principalmente, otimização de performance na reprodução e no sistema imunológico. Composição da Ração VetLife Gastro-Intestinal para gatos adultos Farinha de vísceras de aves, glúten de trigo, ovo em pó, amido de batata, , quirera de arroz, farinha de peixe, gordura de frango, óleo de peixe refinado, plasma suíno em pó, farinha de torresmo (proteína isolada de suíno), semente de linhaça, polpa de beterraba, aveia descascada, celulose, casca de ervilha, casca de psyllium, levedura seca de cervejaria, 