INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21798258321', 'Kit 2 Lâmpada LED 1034 12V 3W 2 Polos - Branca', 'Código: APAU021 Descrição: Lâmpada LED Bulb BAY15D (1034) BLISTER (embalagem) com 2 unidades A lâmpada LED Bulb BAY15D (1034) é utilizada para a iluminação externa do veículo. Os principais locais de utilização são: lanterna e freio. Design e alta eficiência com consumo extremamente baixo e tempo de vida altíssimo. Cores da Luz: Branca Características: • Modelo com 2 polos; • Tensão: 12V; • Potência: 3W; • Equivalência: 30W; • Intensidade luminosa: 360 lm (lúmens); • Ângulo de abertura: 120º; • Corrente: 12V - 250mA / 24V - 125mA Marca: AutoPoli ***ATENÇÃO*** COMPARE AS NUMERAÇÕES E DESCRIÇÃO DO ANÚNCIO COM A SUA PEÇA OU INFORMAÇÕES. EM NOSSO ANÚNCIO CONSTAM A MAIORIA DOS NÚMEROS DE CONVERSÃO PARA COMPARAR. CASO NÃO TENHA A NUMERAÇÃO QUE PROCURA, FAÇA UM PERGUNTA PARA QUE POSSAMOS LOCALIZAR A PEÇA EQUIVALENTE. EQUIPE DL AUTO PARTS.', 24.3, 24.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-matxpyum51ixf7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662883696%2F21798258321', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
