INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13232021739', 'Coleção 3 Livros | Coleção Pioneiros Pentecostais', 'Em 1911 Daniel Berg e Gunnar Vingren fundaram, junto com outros 18 irmãos, as Assembleias de Deus no Brasil. Eles deram início a maior igreja Pentecostal do Brasil, que têm pregado a salvação, o batismo no Espírito Santo, a cura e o retorno de Nosso Senhor. Além Deles muitos outros deram sua contribuição de dedicação e sacrifício para que a mensagem da chama pentecostal chegasse aos quatro cantos do país. Uma edição histórica, produzida para que as futuras gerações não se esqueçam que, naqueles dias, Deus agiu poderosamente em nosso país e sintam o desejo de celebrar e pregar a mensagem da chama pentecostal, cada dia, até a volta do nosso Senhor e Salvador Jesus Cristo. Está coleção é uma nova edição de luxo, valorizada por um novo layout e diagramação, galeria de fotos históricas inéditas, cronologia da vida e obra dos pioneiros. Número de Páginas: 360/288/240', 154.9, 154.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/1e1d8539ed19c98018268a7bfb26e642', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F13232021739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494720699', 'Eudora Club 6 Exclusive Desodorante Colônia 95ml', 'O Club 6 Exclusive Desodorante Colônia é a fragrância ideal para o homem exclusivo, que gosta de curtir a vida ao máximo e sabe o seu valor. Inspirado no momento de apreciação do whisky, Club 6 Exclusive traz uma sofisticada fragrância oriental que combina notas frescas frutais ao fundo robusto amadeirado, trazendo uma perfumação forte e sofisticada. Esta nova criação fica completa com o exclusivo acorde Single Malt, que recria as notas licorosas dos melhores whiskies das terras altas escocesas. Guardado por uma embalagem em forma de cantil, apresenta um design moderno que agrada quem quer aproveitar o melhor da vida. Quer saber como entrar com uma senha exclusiva para o seleto clube daqueles que gostam de aproveitar o melhor da vida? Experimente Club 6 Exclusive e descubra a exclusividade de viver uma vida incrível. Club 6, para ele que é exclusivo. Família Olfativa: Oriental Amadeirada ﻿ Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 154.9, 154.9, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-8261h-mjhifxas08p14f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F22494720699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14356924607', 'Regulador Retificador Cbx 200 Strada / Xr 200r / Nx 200 Magnetron', 'O regulador retificador tem a função de transformar a corrente alternada em contínua, regular a tensão para carregar a bateria e alimentar o sistema elétrico da motocicleta. Compatível com: HONDA XR 200 R (1994-2002) CBX 200 STRADA (1994-2002) NX 200 (1993-2001) Conteúdo da Embalagem: 01 Regulador Retificador Código da peça original: 31600-KRW-900 Especificações Técnicas: - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Tratamentos contra a oxidação - Confeccionado com a melhor matéria-prima - Melhor condutibilidade e maior vida útil da peça - Material leve e resistente - Ótimo acabamento, proporcionando uma instalação sem adaptações - Excelente qualidade e acabamento Características: - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Testado e aprovado dentro das normas de segurança. Importante: - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo mal uso do produto.', 124.9, 112.41, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdyq-mcgleedh3plg74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F14356924607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
