INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998990029', 'Esponja Banho Ricca Pequena 1Un', 'A esponja para banho Ricca é ideal para uso com sabonete líquido! Massageia a pele, ajudando a ativar a circulação sanguínea além de estimular a renovação celular, melhorando a aparência e deixando a textura da pele mais homogênea. Modo de uso: Umedeça a esponja em água e aplique o sabonete de sua preferência. Massageie a pele com movimentos circulares. #html-body [data-pb-style="646BA6483715B"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64837170"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 23.16, 23.16, NULL, 'Home & Living > Bathrooms > Bath Brushes & Loofahs', 'https://cf.shopee.com.br/file/sg-11134201-7rbl7-lmgjmmvkj8h547', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18998990029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
