INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194850981', 'Pneu 110/70-14 Vipal ST500 Dianteiro Tubeless PCX', 'Pneu Street ST500 110/70-14 50P Dianteiro Scooter Tubeless O Pneu Street ST500 110/70-14 50P Dianteiro Scooter é um pneu tubeless (sem câmara) projetado para scooters e motocicletas urbanas com roda dianteira de 14 polegadas. A tecnologia tubeless permite rodar sem câmara de ar, proporcionando melhor retenção de ar e menor probabilidade de perda de pressão repentina em caso de pequenos furos, além de facilitar a manutenção. Desenvolvido para uso em vias asfaltadas e pavimentadas, o ST500 oferece equilíbrio entre conforto, estabilidade e aderência no trânsito urbano e em deslocamentos rodoviários leves. O perfil 110/70 contribui para uma direção responsiva e boa absorção das irregularidades do piso. O índice de carga 50P indica que o pneu é capaz de suportar até 190 kg por unidade com velocidade máxima de operação de até 150 km/h, compatível com a maioria dos scooters de baixa e média cilindrada que utilizam esse diâmetro e especificação. O composto de borracha e o desenho da banda de rodagem foram desenvolvidos para oferecer tração eficiente tanto em piso seco quanto molhado, com sulcos que auxiliam na dispersão de água e maior segurança em condições de chuva. Importante: o anúncio refere-se apenas ao pneu dianteiro tubeless. Não acompanha câmara de ar, rodas ou quaisquer outros acessórios. Especificações Técnicas Tipo: Pneu tubeless (sem câmara) Posição: Dianteiro Medida: 110/70-14 Índice de carga / Velocidade: 50P Aplicação: Scooters e motocicletas compatíveis Uso: Pavimentado / urbano e rodoviário leve Banda de rodagem: desenho para boa tração e dispersão de água', 415.9, 353.52, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-8262j-mkvgu2peq29s26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F23194850981', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
