INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998235276', 'Óleo Direção Hidraulica Câmbio Automático Tutela 10w Tasa 1l', 'Apresentamos o Óleo Direção Hidraulica Câmbio Automático Tutela 10w Tasa 1l, um produto de alta qualidade da marca Petronas. Este óleo mineral é especialmente formulado para carros, picapes e SUVs, proporcionando uma direção suave e eficiente. Com um volume de 1 litro, este produto é perfeito para manter o seu veículo em ótimas condições. O Óleo Direção Hidraulica Câmbio Automático Tutela 10w Tasa 1l vem em uma garrafa prática, tornando-o fácil de usar e armazenar. Com uma viscosidade de 10w, este óleo é ideal para uma ampla gama de temperaturas, garantindo que o seu veículo funcione de maneira eficiente em qualquer clima. Este produto é parte da linha automotiva da Petronas, uma marca conhecida por sua qualidade e confiabilidade. Com apenas uma unidade por embalagem, você tem a certeza de que está recebendo um produto novo e não utilizado. Além disso, o volume líquido de 1 litro garante que você terá óleo suficiente para manter o seu veículo funcionando sem problemas. O Óleo Direção Hidraulica Câmbio Automático Tutela 10w Tasa 1l é uma escolha inteligente para quem se preocupa com o desempenho e a longevidade do seu veículo. Não perca a oportunidade de adquirir este produto de alta qualidade e manter o seu veículo em perfeitas condições.', 44.0, 44.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rd49-m6sepc1do57nb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463823458%2F22998235276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
