INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13854056229', 'Farol Civic 2012 2013 2014 2015 Foco Duplo Máscara Negra', 'Código do produto: 4157 O farol é uma peça essencial para sinalização e visibilidade em vias noturnas e para maior segurança eles devem estar sempre em bom estado. E aqui temos o produto ideal para você. Este item possui material de alta qualidade e resistência, composto com sua lente em acrílico lisa, encaixe da lâmpada HB3 / H11 que suporta até 55W e um design que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Honda - Civic 2012 - Civic 2013 - Civic 2014 - Civic 2015 Especificações Técnicas: - Foco Duplo - Regulagem Manual - Encaixe da lâmpada HB3 / H11 - Lente Lisa - Material da Lente em Acrílico - Material da Carcaça em Plástico - Suporta lâmpadas de até 55W ATENÇÃO Garantia - 3 Meses O valor anunciado referente a Unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 757.34, 757.34, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/ab4b860e736c14bbbd27422c434d9cb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F13854056229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
