INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497451961', 'Pek Pré Powder 1kg Polimento Porcelanato Pisoclean', 'PEK PRÉPOWDERÉ um exclusivo pó abrasivo de preparação do revestimento para o lustre final.Com alto poder de corte, este produto é ideal para a preparação dos revestimentos antes da utilização dePek Powder, em todas suas versões.Pek Pré Powder é indicado para a correção de acabamentos defeituosos, remoção de riscos, sujeiras infiltradas e manchas causadas por ataques químicos, em diversos tipos de revestimentos.Pek Pré Powderpossibilita que o piso que será tratado comPek Powderfique com um brilho muito mais nítido e intenso.Também pode ser utilizado para a recuperação de pisos acetinados ou anticatos, de forma a promover a textura e a aparência original do revestimento tratado.ONDE USARAmbientes:Áreas internas, Áreas externas.', 239.75, 239.75, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7rceu-ltwpr7g7lb59db', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F22497451961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597983400', 'Aditivo Rejunte Facilita a Limpeza do Rejunte Impermeabiliza Rejuntes Resistente À Umidade 1 Litro', 'HIDROREPEL VEDA REJUNTE ADITIVO PARA REJUNTE Base Água Propriedades HIDROREPEL VEDA REJUNTE é um aditivo acrílico, especialmente formulado para rejuntamentos à base de cimento Portland. Melhora as características do rejuntamento dando-lhe maior flexibilidade, resistência a desgastes e manchas, e facilita a limpeza de manutenção. Evita o esfarelamento, rachaduras do rejunte. HIDROREPEL VEDA REJUNTE não altera a coloração do rejunte proporciona um aspecto natural, valorizando e protegendo e protegendo o rejunte dos danos causados pela umidade e infiltrações Vantagens HIDROREPEL VEDA REJUNTE se usado corretamente, proporciona ao rejuntamento os seguintes benefícios: • Redução de impregnação de sujeiras; • Facilita a limpeza; • Melhora o acabamento; • Aumenta a vida do rejuntamento; • Minimiza a marca d’água; • Aumenta a durabilidade. Instruções de Uso HIDROREPEL VEDA REJUNTE é recomendado para todos os tipos de rejuntamento cimenticio, junta fina e junta larga principalmente quando se deseja características de maior plasticidade da mistura e impermeabilidade por período longo. HIDROREPEL VEDA REJUNTE pode ser aplicado em rejunte de uso externo e interno. HIDROREPEL VEDA REJUNTE é utilizado em substituição da água de amassamento do rejunte tomando como base a consciência ideal requerida para aplicação. Utiliza-se em média ,1 litro de hidrorepel veda rejunte para cada 5kg de rejunte.', 38.93, 25.31, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m30mn4jcy5ed00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F19597983400', NULL, NULL, '2026-07-28T02:1