INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597140777', 'Mangá - Frieren E A Jornada Para O Além - 09', 'Frieren E A Jornada Para O Além - 09 Acompanhe a maga Frieren em sua jornada para ''conhecer os humanos''. Seu interesse neles e em suas histórias surgiu depois que ela perdeu seu amigo, o herói Himmel.O destino final dessa aventura é Aureole, a terra onde as almas dormem. Lá também se encontra o castelo do Rei Demônio.Continuando rumo ao Planalto Norte, Frieren e seus companheiros se deparam com um dos Sete sábios da destruição, Macht, o Eldorado.Esta história reflete as memórias que restaram na Cidade de Ouro.''Uma fantasia pós-aventura'' que delineia ''o passado'' dos heróis! Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Kanehito Yamada ISBN: 9786525905051, 978-65-259-0505-1 Check-List: Novembro/2023 Classificação Etária: 16 anos Demografia: Shonen Editora: Editora Panini Número de páginas: 194 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 24/11/2023 Idioma: Português Condição: Novo/Lacrado', 50.9, 50.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg8cnoe437d161', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F23597140777', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
