INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42705346818', 'Chinelo Feminino Slide Usaflex Chinelo Poofy Plataforma Eva Conforto Leve e Macio', 'Combinação perfeita entre conforto, leveza e estilo. Confeccionado em EVA injetado, oferece alta resistência, durabilidade e praticidade no dia a dia. Seu design moderno com bico arredondado e acabamento minimalista proporciona um visual atual e versátil, ideal para compor looks casuais e descontraídos. A plataforma de aproximadamente 3,5 cm traz mais estabilidade na pisada, além de garantir um toque de modernidade ao calçado. A sola texturizada oferece maior aderência e segurança ao caminhar, enquanto o material em EVA proporciona leveza, flexibilidade e conforto extremo, além de ser resistente à água e ser super fácil de limpar. Perfeito para quem busca praticidade sem abrir mão do estilo, o Slide Poofy é indicado para diversas ocasiões, como uso diário, home office, passeios e até momentos de lazer. Além disso, sua construção sem partes metálicas evita o acúmulo de odores e facilita a higienização. Um calçado que une funcionalidade, conforto e um design que acompanha as tendências atuais. Composição do Calçado: Marca: Usaflex Material: Eva 100% Guia Tamanhos: Nº 35 – 23,5 CM Nº 36 – 24,0 CM Nº 37 – 25,0 CM Nº 38 – 26,0 CM Nº 39 – 26,5 CM Nº 40 – 27,0 CM', 165.9, 99.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb8dkqfpl5zja9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F287287585%2F42705346818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
