INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394361531', 'Limpador Automotivo Sintra Fast Vonixx 500ml Higienizador Interno Multilimpador', 'Quer manter o interior do seu veículo limpo, higienizado e livre de odores? Características do Produto – Multilimpador flotador universal de pH balanceado – Ação bactericida e fungicida: elimina até 99,9% de microrganismos – Seguro para painéis, cantos de portas, carpetes, estofados, couro, vinil, plásticos e superfícies emborrachadas – Conteúdo: 500 ml – Cor: verde; odor característico – Densidade: 1,00 a 1,02 g/cm³ – Marca: Vonixx Por que escolher este produto? – Limpeza rápida de sujeiras, manchas e odores – Pronto para uso, sem necessidade de diluição – Seguro para várias superfícies, sem brilho artificial ou resíduos oleosos – Mantém o ambiente do veículo saudável e agradável Dicas de Uso – Pulverizar diretamente na superfície – Espalhar com pincel, escova macia ou aplicador de espuma – Remover o excesso com pano de microfibra úmido – Secar com pano de microfibra seco Perguntas Frequentes (FAQs) – Pode ser usado em estofados e carpetes? Sim, é indicado para tecidos, couro e carpetes. – Elimina bactérias e fungos? Sim, elimina até 99,9% deles. – Precisa diluir o produto? Não, o produto já está pronto para uso. Garanta agora Sintra Fast Vonixx 500ml Higienizador Interno!', 49.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-820nt-mnncyvq9efpfeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552175911%2F22394361531', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797284305', 'Kit 10 Lâmpada Filamento LED G80 4W E27 LUZ QUENTE (AMARELO) Âmbar Retrô Vintage 110V~220V | Bivolt', '💡 Lâmpada LED Decorativa - Iluminação Aconchegante e Estilizada! 💡 Destaque-se com nossa incrível lâmpada LED decorativa, proporcionando uma iluminação aconchegante e estilizada. Confira as características que fazem dela a escolha ideal: 🔍 Especificações Técnicas: 💡 Potência: 4W - Oferece uma iluminação suave e acolhedora. ⚡ Tensão: 85-265V AC - Compatível com diversas redes elétricas. 🔆 Lúmens: 750 LM - Iluminação intensa para realçar o ambiente. 📐 Ângulo de Abertura: 360° - Distribuição uniforme da luz em todas as direções. 🌡️ Cor: BQ 2300K - Luz âmbar para criar uma atmosfera acolhedora. 💡 Fator de Potência: >0,5 - Eficiência energética. ⏳ Vida Útil: 20.000 horas - Durabilidade para uso prolongado. 🎨 IRC (Índice de Reprodução de Cor): RA 75 - Cores mais reais e vibrantes. 💧 IP (Índice de Proteção): IP20 - Adequado para uso interno. 🛡️ Garantia: 1 ano - Confiança e tranquilidade. 📏 Dimensões: 80x125 mm - Design compacto e versátil. ⚖️ Peso: 8,3 gramas - Leve e fácil de instalar. 🎨 Cor do Material: Âmbar - Agrega estilo e elegância. ✨ Destaque-se com Estilo! A lâmpada LED decorativa é perfeita para criar uma atmosfera única e aconchegante em qualquer ambiente. Com garantia de 1 ano, ela oferece não apenas iluminação, mas também um toque de estilo e sofisticação. 🌟 Nota Importante: 🛡️ Todos os nossos produtos possuem garantia. Estamos à disposição para resolver qualquer divergência. Entre em contato conosco após a compra para soluções adequadas.', 280.0, 162.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lq4u1shj4h0f6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F979730489%2F22797284305