INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45200829037', 'Camiseta Oversized Shopito Chaveiro', 'Camiseta Basic Oversized A Camiseta Basic Oversized foi desenvolvida para quem busca uma modelagem exclusiva, leve e confortável. Produzida em 100% algodão fio 30.1 penteado, ela conta com acabamento ULTRA, que proporciona toque macio e caimento perfeito. A gola tem anel de 3 cm, ribana canelada 2×1 com elastano e pesponto de 2 agulhas, garantindo maior estrutura e durabilidade. Além disso, possui reforço ombro a ombro, conferindo resistência extra à peça. Atenção As fotos podem apresentar variações de cor devido à iluminação e ao dispositivo As medidas das peças podem ter pequenas variações Em produtos de algodão, pode ocorrer encolhimento de 3% a 5% após a lavagem Informações Técnicas Composição: 100% algodão fio 30.1 penteado Gramatura: 180 g/m² Gola: Anel de 3 cm, ribana canelada 2×1 com elastano e pesponto de 2 agulhas Reforço: Ombro a ombro para maior durabilidade Acabamento: Bainha de 2 cm Etiqueta interna: Composição e tamanho Recomendações de Conservação Lavar à mão ou em ciclo delicado Não usar alvejantes Secar à sombra para preservar a tonalidade Passar com ferro em temperatura baixa', 129.9, 129.9, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjk88msy62gz7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F656490260%2F45200829037', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42672486176', 'Tênis Infantil Klin Laço Menina - Rosa', 'Sua pequena vai desfilar ainda mais linda e confortável com o Tênis Infantil Klin Laço Menina, perfeito para todos os momentos. Confeccionado em material têxtil, tem solado emborrachado com acabamento antiderrapante, palmilha macia e fechamento ajustável. Combine com lookinhos casuais. O toque de cuidado e delicadeza que não pode faltar no dia a dia! Compre já!', 169.9, 149.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-824jc-mfa3joyue6tk36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1178125772%2F42672486176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
