INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199728154', 'Cama Infantil Casal Montessoriana Completa Móveis', 'A Cama Casal Infantil de Chão Montessoriana para Menino e Menina com Grade de Proteção Lateral traz o melhor do estilo montessori para o quarto do seu filho. Um conceito lúdico para estimular a autonomia e aperfeiçoar o potencial criativo das crianças desde a primeira infância, trazendo leveza e um toque diferenciado no design. Não acompanha colchão Colchão indicado (L x P x A): 188x138x12 cm Peso suportado pela cama: 160 kg ESPECIFICAÇÕES DO PRODUTO Altura: 36 cm Largura: 144,90 cm Comprimento: 194 cm Material: MDP Estrado: MDF de 6 mm Suporte do estrado: madeira maciça de 35 mm CORES DISPONÍVEIS Branco Aveiro Oak com Branco INFORMAÇÕES IMPORTANTES Produto entregue desmontado Montagem não inclusa Montagem direita ou esquerda Produto composto por 1 volume Peso total do produto: 44,80 kg Não possui rodízios Acompanha protetor lateral Acompanha manual de montagem DICAS DE MONTAGEM Forre o chão com o próprio papelão da embalagem. Separe as peças e acessórios conforme o manual. Verifique se todas as peças foram recebidas corretamente. Use um pano levemente umedecido com água, seguido de pano seco. Não utilize produtos químicos ou abrasivos.', 1064.9, 789.0, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-8261q-mjy652ieshza48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229193285%2F18199728154', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
