INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19098468112', 'Máscara Coco Poderoso DaBelle Hair 400g', 'A Máscara Coco Poderoso é a solução perfeita para hidratar e nutrir profundamente seus fios. Com o poder da manteiga, leite e água de coco, ela proporciona uma reparação intensa para cabelos ressecados e danificados, deixando-os revitalizados e brilhantes. O que ele é: A Máscara Coco Poderoso é um tratamento capilar enriquecido com ingredientes naturais como manteiga de coco, leite de coco e água de coco. Sua fórmula rica e nutritiva oferece hidratação profunda, reparação intensa e proteção contra danos, devolvendo vitalidade aos fios. Ações: Manteiga de Coco: Possui alto poder umectante, promovendo uma nutrição ultra profunda e reparando os fios danificados. Leite de Coco: Rico em proteínas, vitaminas e ácidos graxos, hidrata, nutre e protege sem pesar nos fios. Água de Coco: Com açúcares, aminoácidos e sais minerais, hidrata e protege a fibra capilar, mantendo a saúde e a vitalidade dos fios. Resultado no cabelo: Os cabelos ficam extremamente hidratados, mais fortes e brilhantes. Com a ação nutritiva da máscara, os fios ganham suavidade, maciez e uma aparência saudável, com redução de frizz e maior controle. Modo de uso: Aplique por todo o cabelo uma quantidade suficiente pra enluvar os fios. Massageie da raiz às pontas e penteie delicadamente com os dedos ou com um pente de dentes largos. Deixe agir por 3 minutos e enxágue bem. Se preferir uma hidratação mais poderosa, use touca por 5 minutos.', 25.9, 25.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjk83nfo2zgj37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939411398%2F19098468112', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
