INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497477198', 'Inoar Kit Cicatrifios Completo 4 Produtos', 'Inoar Kit Cicatrifios Completo 4 Produtos Kit de tratamento para cabelos de todos os tipos, danificados. O Kit Inoar Cicatrifios Renovação Absoluta hidrata intensivamente e diminui a queda, o frizz e o volume. Com ingredientes da plástica capilar com ativos emolientes para proporcionar resultados instantâneos. Assim, disciplina os fios, amacia, fortalece, protege a coloração e facilita a escovação com durabilidade. Ação: RejuComplex3: promove recuperação da fibra capilar, sela os fios e reduzindo gradativamente o volume. Reduz o frizz e a quebra, uma plástica para fios disciplinados e renovados. Conselho de Aplicação: Lave os cabelos com o Shampoo, enxágue. Em seguida, aplique a máscara e deixe agir de 2 à 5 minutos, enxágue. Aplique o Condicionador deixe agir por 3 minutos enxágue. Passe o Leave-in protetor térmico sobre a extensão dos fios, com os cabelos úmidos, antes de utilizar secador e chapinha. Sem enxágue. Contém: 1- Shampoo 1litro 1- Condicionador 1litro 1- Máscara 500g 1- Leave-in 50ml', 161.44, 145.3, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rd4f-lul3cwxt7wzx44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290896931%2F22497477198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498222778', 'Sandália Chinelo Kenner Summer Degradê Original Masculino', '🩴 Sandália Chinelo Kenner New Summer Original Unissex O Chinelo Kenner New Summer é a escolha ideal para quem busca conforto, resistência e estilo atemporal. Desenvolvido com materiais de alta durabilidade, oferece leveza e aderência para todos os momentos do dia. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/22893536127/ ✅ Diferenciais do Chinelo Kenner New Summer 👣 Palmilha macia e anatômica, proporcionando conforto em cada passo. ⚡ Solado de borracha extragrip, com alta tração e durabilidade. 🖤 Design moderno e versátil, ideal para o dia a dia ou lazer. 🌊 Resistente à água, perfeito para praia, piscina e momentos descontraídos. 🔝 Produto Kenner Original, referência em qualidade e estilo no segmento de sandálias e chinelos. 📏 Tabela de Medidas – Chinelo Kenner New Summer 37 – 25,0 cm 38 – 25,5 cm 39 – 26,0 cm 40 – 26,5 cm 41 – 27,0 cm 42 – 27,5 cm 43 – 28,0 cm 44 – 28,5 cm (Recomenda-se escolher a numeração habitual para melhor ajuste.) 👉 O Kenner New Summer é um chinelo que une design, conforto e durabilidade, sendo indispensável para quem busca qualidade em cada detalhe.', 129.9, 99.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rcdq-m6gwxtmvof4rd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F22498222778', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
