INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56302897435', 'Bau Motoboy Entrega Carga 90 Litros Resiplastic Maxx Preto', 'Baú para carga motoboy reforçado 90 litros Características: Marca: Resiplastic Capacidade de 90 litros Cor: Preto Modelo: Max Aplicação: Produto de aplicação universal (é necessário a moto possuir o bagageiro específico para a fixação do baú) Não acompanha parafusos Material: Polipropileno Dimensões: 50cm x 47cm x 50cm (comp x larg x alt) Peso Máximo suportado: 6,6Kg. Conteúdo da embalagem: 1 Baú 90 litros 1 kit de arruelas para instalação Sobre a Resiplastic: QUAL É A TECNOLOGIA APLICADA NA PRODUÇÃO DO BAÚ PLÁSTICO PARA MOTO? Uma das empresas mais reconhecidas pelo trabalho de pesquisa e tecnologia aplicada na produção de uma imensa variedade de produtos obtidos do polietileno, como o baú plástico para moto , é a Resiplastic, empresa especializada na técnica de rotomoldagem. A rotomoldagem consiste na manipulação do termoplástico utilizando temperaturas distintas. O choque térmico decorrente dessa ação resulta em um material de altíssima qualidade para a produção do baú plástico para moto. Outra característica é que, diferente do processo de injeção no qual o plástico tem a forma granulada, a rotomoldagem utiliza material de base em pó, o que facilita no processo de derretimento e fusão como um todo, colaborando para criar a superfície uniforme e de qualidade superior ao molde. Código do fabricante: 1900', 348.9, 348.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/sg-11134201-822x2-mi3hi31buk1t72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1297313782%2F56302897435', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
