INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697761386', 'Aparelho De Jantar 30 Peças Ryo White Oxford', 'Aparelho De Jantar 30 Peças Ryo White OxfordBuscar a beleza no imperfeito: essa é a premissa de uma filosofia japonesa muito inspiradora. O conceito se tornou uma grande tendência de design que aposta no uso de formas orgânicas e naturais. O aparelho de jantar, chá e café Ryo White segue essa tendência e traz peças com formatos sinuosos. Louças lindas que apostam na imperfeição e na autenticidade. O nome Ryo é uma palavra em japonês que significa excelente. Incluso: 6 Pratos Rasos - 27,5 cm 6 Pratos Fundos - 21 cm 6 Prato Sobremesa - 21,5 cm 6 Pires De Chá - 16 cm 6 Xícaras De Chá - 200 ml Informações: Uso: Resistente a micro-ondas, resistente a lava-louças Material: Porcelana Formato: Sinuoso Decoração: Liso Marca :OXFORD Garantia :03 Meses contra defeitos de fabricação.', 694.84, 694.84, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-lztdrotd47ifa0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22697761386', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898697366', 'Balcão Cantinho do Café Reims 2 Portas Branco Madesa', 'Balcão Cantinho do Café Reims 2 Portas Branco Madesa Características: - O Balcão Cantinho do Café, da linha Reims da Madesa, é a opção perfeita para deixar o seu ambiente muito mais charmoso. - O balcão acompanha tampo e a parte interna é dividida entre uma prateleira e dois nichos, espaço ideal para organizar a louça, a máquina de café, outras bebidas e o que mais você preferir. - Além de puxadores embutidos em alumínio na coloração marrom e dobradiças metálicas, possui também pés em madeira muito bonitos e resistentes. - O acabamento é branco, feito com a Pintura Poliéster ecológica com sete camadas, exclusiva da Madesa. Esse método oferece proteção contra os efeitos da água e do calor. Especificações Técnicas: - Marca: Madesa - Modelo: Reims - Cor: Branco - Material: Mdp - Itens inclusos: Um (1) Balcão com duas (2) portas - Dimensões aprox. do produto: Altura: 83cm X Largura: 70cm X Profundidade: 52cm - Peso Aproximado: 22 Kg - Garantia: 3 meses contra defeito de fabricação', 369.99, 369.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rdx5-mc172p4u6c3k1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F23898697366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
