INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797376787', 'Mop Giratório Cabo Inox + Refil Limpeza Balde Esfregão 360 Spin Original Powermaid', '***PRODUTO PRONTA ENTREGA COM ENVIO IMEDIATO*** MOP ESFREGÃO GIRATÓRIO SPIN PRO MASTER 360 BALDE E CABO INOX PRÁTICO - DURÁVEL - EFICIENTE O Mop Giratório FIT é composto por um balde com centrifuga . Para usar, basta colocar água no balde de enxágue e ele está pronto! O balde de centrifugação conta com um cesto de para facilitar o escoamento da água ao término de sua utilização. O cabo de aço inox é leve, resistente e possui altura variável até 1,25cm Conteúdo: 1 Balde para centrifugar e enxaguar 1 Cabo telescópico 2 Refis de microfibra O que é Microfibra? É um tecido composto de fios ultrafinos de poliéster. Sua estrutura permite uma limpeza profunda sem danificar as superfícies. Os fios de microfibra possuem um alto poder de absorção, o que reduz ou até elimina o uso de produtos químicos. Mais Características: - Cabo com regulagem de altura máxima até 1,25cm - Capacidade em uso do balde: 8L - Capacidade Total: 4L - Base do Mop flexível permite alcançar áreas de difícil acesso - Alça flexível para facilitar o transporte e manuseio - Cabo em Aço Inox - Balde de plástico - Balde com rodízios - O refil pode ser lavado na máquina de lavar Refil adequado: refil mop giratório universal.', 65.9, 57.9, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-llmibsvzylzue1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F21797376787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
