INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58212531979', 'Caminhão Miniatura IVECO Betoneira Bi-Truck Teto Alto Brinquedo Infantil Colecionável', 'Caminhão Miniatura IVECO Teto Alto Bi-Truck Betoneira – Brinquedo, Coleção e Decoração O Caminhão Miniatura IVECO Teto Alto Bi-Truck Betoneira é ideal para quem aprecia caminhões, veículos de obra, miniaturas realistas ou busca uma peça diferenciada para decoração, coleção ou presente. Inspirado nos tradicionais caminhões betoneira utilizados na construção civil, o modelo apresenta um design robusto, cabine de teto alto e estrutura bi-truck, que garantem um visual mais imponente e chamativo, valorizando ainda mais a peça. Destaques do produto: ✓ Miniatura inspirada em caminhão betoneira ✓ Cabine teto alto com visual imponente e realista ✓ Estrutura bi-truck que valoriza o design ✓ Ideal para colecionadores e entusiastas de veículos ✓ Ótimo para decoração de prateleiras, mesas e nichos ✓ Excelente opção de presente para fãs de caminhões ✓ Peça compacta, detalhada e fácil de expor ✓ Indicado para coleção, brincadeira leve e decoração temática Perfeito para quem ama o universo dos caminhões, construção civil e miniaturas automotivas, ou deseja compor ambientes com peças diferenciadas e cheias de personalidade. Adicione agora essa miniatura à sua coleção e deixe seu espaço com muito mais personalidade!', 119.9, 89.9, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-820ly-mpi91bfqv1mp8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1547749545%2F58212531979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
