INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993534297', 'Kit 6 Buchas GP7 Balança Traseira CB 300R Honda 09/15', 'O Kit de Buchas da Balança Traseira GP7 foi projetado para proporcionar alta durabilidade, firmeza e segurança à sua motocicleta. Produzidas em material de alta resistência, as buchas asseguram o encaixe perfeito da balança traseira, eliminando folgas, reduzindo ruídos e mantendo a suspensão em ótimo funcionamento. Composto por 6 peças, este kit é específico para a Honda CB 300R (2009 a 2015), garantindo uma manutenção prática e confiável para restaurar a estabilidade e o desempenho original da moto. Benefícios Elimina folgas e ruídos na balança traseira Aumenta a estabilidade e a dirigibilidade segura Preserva a vida útil da suspensão e da balança Kit completo com 6 peças para substituição prática Alta durabilidade e qualidade GP7 com encaixe preciso Compatibilidade Compatível com os seguintes modelos Honda: CB 300R (2009 a 2015) (Antes da compra, confirme a compatibilidade no manual da moto ou com seu mecânico de confiança.) Informações Importantes para o Cliente Produto novo, reforçado e com encaixe original para CB 300R. Instalação simples, sem adaptações. A Kizz Moto Peças garante envio rápido, seguro e bem embalado, além de suporte especializado antes e depois da compra. Motivos para Comprar na Kizz Moto Peças Loja especializada em motopeças, referência em confiança e qualidade Trabalhamos apenas com marcas reconhecidas como GP7, Texx e Darom Envio ágil e seguro para todo o Brasil Atendimento humanizado e suporte técnico dedicado Excelente custo-benefício aliado à durabilidade comprovada Adquira agora o Kit 6 Buchas GP7 da Balança Traseira para Honda CB 300R (2009 a 2015) e mantenha sua moto sempre estável, firme e pronta para rodar com segurança. Imagens Meramente Ilustrativas', 95.9, 71.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-824gj-mege0t2nkbuo47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1117095756%2F22993534297', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26320024551', 'Melado de Cana 300g Orgânico - Guimarães', 'O melado de cana é livre de gorduras, além de ser fonte de vitaminas e minerais fundamentais para manutenção da vitalidade do organismo. O xarope é rico em vitaminas do complexo B, cálcio, cobre, ferro, magnésio e selênio. O superalimento é ainda uma opção incrível para pessoas que seguem uma dieta vegetariana/vegana, pois é um produto de origem vegetal. Ingredientes: caldo de cana de açucar. ALÉRGICOS: NÃO CONTÉM GLUTEN.', 35.5, 35.5, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Honey & Maple Syrups', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3hy514rv55n3c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F657120589%2F26320024551', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793262715', 'Mesa de Escritório Kuadra II Nogal 150 cm', 'Que tal a Mesa de Escritório Nikki?Seja no home office ou no cantinho do dormitório que você reservou para trabalhar, a Mesa Nikki tem todas as características indispensáveis para compor seu ambiente: estrutura funcional e produzida com materiais de boa durabilidade, design perfeito e muito bom gosto. Com tampo que dá espaço para que você acomode livros, objetos decorativos e, claro, o notebook, além daqueles itens de escritório que precisam ficar fáceis de alcançar durante a rotina, ela é um apoio bem versátil e fácil de personalizar. Para melhorar, ela tem tonalidade sóbria ideal para casar com a cadeira e com o restante da decoração, deixando o lar-style ainda mais impecável.', 629.99, 629.99, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-824jk-mfblz5cq5iq377', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226120317%2F23793262715', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
