INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497378325', 'Teclado Mecânico Gamer Led Abnt2 Usb Para Pc Computad - Knup', 'Teclado Gamer Mecânico de Led Luminoso RGB com Switch Red Profissional com interação de diversas efeitos de cores! Projetado para uma boa escrita e especialmente para jogos, conta com switches Red mecânicos, Luzes de led com efeitos de retro iluminação RGB, atendendo todos os requisitos de um gamer de respeito! Possuindo sistema de teclas mecânicas que separam cada botão individualmente sem membrana permitindo o pressionamento simultâneo de várias teclas (Anti-ghosting) resultando em respostas muito mais rápidas. Conta com 12 efeitos de retro iluminação Led RGB, podendo alterná-los manualmente e 5 funções de teclas predefinidas com opção de definir as teclas que deseja iluminar dando iluminação centralizada e uma cobertura de luz mais uniforme no topo para facilitar a identificação de cada letra. Inclui um apoio de punho removível que proporciona suporte e conforto durante o uso prolongado, oferecendo maior comodidade e flexibilidade. Compatível com Xbox Series X/S, Playstation 4 e 5 jogue com mais precisão e rapidez e em seu console! Características: - Numero de teclas: 107 - Material: Plastico e Metais - Teclas Ejetáveis para limpeza ou troca - Iluminação nas teclas com iluminação Rainbow podendo alterar 12 efeitos de cores - Tecnologia Anti-ghosting para sobreposição de até 25 teclas - Teclas com Switch Mecânico Outemu: Red com toque amortecido e macio - Curso de acionamento das teclas de 2mm - Curso total das teclas de 4mm - teclas multimídia suas teclas são macias e possuem som, assim você não fica em dúvida se a tecla foi acionada ou não - Tem conexão USB 2.0 que transmite com maior rapidez seus comandos para o CPU - Comprimento do cabo: 1,7 metros - Vida útil botões: 80 milhões de cliques - Teclas com padrão Brasileiro ( ABNT2 ) - Compatível com Windows 2000 / XP / 2003 / Vista / Win 7 / Win 8 / 10 e 11 / Linux e MAC - Apoio de punho removível, maior conforto na digitação - Dimensões: 43,8 x 13,6 x 4cm (LxCxA) - Peso aprox: 1k g Itens inclusos: 1 Teclado Gamer Mecânico Gaming Focused:Yes Connection Type:Wired Model Name:Kp-te121', 550.0, 158.76, NULL, 'Computers & Accessories > Keyboards & Mice > Keyboards', 'https://cf.shopee.com.br/file/sg-11134201-7rd3w-m7ks6ar1l05w71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373745451%2F23497378325', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
