INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793658887', 'Deo Colônia Masculino Smell for Men 15ml - Amakha Paris', 'Conheça o Perfume Ambarado Amadeirado, uma fragrância que personifica a postura decidida do homem que o usa. Esta composição olfativa única é uma expressão autêntica de confiança e determinação, perfeita para o homem moderno que enfrenta desafios com coragem e determinação. Use este perfume para marcar presença em qualquer situação. Deixe sua postura decidida e sua confiança inabalável brilharem, enquanto você enfrenta cada desafio com coragem e determinação. ✅ Referência olfativa: Black XS Men. ✅ Família Olfativa: Ambarado Amadeirado. ✅ Notas Olfativas: • Topo: Limão e Sálvia • Corpo: Pralinê, Canela, Tolú Bálsamo e Cardamomo Preto • Fundo: Pau-Rosa, Patchouli ou Oriza e Âmbar Negro Indicações: ✔️ Ocasião: Noite. ✔️ Estação: Inverno / Outono. ✔️ Momento: Sedução. ✔️ Perfil: Conquistador. Modo de Uso: Aplique o perfume nos pontos de pulsação (pescoço, pulsos, atrás das orelhas). Borrife a cerca de 15–20 cm da pele e evite esfregar os pulsos após a aplicação. Para maior fixação, aplique sobre a pele limpa e hidratada. ✨ Por que escolher? ✔ Inspirado no perfume Black XS Men ✔ Tamanho prático: 15ml (leve para onde quiser) ✔ Perfeito para usar em ocasiões especiais e encontros noturnos', 50.0, 32.5, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhkisjmi677lef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F22793658887', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10688001685', 'Ração Royal Canin Veterinary Nutrition Urinary Small Dog para Cães de Raças Pequenas com Doenças Urinárias - 7,5Kg', '- Com transgênico; - Auxiliar a dissolução de cálculos urinários; - Fornece concentração moderada de proteínas; - Fornece quantidade adequadas de minerais como o cálcio, fósforo e magnésio pois o excesso ou a falta destes predispões à formação de cálculos.', 477.9, 382.32, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/3ebe22fab09dbbf822a5475494dfec60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F10688001685', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21499004924', 'Palheta Limpador Para-Brisa Gm Opala 1968 a 1988 - 198438 - PVT15', 'Palheta Limpador Para-Brisa Gm Opala 1968 a 1988 198438 PVT15 (Lado - Motorista / Passageiro) (15") (Conexão Baioneta) Os limpadores combinam duas tecnologias mecânicas. A primeira delas é uma combinação de motor elétrico com engrenagem redutora. Ela é responsável por gerar a força necessária para acionar os limpadores. A segunda delas é um inteligente sistema de transmissão por hastes, ela converte a rotação de saída do motor no movimento dos limpadores para de um lado para o outro.Elas funcionam como uma espécie de rodo. Estas hastes arrastam uma fina tira de borracha com a função de retirar a água.', 22.5, 22.5, NULL, 'Automobiles > Automobile Spare Parts > Windshield Wipers & Washers', 'https://cf.shopee.com.br/file/sg-11134201-7rbkz-lmsb7mvy6iq3a0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21499004924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797903700', 'SANADOG 500 ML', 'A Nutrisana é uma marca especializada em suplementos alimentares para cães e gatos. Seus produtos são desenvolvidos para promover a saúde e o bem-estar dos pets, oferecendo nutrientes essenciais para diferentes fases da vida e necessidades específicas. Aqui estão alguns dos produtos oferecidos pela Nutrisana: Suplementos Alimentares: Incluem opções como glutamina, betaglucanas e zinco, que ajudam a fortalecer o sistema imunológico e a saúde geral dos pets12. Antiparasitários e Vacinas: Produtos destinados a proteger os animais contra parasitas e doenças comuns1. Produtos Dermatológicos e Estéticos: Incluem shampoos e outros itens para cuidados com a pele e pelagem1. Higiene e Educação: Produtos que ajudam na manutenção da higiene e no treinamento dos pets1. A Nutrisana oferece uma variedade de formatos, como líquidos, pastas, pós e comprimidos, para atender às diferentes preferências e necessidades dos animai', 99.5, 79.6, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/sg-11134201-7rdws-m0vwf1u1abm6df', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F23797903700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20814328623', 'Carbonato De Magnésio Em Bloco Cross Funcional Chalk Block 30g Rythmoon', 'Este formato inovador evita o desperdício por suspensão, além de ser mais resistente que os blocos tradicionais pra você aproveitar muuito do começo ao fim do saquinho. Além disso, você consegue salvar aquele parceiro que está sem magnésio de uma forma muito mais fácil! O melhor motivo pra você adquirir o magnésio é porque é NACIONAL, sintetizado por especialistas. Pensamos em cada molécula pra conseguir a MELHOR eficiência na absorção do suor de suas mãos. Sua utilização é indicada para aumentar o desempenho em diversas praticas esportivas como: Escalada Crossfit Ginastica Olímpica Levantamento de Peso Olímpico Tecnologias : Melhor Aderência Agente Secante Clima Quente e Úmido Matéria Prima Importada Seca o suor das mãos Prático Traz maior segurança Ajuda na aderência Conteúdo da Embalagem: 01 un. Carbonato de Magnésio em Bloco Cross Funcional Chalk Block 30g Rythmoon Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 22.0, 22.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Rock Climbing', 'https://cf.shopee.com.br/file/7a21867b5f766ba9c4d5b93f18e679c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F20814328623', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
