INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49653019440', 'Isca Holográfica Borá 7,5 Lucky Nelson Nakamura Meia Água Pesca Esportiva 7g Balanceamento Rattlin Chocalho Forte', 'A Isca Artificial Borá 7,5 Holográfica da Lucky Moldes by Nelson Nakamura é uma meia água desenvolvida para oferecer ação eficiente, brilho elevado e excelente poder de atração. O acabamento holográfico aumenta a reflexão de luz dentro da água, destacando a isca mesmo em dias claros ou locais com maior luminosidade, facilitando a visualização pelos predadores. O corpo balanceado trabalha de forma estável no recolhimento e o chocalho interno gera vibração adicional, reforçando o efeito visual da holografia e ajudando a provocar ataques. Pode ser trabalhada com recolhimento contínuo ou com toques curtos na ponta da vara, simulando um peixe ferido com alta capacidade de chamar atenção em pouca distância. É indicada para predadores de água doce e costeira, entregando resposta rápida e forte apelo visual. Características Modelo: Borá 7,5 Tamanho: 7,5 cm Peso: 7 g Ação: Meia água Tipo: Artificial Acabamento: Holográfico Efeito sonoro: Rattlin', 56.9, 56.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fishing', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi5x9sor3qir76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F320275364%2F49653019440', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54909322408', 'TOALHAS UMEDECIDAS SELECTWIPES BASIC ROXO 100 COM TAMPA', 'Os Lenços Umedecidos Select Wipes Basic são a escolha ideal para quem busca praticidade e cuidado com a pele. Com 100 unidades em cada embalagem, esses lenços são perfeitos para o dia a dia, oferecendo uma limpeza eficaz e suave. Desenvolvidos sem álcool, são hipoalergênicos e adequados para peles sensíveis, garantindo conforto e segurança em cada uso. Dermatologicamente testados, proporcionam uma experiência de limpeza que respeita a saúde da sua pele. Seja em casa, no trabalho ou em passeios, os Lenços Umedecidos Select Wipes Basic são a solução prática para manter a higiene em qualquer situação. Experimente e sinta a diferença na sua rotina de cuidados pessoais.', 14.9, 14.9, NULL, 'Home & Living > Home Care Supplies > Toilet Paper', 'https://cf.shopee.com.br/file/sg-11134201-820na-mnd06c6kzksi8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683952730%2F54909322408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394427960', 'Tapete Adana Liana 50x180cm Tapetes São Carlos', 'Informações Técnicas: 100% Polipropileno Altura aproximada dos fios: 6mm Contém antiderrapante: Não Base: Resina Proteção: Ultravioleta Disponível em Medidas especias: Não Imagem meramente ilustrativa Regras de Utilização: - Recomenda-se alterar a posição do tapete no ambiente a cada três meses, para assegurar o uso homogêneo da superfície, - Lavagem à mão, Temperatura máxima: 40ºC; - Não alvejar, Não branquear; - Não secar em tambor; - Secagem por gotejamento na horizontal; - Não passar; - Não limpar a seco; - Limpeza a úmido profissional: processo normal,', 119.99, 119.99, NULL, 'Home & Living > Decoration > Carpets & Rugs', 'https://cf.shopee.com.br/file/sg-11134201-824jf-mezon2x9mxhrfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778935801%2F23394427960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42554306100', 'Fonte Carregador para Notebook Dell Inspiron 14-5458', 'Fonte Carregador para Notebook Dell Inspiron 14-5458 | 19.5V 3.34A 65W A fonte para Dell Inspiron 14-5458 foi aprovada em rigorosos testes de qualidade e atende todas as exigências do seu equipamento. Possui tecnologia exclusiva de proteção contra excessos de corrente, superaquecimento e curto-circuito. Todas as fontes bringIT possuem 36 meses de garantia contra defeitos de fabricação. E contam com seletor automático de tensão, que permite funcionamento em 110V e 220V. OUTPUT: DC 19.5V 3.34A 65W Plug: 4.5mm x 3.0mm Caso você não possua a fonte original, você pode encontrar esta informação em seu notebook indicada como INPUT. Itens inclusos: cabo de 1,20m Marca: bringIT Modelo: 14-5458 Referência: FT126-DE-0027 Atenção: Para que essa fonte seja compatível com seu notebook, deverá ter pino e voltagem iguais e a amperagem igual ou maior que a do anúncio. Esse produto é compatível com os notebooks: LA65NS2-01, 4.5 MM X 3.0 MM, P75F, 3490, 5558, 3410, 14-5458, 15-3510-P25T, 15-5570, 15-5566, 03V9J8, P75F006, 15-3510, 15-3567, 15-3501, 3520, 3540, 3400, 3480, 11 3000 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 106.75, 79.9, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-824ij-mpv32djvbb4b8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F42554306100', NULL, NULL, '2026-07-28T02:11:31.708458+00: