INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093255176', 'Oleo Corporal Bio-Oil 200ml', 'O óleo tem uma notável capacidade para melhorar a pele. Como e por que razão isso acontece não é totalmente compreendido, visto que os benefícios do óleo são, sobretudo, um conhecimento popular. O Bio Oil Skincare Oil foi o primeiro óleo a ser submetido a ensaios clínicos e a comprovar que ele pode melhorar o aspecto de cicatrizes e estrias. Foi o sucesso desses ensaios que levou médicos e farmacêuticos por todo o mundo a começar a recomendar o produto. Hoje em dia, o Bio Oil Skincare Oil é o produto líder mundial para cicatrizes e estrias, com mais de 400 prêmios no segmento de cuidados da pele.', 104.71, 104.71, NULL, 'Beauty > Bath & Body Care > Body Oil', 'https://cf.shopee.com.br/file/sg-11134201-7rdxp-lzfmvz268g53cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22093255176', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297917384', 'Leite Condensado Linea 210g - 2 unidades', 'Linea Leite Condensado é doce e cremoso, com uma textura e cremosidade ideal que vem do cozimento do leite. Sem adição de açúcares, é adoçado com sucralose, o adoçante derivado da cana de açúcar que contribui para a redução de sódio e calorias. Com menos calorias que o tradicional pela retirada do açúcar, pode ser utilizado para o preparo de doces ou sobremesas. 1 Kit Contém: Leite Condensado Linea 210g - 2 unidades INGREDIENTES Leite integral, cloreto de sódio, edulcorantes: sorbitol e sucralose, conservador sorbato de potássio, regulador de acidez bicarbonato de sódio, espessante pectina, estabilizante citrato de sódio e aroma natural de leite condensado. ALÉRGICOS: CONTÉM LEITE. PODE CONTER NOZES. CONTÉM LACTOSE. NÃO CONTÉM GLÚTEN.', 75.58, 68.02, NULL, 'Food & Beverages > Cooking Essentials > Cooking Paste & Kit', 'https://cf.shopee.com.br/file/sg-11134201-7rdwz-m18wz3ngo96m11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F23297917384', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19297637476', 'Anel De Pilates Kikos 39Cm', 'Indicado: Ao uso durante as aulas de pilates, r ecomendado para pessoas de todos os tipos, desde iniciante até esportistas com mais experiência. Descrição: Anel levemente flexível revestido. Fortalece e tonifica os músculos das coxas, glúteos, abdômen, peitoral e braços. COMPOSIÇÃO: Anel em polipropileno. Revestimento em borracha e espuma. DIMENSÕES: Circunferência 39 cm.', 79.0, 79.0, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Training Equipments', 'https://cf.shopee.com.br/file/sg-11134201-7rccm-lsltw5xccnu291', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082126160%2F19297637476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
