INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19871502552', 'Meião Esportivo Penalty de Futebol Adulto Matis T 39-44 Adulto', 'Treine suas habilidades com equipamentos corretos e se torne um craque de verdade. A Penalty criou o Meião Matis para proporcionar confortoe maciez aos pés e pernas durante as partidas. Além disso, o produto é confeccionado com a tecnologia Flot garantindo respirabilidade para evitar acúmulo de suor nas partidas. Benefícios Conforto aos pése pernas durante os movimentos. Respirabilidade aos pés. Evite oacúmulo de suor durante a utilização. Alguns diferenciais técnicos O Meião Matis conta com a tecnologia Flot, permitindo ajuste perfeito e total liberdade nos movimentos durante as atividades físicas. Além disso, o produto conta com a tecnologia Confort, garantindo rápida absorção e transporte de suor para a camada externa da meia, proporcionando uma secagem mais rápida deixando os pés secos para você jogar com qualidade e alta performance.', 26.9, 26.9, NULL, 'Men Clothes > Socks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbwtwa9x2na1b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F19871502552', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
