INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994332078', 'Pochete Triathlon Impermeável Cintura Corrida Hidrolight', 'Pochete Triathlon Impermeável Cintura Corrida Hidrolight A Pochete Triathlon Hidrolight Preta é a parceira ideal para seus treinos de alta performance. Com design aerodinâmico e confeccionada em neoprene, ela oferece ajuste perfeito ao corpo através da faixa regulável. Prática e versátil, possui passador de fone de ouvido, permitindo que você leve seus pertences e curta sua música durante corridas, caminhadas ou ciclismo com total liberdade e segurança. Especificações: - Material: Confeccionada em Neoprene de alta qualidade. - Ajuste: Faixa regulável para adaptação perfeita ao corpo. - Detalhe: Passador de fone de ouvido. - Tamanhos: P/M (até 100 cm) e G/GG (até 122 cm). - Indicação: Corrida, Caminhada, Ciclismo, Patinação e Academia. Benefícios: - Praticidade para carregar celular, chaves e documentos. - Design aerodinâmico que não atrapalha o movimento. - Ajuste firme que evita que a pochete balance durante o exercício. - Material resistente e confortável. - Passador de fone para maior comodidade. Composição: - 100% Poliamida (Revestimento do Neoprene). Cuidados e Conservação: Lavar à mão com sabão neutro e água fria. Não utilizar alvejante ou cloro. Secar à sombra em local ventilado. Não passar a ferro e não lavar a seco. Não guardar molhada.', 125.02, 96.99, NULL, 'Men Bags > Waist Bags & Chest Bags', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mh6afk27vdadc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F471903358%2F23994332078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898278672', 'Sandália Feminina Flat Piccadilly 500399', 'A sandália feminina Flat Piccadilly é a escolha perfeita para quem busca conforto e estilo em um só calçado. Com um design moderno e versátil, ela é ideal para compor looks variados, desde os mais casuais até os mais sofisticados. Feita com materiais de alta qualidade, possui acabamento refinado e durável, garantindo o máximo de conforto aos seus pés. Com ela, você estará sempre pronta para arrasar em qualquer ocasião. Adquira já a sua e sinta a diferença de um produto pensado especialmente para a mulher contemporânea!. MODELO: 0083990 REFERENCIA: 500399 MARCA: Piccadilly MATERIAL DA PALMILHA: EVA MATERIAL DA SOLA: Borracha ACABAMENTO: Colado/Costurado DETALHES: WIDE FITOs calçados com a característica WIDE FIT permitem que os pés fiquem bem acomodados e diminuem as dores causadas pelo Neuroma de Morton - inflamação de um nervo entre o terceiro e o quarto dedo menor, causada por compressão crônica (Joanete). GÊNERO: Female GRUPO DE IDADE: Adult TIPO DE SALTO: Flat MATERIAL DO SAPATO: Napa Stretch Soft MEDIDA DO SALTO: 3 cm aproximadamente ESTILO DE SANDÁLIA: Salto baixo TIPO: SANDÁLIA', 143.99, 143.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-7rdxn-mdg4481xpg7efd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F21898278672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
