INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4164260958', 'Pneu DSI SRI-104 700 x 28C - Arame', 'O Pneu SRI-104 da DSI com medida 700 x 28C oferece ótimo custo x benefício sendo indicado para treinos e quilometragens. A Samson Rubber Industries (Pvt) Ltd. - SRI, foi criada em 1983 como membro do Grupo DSI Samson para a fabricação de pneus e câmaras e é uma das principais fabricantes de pneus do Sri Lanka. Todos os produtos da SRI são chamados de DSI. Especificações: - Modelo SRI 104; - Medida 700 x 28 (28-622); - Capacidade 75 PSI; - Certificado Inmetro; - Qualidade DSI.', 49.9, 49.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-22120-8qcszmu5o2kv07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F4164260958', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8377647725', 'Meia de Ciclismo Sem Costura Vistho 33/38', 'Meia de Ciclismo cano longo, que oferece ao ciclista conforto, maciez e compressão na medida certa. Desenvolvido com Poliamida e Elastano (lycra), possui um designer anatômico com elástico na parte do cano que fixa o produto, faixa elástica no peito do pé que auxilia no ajuste e fixação. Além de ser respirável e com secagem rápida. Calcanhar verdadeiro Ponta sem costura Composição: 98 % Poliamida e 2 % elastano Conteúdo da Embalagem: 01 Par de Meia de ciclismo Sem Costura Vistho Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 45.0, 45.0, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Others', 'https://cf.shopee.com.br/file/8058be229b94fe4ca6d8e97ff1bb3a8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F8377647725', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
