INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29037464423', 'Calça Legging Cós Cruzado Suplex Poliamida Academia Feminina Coleção Pace Up', 'Essa Legging foi criado para oferecer suporte e liberdade de movimentos, com um tecido que se ajusta perfeitamente ao corpo e proporciona suavidade ao toque, além de possuir uma modelagem que aparenta uma cintura mais fina! Sua experiência de treino atinge um novo patamar, enquanto o design moderno e os detalhes cuidadosamente trabalhados tornam esta Legging uma escolha irresistível para quem busca o equilíbrio perfeito entre moda e funcionalidade. Informações adicionais: Informações adicionais: A modelo veste: P Proteção UV50+: Sim Composição: 82% poliamida / 18% elastano Garantia: Contra defeitos de fabricação *Cores claras: Opte por usar lingerie de cor nude.', 144.9, 126.9, NULL, 'Women Clothes > Pants & Leggings > Leggings & Treggings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-maubg5gpqbnze6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373847201%2F29037464423', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
