INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27814759387', 'Antena Curta Retevis SMA-F Para Rádio H-777/RT-5R B6 5RV/RT5 BaoFeng Kenwood', 'A antena de chicote RT-805S Original Retevis RT-805S permitirá que você obtenha mais alcance em seu rádio portátil, como Retevis RT-5R, H-777,BaoFeng 888, rádio UV-5R. Esta antena possui um sinal de 2,15/3,0db com até 10Watts de potência. É 5cm de comprimento e pesa 16g. 🤗Adequado para Retevis RA79 RT29 RT86 RM21 RT29D Aliunce HD1 HD2, compatível com BaoFeng UV-5R BF-F8HP BF-888BF-S Arcshell AR-5 walkie-talkie. 🤗Nova Retevis RT-805s Antena Curta SMA-F Feminina Para Retevis H-777/RT-5R/RT-B6/RT-5RV/RT5 BaoFeng/Kenwood/Wouxun/TYT/Puxar rádio de duas vias Especificação de especificação Modelo: Retevis RT-805S Banda: Banda dupla VHF/UHF Frequência: 144/430MHz (136-174+400-480MHz) Grão: 2,15db/3,0db Potência máxima: 10W -VSWR:<1,5 Impedância: 50 ohm -Conector -Conector: Sma-f Comprimento: 5 cm - Comprimento: 5 cm 🤗O pacote inclui o pacote Antena SMA-F 1 x RT-805s 🤗Comprimento fácil de transportar e caber no bolso 🤗Conector sma-f; frequência 144/430MHz (136-174+400-480MHz) 🤗A potência máxima de 10W pode melhorar significativamente o sinal de rádio 🤗Não necessita de ferramentas; plug and play; uma ótima melhoria sobre rádios 🤗Antena SMA-F é indicada para Retevis RA79 RT29 RT86 RM21 RT29D RB85 RT5R RT56 RT43 RB22 RB25 P1 Aliunce HD1 HD2; compatível com BAOFENG BF-F8HP UV5R UV-82 Kenwood TK-250, etc. Modelo de aplicações de aplicação #Retevis #Short Antena #BaoFeng Rádio Kenwood', 64.0, 64.0, NULL, 'Mobile & Gadgets > Others', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m52kuk1cicom6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F274517927%2F27814759387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
