INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792944422', 'Cesto Organizador 12 Litros Flow CFW450 - Ou', 'Cesto Flow 12 Litros - Ou Os Cestos Flow da Ou são aliados essenciais na organização de qualquer ambiente, oferecendo praticidade e eficiência no armazenamento de diversos itens. Com capacidade de 12 litros e medidas de 34x27x13 cm, proporcionam espaço suficiente para guardar produtos de limpeza, roupas ou acessórios, mantendo cada espaço da casa organizado de forma fluida e eficaz. Seu design ergonômico conta com uma pega em formato redondo para encaixe confortável dos dedos, tornando o manuseio mais simples e confortável. Fabricados em PP (Polipropileno), os Cestos Flow são resistentes e duráveis, garantindo sua utilização por longos períodos. Simplifique sua rotina diária e mantenha sua casa organizada com os Cestos Flow da Ou. Especificações Marca: Ou Modelo Cesto Flow 12 Litros Material: PP (Polipropileno) Capacidade: 12 litros Medidas: 34x27x13 cm Peso: 341g', 49.9, 44.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbr3yvevs9qx06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F335160199%2F23792944422', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
