INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297875133', 'Kit Multimídia Saveiro G5 Espelhamento + Moldura 2 Din', 'Seja bem-vindo à eletroking, leia atentamente a descrição do produto abaixo antes da compra, qualquer dúvida, nos acione no campo de perguntas do anúncio. Central Multimídia MP5 7 Ultron Bluetooth/USB/Espelhamento Saveiro G5 Moldura Preta 2 Botões Descubra a Central Multimídia MP5 Ultron T1 com tela touchscreen de 7 polegadas, perfeita para acessar seus aplicativos favoritos diretamente do seu smartphone via espelhamento para Android e iOS. Com recursos avançados, esta central reproduz áudio e vídeo em diversos formatos, oferece conexão Bluetooth, entrada USB e suporte para câmera de ré, proporcionando uma experiência completa e prática. Incluímos também uma moldura 2 din de 7 polegadas projetada especificamente para proporcionar um encaixe perfeito e acabamento elegante. Especificações Técnicas: Central Multimídia MP5 Ultron T1 2 Din 7 BT/USB/SD/AUX/AM/FM/Espelhamento • Tecnologia MP5 de reprodução de áudio e vídeo; • Reprodução nos formatos: RMVB, MPG4, DIVX, AVI, MP3, MP4, MP5, MPEG E JPEG; • Tela Digital Touchscreen de 7 Polegadas HD • Resolução: 1024x600 • Controle Remoto Infravermelho incluso • Chassi compacto de fácil instalação • Entrada USB • Entrada para câmera de ré • Entrada para câmera frontal • Entrada RCA • Equalizador • Botões RGB Multi Color • Conexão Bluetooth • Leitor de cartão mini-SD • SWC (Compatível com sistemas de comando de volante) • Rádio AM/FM • Potência: 4x45 Watts (4x60 Watts MÁX) • Alimentação: 12 Volts Moldura 2 Din 7 Saveiro G5 - Fiamon • Abertura no Modelo 2 Din • 7 Polegadas • Produzido em ABS Injetado Resistente • Alta Resistência e Excelente Durabilidade • Cor Disponível: Preta • Tonalidade Preta Fiel à Original do Carro • Encaixe Sob Medida • Acabamento Impecável • Fácil Instalação Conteúdo da Embalagem: • 01 Central Multimídia MP5 Ultron T1 2 Din 7 • 01 Moldura 2 Din 7 Saveiro G5 • Manuais Compativel com Saveiro G5 Importante: • Garantia de 273 Dias • Valor do kit • Todos os Nossos Produtos São Novos, Originais e Acompanham Nota Fiscal. • A eletroking recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 357.2, 335.77, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/sg-11134201-7rdyf-m0lomych9u2s58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F463375702%2F20297875133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
