INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094549100', 'Tênis Masculino Siesta Red Nose Rnvm606', 'O Tênis Masculino Siesta Red Nose RNVM606 é perfeito para homens que buscam conforto e estilo em um calçado. Com design moderno e cores vibrantes, o tênis é confeccionado em materiais de alta qualidade, proporcionando durabilidade e resistência. Seu solado antiderrapante garante segurança e estabilidade ao caminhar. Ideal para compor looks casuais e despojados, o Siesta Red Nose RNVM606 é a escolha ideal para homens que gostam de se destacar com um calçado único e cheio de personalidade.. MODELO: 0290606 REFERENCIA: RNVM606 MARCA: Red Nose MATERIAL DA PALMILHA: EVA MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GÊNERO: Male GRUPO DE IDADE: Adult MATERIAL DO SAPATO: Sintético ESTILO DO TÊNIS: Urbano', 263.99, 263.99, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-825as-mg3pj6hdyw3s5f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F23094549100', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258748019', 'Kit MINI Bolinha de brigadeiro Flormel Zero Açúcar 60g com 3 Pacotes', 'Kit MINI Bolinha de brigadeiro Flormel Zero Açúcar 60g com 3 Pacotes A Bolinha de Brigadeiro Zero preserva o autêntico sabor Brigadeiro, pois ela é envolvida no granulado trazendo maciez e o sabor do cacau, proporcionando uma experiência cheia de coisas boas em cada mordida. A nossa Bolinha de Brigadeiro Zero é uma opção ideal para quem procura cuidar da saúde sem abrir mão do sabor, vem em uma embalagem que abre e fecha, facilitando o armazenamento do brigadeiro. Você pode colocar na lancheira do seu filho, pode compartilhar com os amigos e familiares, trazendo praticidade para o seu dia a dia.', 47.7, 47.7, NULL, 'Food & Beverages > Bakery > Cakes & Pies', 'https://cf.shopee.com.br/file/sg-11134201-81zwt-mn0cjjvnxdz826', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674436044%2F58258748019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693410988', 'Leave-in Serie Expert NutriOil 150ml - L''oreal', 'L''Oréal Professionnel Serie Expert NutriOil Leave-in para cabelos secos e ressecados. L''Oréal Professionnel Serie Expert NutriOil promove cabelos 4x mais macios, proteção térmica e efeito antifrizz por até 24 horas. O Leave-in L''Oréal Professionnel Serie Expert NutriOil é a solução ideal para cabelos mais nutridos e com muito mais brilho. Sua fórmula é enriquecida com óleo de coco e oferece textura leve e nutritiva para os fios. A proteção térmica atinge até 230ºC e o efeito antifrizz por até 24 horas. Como Usar Conselho de Aplicação Sobre o cabelo úmido, distribua o leave-in uniformemente pelo comprimento e pontas. Não enxágue e finalize como desejar.', 159.9, 139.35, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdxh-m12vkkpiwwdwa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23693410988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693341759', 'Kit 2 Refis Shampoo Absolut Repair 240ml', 'O Shampoo L''Oréal Professionnel Serie Expert Absolut Repair Gold Quinoa + Protein é indicado para cabelos danificados, promovendo reparação, brilho e leveza. Sua fórmula restaura a fibra capilar e melhora a aparência dos fios, deixando-os mais saudáveis, macios e maleáveis. Com uma ação que reduz danos, oferece hidratação profunda sem pesar o cabelo. A versão refil de 240ml permite reabastecer o frasco de 300ml, utilizando 75% menos plástico, com capacidade para 24 lavagens._x000D_ _x000D_ _x000D_', 290.72, 141.03, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rdwl-m0d188ls4twl81', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F22693341759', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10491349348', 'Tônico Salon Line SOS Bomba Salon Line Crescimento Acelerado 100ml', 'Tônico Salon Line SOS Bomba Salon Line Crescimento Acelerado 100Ml Experimente o poderoso Tônico Fortalecedor S.O.S Bomba Crescimento Acelerado. Esse tônico exclusivo estimula o crescimento saudável dos fios, nutrindo e fortalecendo-os desde a raiz. Além disso, ele também é eficaz para acelerar o crescimento das sobrancelhas. Com sua fórmula avançada, esse tônico oferece uma ação condicionante, deixando os fios e as sobrancelhas mais macios e sedosos. Transforme seu cabelo e suas sobrancelhas com o Tônico Fortalecedor S.O.S Bomba Crescimento Acelerado. Adquira agora e desfrute de resultados incríveis! Recomendações: Ideal para todos os tipos de cabelos. Indicados para cabelos fragilizados e cabelos danificados. Modo de uso: Couro cabeludo: depois de lavar o cabelo, aplique o tônico para crescer cabelo S.O.S Bomba Crescimento Acelerado e faça massagens circulares. Não precisa enxaguar. Sobrancelha: aplique o Tônico Salon Line fortalecedor de cabelo diariamente nas sobrancelhas e faça massagens circulares. Não precisa enxaguar. Dica de uso: Use a linha completa para um cabelo ainda mais saudável. Especificações: Código interno: 9695025 Volume: 100Ml Importante: * Produtos de decoração não inclusos. Imagens meramente ilustrativas; * As cores dos objetos podem sofrer alterações devido a luminosidade, configurações do monitor e até mesmo a percepção do usuário; * Os dados divulgados são de responsabilidade do fabricante/fornecedor.', 24.9, 24.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lj4iv3amktrkfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F10491349348', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
