INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257923790', 'Vult Super Fix Máscara De Cílios 10g', 'Prepare-se para ter cílios impecáveis com a Máscara de Cílios Vult Super Fix. Sua fórmula inovadora, combinada ao exclusivo pincel espiralado, garante volume, alongamento e definição extremos por até 18 horas: Resistente à água, suor e atrito;Pincel que potencializa o efeito de curvatura nos fios;Pigmentação preta intensa;Longa duração;Fácil remoção. A Máscara de Cílios Vult Super Fix é a escolha ideal para quem busca um olhar poderoso e duradouro. Sua fórmula de alta performance garante cílios impecáveis, resistentes a qualquer desafio, sem abrir mão da praticidade. Vult é uma marca 100% brasileira, nascida em 2014 e comprometida a incentivar a mudança e a transformação como uma verdadeira fonte de beleza e realização pessoal, de maneira acessível. Em seu portfólio, busca promover beleza de maneira democrática, empoderadora e versátil, com itens para todos os momentos de cuidado, como base, esmalte, batom, blush, sombra, skin care e cuidados capilares Tudo cuidadosamente imaginado e desenvolvido para facilitar o dia a dia de mulheres determinadas e comprometidas com seu corre, e importância do autocuidado e do verdadeiro bem-estar. Nenhum produto Vult é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 52.99, 52.99, NULL, 'Beauty > Makeup > Eyes', 'https://cf.shopee.com.br/file/sg-11134201-8261t-mmgjsik3tqtgd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1675526045%2F58257923790', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
