INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18349715916', 'Colcha King Buddemeyer In Design 100% Algodão Penteado', 'CARACTERÍSTICA DO PRODUTO: Trabalho em elegante estilo geométrico e acabamento todo em franja conferindo um toque moderno e sofisticado. Um produto versátil que pode ser utilizado como colcha mas também como manta e para decoraçãoPré-lavada e pré-encolhida, conferindo durabilidadeQualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 colcha king 230x280cm COMPOSIÇÃO: 100% Algodão TIPO DE MATERIAL: 100% Algodão DESCRIÇÃO: Colcha King In Design. Produzido em 100% algodão penteado. A coleção In Design da Buddemeyer tem design sofisticado. Trabalho em elegante estilo geométrico conferindo um toque moderno e sofisticado. Um produto versátil que pode ser utilizado como colcha mas também como manta e para decoração. Possui acabamento todo em franja que inspira modernidade e sofisticação. Produto pré-lavado e pré-encolhido, conferindo durabilidade e maciez. Produzido em 100% algodão. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 60°C. O melhor sabão para manter as características do produto é o de coco ou neutro. Não colocar sabão diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Temperatura máxima da base do ferro 110°C. Não usar ferro a vapor. Não lavar a seco.', 389.37, 347.26, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/sg-11134201-7rfgn-m9ktb3a9ban62a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F