INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206603560', 'NIVEA Q10 Plus Antiidade - Creme Hidratante para as Mãos 75g', 'Creme hidratante para as mãos. NIVEA Q10 Plus Reparação 3 em 1 ajuda a prevenir o aparecimento de manchas e oferece hidratação duradoura, por até 24 horas. O Creme para as Mãos NIVEA Q10 Plus Reparação 3 em 1 adiciona um toque macio e sedoso na pele. Sua fórmula conta com Q10 Plus, coenzima produzida naturalmente no corpo, estimula a renovação celular, combate os sinais da idade e uniformiza o tom, agindo como um poderoso Redutor de Linhas e antissinais para as mãos. Além disso, sua composição é dermatologicamente testada. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 27.9, 27.9, NULL, 'Beauty > Hand, Foot & Nail Care > Hand Care', 'https://cf.shopee.com.br/file/sg-11134201-8260e-mlmiykhd0av5c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58206603560', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997683536', 'MARIA CLARA E JP O SUMIÇO DO CELULAR', 'MARIA CLARA E JP O SUMIÇO DO CELULAR Maria Clara e JP querem brincar com o pai, mas ele passa muito tempo ao telefone. Der repente o telefone se perde O que será que aconteceu?. Informações Adicionais Autor: CIRANDA, CULTURAL Data Publicação: 01/01/1900 Tipo de capa: CAPA DURA Condição do Item: Novo Subtitulo: MARIA CLARA E JP O SUMIÇO DO CELULAR Idioma: INDEFINIDO Páginas: 8 Edição: 2 ISBN-13: 9788538098089 ISBN-10: 853809808X', 21.19, 21.19, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rd5n-luh63hybaj4y37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F18997683536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251688486', 'O REI LOBO: OS REIS DE AVALIER — VOL 4', 'O REI LOBO: OS REIS DE AVALIER — VOL 4 BATALHAR POR UM MUNDO PARA DESFRUTAR DE UM AMOR DO PASSADO. Zara se destaca como uma das mulheres mais influentes e poderosas, capaz de enfrentar até os membros de destaque da alcateia de lobos. Com tamanha habilidade, não foi uma surpresa quando o Rei Lobo a convocou para participar dos Duelos Reais – que pode decidir quem ocupará o trono de rainha. No entanto, para Zara, há um motivo adicional para entrar nessa competição... Ela sabe exatamente com quem está lidando, pois conheceu o rei quando ele era apenas o príncipe Axil. Aos quinze anos, ele foi seu primeiro amor e prometeu que, um dia, se casariam. Entretanto, a relação tomou um rumo inesperado quando o irmão mais velho de Axil a menosprezou, e ele simplesmente partiu, deixando para trás todas as promessas que havia feito a ela. Motivada por de vingança, sua intenção é provar a ele que uma simples aldeã pode se tornar rainha. E decidida a se submeter aos desafios, Zara está ciente de que a recompensa final será casar com Axil e passar o resto da vida fazendo ele se arrepender de tê-la abandonado. Mas, quando ficam frente a frente, ela percebe que algo mudou; o rei lobo não é mais o mesmo garoto que amava na adolescência. Muitos anos se passaram desde o último encontro, e ele implora por uma segunda chance. Em meio a uma batalha mortal, Zara se sente dividida entre o orgulho e a esperança... mas há uma guerra em curso. O destino de Avalier está em risco e todos os reinos se unem para a batalha final.', 51.92, 51.92, NULL, 'Books & Magazines > Books > Biography & Memoirs', 'https://cf.shopee.com.br/file/sg-11134201-822yg-mi1o26jm8lc447', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F58251688486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
