INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52653503008', 'Optivet Clean Vetnil para cães e gatos 100 ml', 'Optivet Clean é um spray da Vetnil indicado para a limpeza da região periocular de cães e gatos. Auxilia na remoção de secreções, resíduos e sujeiras que se acumulam ao redor dos olhos, contribuindo para manter a área limpa e bem cuidada no uso diário. Pode ser utilizado de forma rotineira, inclusive em animais com maior tendência ao acúmulo de secreções, respeitando sempre a forma correta de aplicação. FICHA TÉCNICA • Indicação: Higiene da região periocular • Finalidade: Auxiliar na remoção de secreções e resíduos • Tipo de produto: Spray de limpeza ocular • Área de uso: Região ao redor dos olhos • Apresentação: Frasco spray • Volume: 100 ml • Público alvo: Cães e gatos CUIDADOS COM O PRODUTO Evitar contato direto com os olhos. Aplicar com auxílio de algodão ou gaze limpa. Utilizar conforme orientação do fabricante. Armazenar em local seco e protegido da luz. Manter fora do alcance de crianças e animais não destinados ao uso.', 84.9, 54.9, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-81z1k-milgcihaj9c2af', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F293152127%2F52653503008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205446732', 'Eudora Instance Obsessão por Baunilha Creme Hidratante Desodorante Corporal 400ml', 'O Creme Hidratante Desodorante Corporal Eudora Instance Obsessão por Baunilha é ideal para quem busca uma pele macia e intensamente perfumada. Sua fragrância oriental envolvente combina a cremosidade da baunilha com notas florais. Conheça as características desse produto que vão fazer você se apaixonar: - Fórmula com Hydracolageno (colágeno vegetal); - Hidratação profunda por até 48 horas; - Rápida absorção: Passou, Secou, Hidratou; - Produto vegano e livre de parabenos. Este hidratante corporal proporciona sensação de firmeza e vitalidade, deixando a pele desodorizada com textura cremosa. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 59.99, 59.99, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-8260x-mkwpybhlhuyu79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58205446732', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997518088', 'Polia Correia Alternador Peugeot 206 2004 a 2009 - 798549 - T951250', 'Polia Correia Alternador Peugeot 206 2004 a 2009 798549 T951250 1.4 8v É o componente que está montado no eixo do rotor do alternador, e por meio de uma correia de distribuição, o alternador gira conforme a velocidade do rotação do motor(Rpm). Esta correia pode ser do tipo trapezoidal ou do tipo poly-V.', 63.73, 63.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbni-loh8nl0vu4ioee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20997518088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12454274420', 'Farol Milha Tipo 93 94 95 96 97', 'Código do produto: 48 O farol de milha é uma peça essencial para visibilidade em vias noturnas ou em dias de neblina. Eles devem estar sempre em bom estado para maior segurança do motorista e seus ocupantes. Este item possui material de alta qualidade e resistência, composto com sua lente vidro que deixa seu carro com aspecto diferenciado de todos os outros. Compatível com: Fiat - Tipo 1993 - Tipo 1994 - Tipo 1995 - Tipo 1996 - Tipo 1997 Especificações Técnicas: - Lente Lisa - Material da Lente em Vidro - Material da Carcaça em Plástico - Encaixe de lâmpada H3 ATENÇÃO Garantia - 3 Meses O valor anunciado referente a Unidade. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 127.73, 127.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/0e0f3827360262796842e656831aaea8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F12454274420', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398892082', 'Mesa de Som Profissional Soundcraft Mi-6 Analógica 6 Canais USB Stereo MI 6 Estéreo', 'TRANSMITA O SEU MOMENTO Mixe e grave uma apresentação ao vivo com os mixers Mi Series, são perfeitos para capturar o seu momento. Configure, ajuste sua mix, conecte seu DAW ou grave para garantir que as ideias das sessões de composição e ensaios sejam preservadas com a qualidade de 24 bits. Se precisar integrar loops e materiais pré-gravados à performance ao vivo, isso é facilmente alcançado através da interface de áudio USB Stereo, através do media player USB e com o Streaming Bluetooth Especificações Gerais • Filtro de Passa-Alta (HI-PASS): 80 Hz - 18dB/OCT • THD: 0.02% @+14dB 20~20kHz, at Min. Ganho ; 0.09% @+24dB 1kHz, at Min. Ganho • Resposta de Frequência: +0.5/-1.5dB @+4dB 20~24kHz @620ohm • Máximo Sinal de Saída: +20dB @0.5% THD 1kHz @620ohm • Tensão de Alimentação: 100V~240V 50Hz/60Hz (fonte interna bivolt) • Potência.: 7W Dimensões • Peso Bruto: 1,85 kg • Peso Líquido: 1,30 kg • Dimensões da Embalagem Individual: 317x275x103mm Qual o conteúdo da caixa? • 1x mixer modelo MI-6 • 1x cabo de força • 1x Manual técnico', 1165.0, 695.0, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mekehc3nylfl38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229977598%2F23398892082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
