INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393216012', 'Amplificador Residencial Taramps 4 Canais 400w Rms Ths 6000 Original', 'Descubra o poder do som de alta qualidade com o receiver THS 6000 da Taramps, um receiver multicanal projetado para proporcionar uma experiência sonora excepcional em diversos ambientes, como lojas, bares, comércios, clínicas, áreas de lazer, espaços gourmet, academias e muito mais. TARAMPS THS: Receiver Multi Channel Classe D Especificações Técnicas: • Números de canais: 04 • Potência RMS: 400W • Potência RMS nominal de cada canal: 100W / 200W bridged • Entradas: Bluetooth, USB, MicroSD, MP3 player, rádio FM, AUX frontal e traseira, entrada P2, RCA, microfone, óptica • Crossover high pass (HPF): 100Hz (-12dB/8) fixo • Crossover low pass (LPF): 100Hz (-12dB/8) fixo • Roteamento: R, L, R/L e L+R • Tensão de saída RMS nominal de cada canal: 12,2 Vrms / 28,4 Vrms bridged • Distorção harmônica total + ruído (THD + N) na potência nominal de cada canal (125W): 3% • Impedância nominal de cada canal: 2 ohms / 4 ohms bridged • Sensibilidade do mic: 10 mV • Sensibilidade das entradas AUX: 200 mV • Impedância de entrada mic: 2,2k ohms • Impedância das entradas AUX: 5k ohms • Resposta em frequência (equalizadores em 0dB): 15Hz a 20kHz (-3dB) • Atuação típica do equalizador de 3 vias: Low (graves) 12dB - 80Hz / Mid (médios) 12dB - 2kHz / High (agudos) 12dB - 10kHz • Relação sinal ruído: 70dB • Sistema de proteções: Proteção nas saídas contra curto e baixa impedância • Alimentação: 90 a 240V AC • Consumo stand by: 3,5W • Consumo máximo: 508W • Fusível de proteção interno: 6A • Faixa de frequências FM: 87,5 MHz a 108 MHz Medidas: • Dimensões: 398 x 59 x 194mm • Peso: 2,20Kg IMPORTANTE: • A Loja do Som e Acessórios recomenda que a instalação seja feita por profissional especializado e não se responsabiliza pelo mau uso do produto.', 1289.7, 1289.7, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/br-11134207-820lr-mqrrqe05pzb7bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1273324128%2F23393216012', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18575860070', 'KIT 3 HENÊ PELÚCIA MÉDIO POUCH', 'Esse kit contem: - 3 unidades Henê pelúcia médio pouch Orgulhosamente Felizes Para Sempre Somos muitas, somos fortes, somos lindas! Orgulhosas do nosso cabelão, nosso pretinho nada básico! E o Henê Pelúcia, que sempre esteve ao nosso lado, agora inovou de vez. Traz o puríssimo Azeite de Oliva Preta pra nutrir os fios e fazer nosso cabelão brilhar. Henê Pelúcia tem tudo pra gente se sentir sempre livre e pronta pra chamar muuuuita atenção por onde passar! Características: INDICAÇÃO Indicado para todos os tipos de cabelos. AÇÃO Alisa, pinta de preto e trata os cabelos. ATIVOS Azeite de Oliva Preta. BENEFÍCIOS Nutrição e Megabrilho. RESULTADO Cabelão liso escorrido, preto e com brilho pra lacrar!', 51.0, 35.99, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/br-11134207-820ls-mmpq6jfqk6iv12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F18575860070', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
