INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18198966960', 'Pneu Traseiro Honda CG Titan fan Cargo YBR Factor Maggion 90/90-18 ST-6 Uso Com Câmara', 'Fundada no México há mais de 85 anos, a Maggion tem reconhecimento internacional e seus pneus são pensados para diferentes modalidades, desde carga até veículos comerciais leves e carros de passeio. Custo-benefício e ótima aderência em pistas tanto seca quanto molhadas são pontos altos dos produtos da marca. Os pneus da Maggion lhe darão um excelente controle, estabilidade e tração no seu passeio. PERGUNTAS FREQUENTES: O PNEU É NOVO OU REMOLD? R: SÓ TRABALHAMOS COM PNEUS NOVOS E ORIGINAIS DE FÁBRICAS. O PNEU VEM COM NOTA FISCAL? R: SIM, TODOS OS NOSSOS PRODUTOS ACOMPANHAM NOTA FISCAL. O PNEU VEM COM A RODA/ARO? R: O ANUNCIO É APENAS DO PNEU O PNEU ACOMPANHA CAMARA DE AR? R: NÃO ACOMPANHA, O ANUNCIO É APENAS DO PNEU Principais aplicações: - Honda CG 150 / 160 - Honda Fan - Honda Cargo / Start - Honda Today - Honda CBX150 - Yamaha RD - Yamaha YBR - Yamaha Factor Identificação: 90/90-18 Marca: Maggion Aro: 18 Modelo: ST6 Com Câmara * Observações: - O anúncio é apenas do pneu, não acompanha o aro. - Uso com câmara, não inclusa. - Possui certificados de garantia ISO 9001 / Inmetro. - Recomendamos que os produtos sejam instalados por profissionais capacitados e não nos encarregamos pelo mau uso ou instalação indevida, acarretando a perda da garantia. - Venda 100% garantida', 243.9, 219.51, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Tires', 'https://cf.shopee.com.br/file/sg-11134201-8260o-mlibe7an09oobb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F18198966960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792643318', 'Lente Para Óculos Hawker Cinza Revo Fumê Jet Adventure Motocross Enduro', 'Você está na Loja TMX Duas Rodas. Lente Oculos Hawker Cinza Revo Fume Jet Adventure Com mais de 20 anos de mercado, a paixão pelo o mundo das 2 rodas, fez Surgir a Jet Adventure. Vendo a necessidade do mercado por produtos com qualidade e preço acessível, o espírito aventureiro da marca vem se destacando no mercado nacional com produtos para o segmento de bike e moto. Buscamos aliar os melhores conceitos de produção e matéria-prima para você que possui o “Espírito de Aventura” ou é um profissional do esporte. Não Procure mais vá de JET ADVENTURE uma marca que preza pela qualidade e conforto dos seus produtos! A TMX Duas Rodas é Revendedora autorizada JET ADVENTURE® " A Lente Para Óculos Hawker é fabricada com cuidado oferecendo grande praticidade durante a remoção e troca nos óculos, Garantia uma visão mais limpa e uma pilotagem com mais desempenho e segurança. -Compra 100% Confiável!', 25.9, 25.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Clothing and Boots', 'https://cf.shopee.com.br/file/sg-11134201-7rbmm-lo1hm9hr2wj52d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F813601541%2F23792643318', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18599564674', 'Copo Neo com Canudo Skye – Patrulha Canina', 'Depois de passar o dia combatendo o tédio em Adventure Bay, você precisa de uma ajudinha para combater a sede? A gente te ajuda! Com 300ml de capacidade, feito em aço inoxidável, ajuda a manter a temperatura da bebida por muito tempo! Além de contar com um canudo de inox para não existir dificuldades na hora de tomar aquele suquinho! Não importa qual é a brincadeira, esse copo te acompanha em todos os lugares! O copo é importado, feito em aço inoxidável e plástico, possui detalhes incríveis que vão fazer você se apaixonar! Se você quer um copo que acompanhe e te hidrate por onde você for, a gente te ajuda! Com 300ml de capacidade, e parede dupla que ajuda a manter a temperatura da bebida por muito mais tempo! Com uma tampa rosqueável para evitar vazamentos na bolsa ou mochila, além de contar com um canudo de aço inoxidável incrível com um protetor de silicone! Não importa qual é o rolê, esse copo te acompanha em todas as suas aventuras! Especificações: Altura: 14cm| Largura: 7cm| Comprimento: 9cm| Capacidade: 300ml| Material: Aço inoxidável e plástico Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos.', 84.9, 84.9, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-825ax-mqqhe6h152bzf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404743073%2F18599564674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
