INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397908123', 'Tinta Acrilica Eucalar 3,6 Litros Gelo Fosco', 'Características Principais: Marca: Eucatex Cor: Gelo Tipo: Acrílica Litragem: 3,6 L Acabamento: Fosco Informações Adicionais: Uso: Interno Superfícies indicadas: Reboco, concreto, fibrocimento, massa acrílica, textura acrílica, forros acústicos, massa corrida PVA e gesso Rendimento: Até 14 m² por balde de 3,6 L (pintura acabada) Diluição: Rolo, pincel e trincha: 20% com água Airless: 30% com água Secagem: Ao toque: 30 minutos Entre demãos: 4 horas Final: 12 horas Demãos recomendadas: 2 a 3 Aplicação: Rolo de lã, pincel ou trincha Propriedades: Contém proteção antimofo para maior durabilidade Preparo da superfície: Certifique-se de que a superfície esteja limpa, seca e sem resíduos Recomendações de uso: Evitar aplicação em condições de alta umidade ou temperaturas extremas Fornecedor: Eucatex', 39.81, 39.81, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-824ia-mpiak47shtla3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23397908123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
