INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23399312450', 'Suéter Feminino Tricot Listrado Manga Longa Confortável Inverno 3RD SD3010', 'Uma peça moderna, confortável e super versátil — perfeita tanto para o dia a dia quanto para ocasiões especiais. Com caimento impecável e tecido de alta qualidade, ela garante estilo, praticidade e muito bem-estar em qualquer momento. Nada melhor do que investir em looks que elevam sua autoestima e destacam seu estilo todos os dias. Garanta já o seu! 📌 Tecido Mousse (Estica bem) (Modelo Altura 1,60m — 60kg) 📏Medidas Tamanho Unico(36-44) • Busto:100cm • Manga:60cm • Comprimento:58cm OBSERVAÇÕES 1) Recomendamos pedir sua numeração habitual. A modelagem é padrão — não veste menor nem maior. 2) Em caso de dúvidas, sugestões ou qualquer problema, nos chame no chat da loja! Atendemos também pedidos no atacado. 3) Trabalhamos somente com produtos importados e de ótima qualidade. Como não há reposição imediata, nossos estoques são limitados — aproveite enquanto temos! ♥️ Siga a 3RD Fashion e conheça todas as novidades que preparamos com muito carinho para você!', 65.0, 65.0, NULL, 'Women Clothes > Hoodies & Sweatshirts > Sweatshirts', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjyg1gvyyg3m89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F393568956%2F23399312450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23199169291', 'Pijama Infantil Menino Brilha No Escuro Kappes Branco', 'O Pijama Infantil Menino Brilha no Escuro Select é perfeito para noites cheias de conforto e diversão. Confeccionado em 100 algodão, garante maciez, leveza e respirabilidade, proporcionando um sono tranquilo. A camiseta de manga curta possui decote redondo e estampa especial que brilha no escuro, encantando os pequenos. Acompanha bermuda estampada com cós elástico, que oferece ajuste confortável e praticidade. Um conjunto lúdico e aconchegante para o dia a dia.', 59.99, 59.99, NULL, 'Baby & Kids Fashion > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258a-mqp6vyoq680f3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F778895824%2F23199169291', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293116076', 'Esteira Elétrica Dream Fitness Energy 1600 Academia Ergométrica com Inclinação Dobrável Residencial', 'A esteira Energy 1600 desenvolvida para uso residencial é dobrável e possui capacidade para até 110 Kg. Ela atinge velocidade máxima de 9 km/h, tem um nível de inclinação, um programa pré-definido de velocidade e conta com um sistema de absorção de impactos com seis amortecedores que preservam as articulações do usuário, ela é perfeita para malhar as coxas, panturrilhas, glúteos e abdômen. Esse aparelho possui monitor LCD com cinco funções, sendo elas: tempo, velocidade, distância, calorias Scan (mudança automática). Desta forma você pode acompanhar o seu desempenho em tempo real e avaliar seu desempenho. Especificações: - Modelo: Energy 1600 - Motor (HP): 1.6Hp - Velocidade Máx (Km/h): 9 - Capacidade (Kg): 110 - Uso recomendado: esteira para academia residencial - Tamanho do Produto (C/L/A): 139 x 62 x 127 cm - Peso Líquido: 41 Kg - Superfície de Caminhada: 100 x 33 cm - Voltagem: 110 e 220 (bivolt) - Material: Aço Carbono - Pintura: Eletrostática pó - Funções Monitor (Descrição): 5 Funções Calorias, Distância, Scan, Tempo, Velocidade - Com 6 armotecedores - Quantidade de posições de inclinação: 1 - Quantidade de programas: 1 - Dobrável - Com porta garrafas', 2159.9, 1959.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/sg-11134201-7rd6q-lx92lx965u8w6c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F23293116076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58261755205', 'Aplicador Microfibra Dub Jack Automotivo Dub Boyz Original Cor PretoAplicador Microfibra Dub Jack Automotivo Dub Boyz', 'Aplicador de Microfibra Dub Jack Aplicator da Dub Boyz é versátil e desenvolvido para aplicações seguras e confortáveis, proporcionando maior rendimento na cobertura das áreas. Pode ser utilizado em diversos tipos de superfície, sendo composto por microfibra de alto padrão e espuma interna de alta densidade. Possui encaixe para até quatro dedos. Como utilizar: Após definir o produto a ser utilizado, aplique-o sobre a superfície de microfibra do aplicador. Com movimentos suaves e precisos, faça a cobertura da superfície desejada. Características: - Marca Dub Boyz - Modelo DBA002 - Material Plástico - Encaixe para dedos Serve para os Modelos e Anos: Universal Especificação Técnica: - Material: Microfibra de alto padrão e espuma interna de alta densidade - Encaixe para até quatro dedos', 29.99, 29.99, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-820m3-moy889oek1s636', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1167180125%2F58261755205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
