INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44168588480', 'Umidificador de Ar 2,4 Litros BUD05B 12 Horas de Autonomia Névoa Fria Britânia', 'Disponha de maior conforto, bem-estar e saúde em qualquer ambiente. O Umidificador BUD05B possui um reservatório de água removível com capacidade de 2,4 litros, que garante até 12 horas de ar fresco e úmido no ambiente. O sistema Ultrassônico gera uma névoa fria que repõe a umidade e a qualidade do ar, amenizando diversos sintomas como alergias, olhos irritados, rinite, garganta seca e alivia e tosse. Ideal para ambientes secos e refrigerados com ar condicionado, a fim de proporcionar dias e noites mais tranquilas para respirar. Informações Técnicas: Modelo: BUD05B Tensão: 127v / 220v Bivolt Automático Potência Elétrica: 18W Autonomia Aproximada: 12 Horas Capacidade do Reservatório: 2,4 Litros Vazão de névoa: 240g/h Desligamento Automático: Sim Dimensões do Produto CxLxA: 285x148x158mm Dimensões da Embalagem CxLxA: 140x160x310mm Peso Aproximado: 0,72kg Garantia: 12 Mês Sku da Loja: Código Britânia: 065503020 - 127v / 220v Bivolt', 189.9, 172.9, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-824gg-mej1rzdf8w7b10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F951290141%2F44168588480', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
