INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259245303', 'Lava-Louças EOS Premium AI 14 Serviços Branco ELL142B 110V', '🍽️ Lava-Louças EOS Premium AI 14 Serviços Branca ELL142B ✨ Mais inteligência, eficiência e praticidade para transformar sua rotina na cozinha. A Lava-Louças EOS Premium AI ELL142B combina alta capacidade, tecnologia avançada e funções inteligentes para entregar máxima performance na limpeza com economia e praticidade. ✨ Destaques do Produto: ✅ Capacidade para até 14 serviços ✅ Design moderno e elegante na cor branca ✅ IA com detecção inteligente de sujeira ✅ Ajuste automático do ciclo conforme o nível de sujeira ✅ 8 programas de lavagem para diferentes necessidades ✅ Programas ECO, Intensivo, Esterilização, GlassCare e muito mais ✅ Funções Extras: Meio Carga, Extra Seco, Extra Rápido e Extra Higiene ✅ Sistema de secagem com troca de calor para maior eficiência ✅ Baixo consumo de água e energia ✅ Funcionamento silencioso com apenas 55 dB ✅ Proteção antivazamento e antitransbordo ✅ Ideal para famílias grandes e quem recebe convidados com frequência ✅ Alta performance com mais economia e sustentabilidade ✅ Mais praticidade e segurança para o dia a dia 📏 Medidas (LxAxP/cm): 60 x 84,5 x 60 cm', 2847.9, 2847.9, NULL, 'Home Appliances > Kitchen Appliances > Dishwashers', 'https://cf.shopee.com.br/file/sg-11134201-820mn-mnagea26gnb9de', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58259245303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
