INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18549743427', 'Kit Wella Oil Reflections Profissional - Shampoo e Máscara', 'A Linha Wella Oil Reflections proporciona maciez e luminosidade para todos os tipos de cabelo. Tratamento promove nutrição e hidratação intensa, cor protegida. Mantenha seu cabelo hidratado com o kit Wella Oil Reflections! *RESULTADO Brilho *SUGESTÃO DE USO Shampoo 1. Aplique, massageie, deixe agir por 2 minutos; 2. Enxágue. Máscara 1. Aplique a máscara nos cabelos, do comprimento a pontas; 2. Deixe o produto agindo por 5 minutos e enxague em seguida. *OBSERVAÇÕES Imagem Meramente Ilustrativa *ITENS INCLUSOS 1 Shampoo Wella Professionals Oil Reflections 1000 ml 1 Máscara de Brilho Wella Professionals Oil Reflections 500 ml', 787.9, 567.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22090-o45305u3ayhv31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F18549743427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23096674275', 'Karen Bachini Afrodite Batom Líquido Matte Aveludado 3,8g', 'O Batom líquido By Karen Bachini apresenta uma fórmula inovadora com textura aveludada, que confere efeito mate e aplicação altamente confortável. Se espalha uniformemente e não marca as linhas dos lábios, revelando cor intensa e efeito ultra-mate. Proporciona uma nova experiência com batom matte, com sensorial de creme em pó. Pigmentos de alta intensidade e com alta cobertura. Após secagem, longa duração. Alta aderência, que suaviza as linhas labiais finas. * RESULTADO: Efeito Matte * SUGESTÕES DE USO: 1.Aplique uma camada do batom sobre os lábios utilizando o pincel flecha da própria embalagem. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1Karen Bachini Afrodite Batom Líquido Matte Aveludado 3,8g', 49.9, 49.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkpc595sk6zy01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F23096674275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40873488217', 'Nillkin Shield Pro Capa De Telefone Para Xiaomi 17/17 Max Ultrafina Anti Impressão Digital À Prova De Choque Traseira Ca', 'Escudo Super Fosco Pro O Shield Pro Super fosco adota tecnologia de moldagem por injeção. Utilize os materiais duplos de PC e TPU, que atualizam a proteção. Melhore a resistência à queda com bordas macias TPU e batedores em quatro cantos. A rigidez do PC de transferência e quebra da rigidez do PC é boa o suficiente para não transferir e quebrar facilmente. A mais recente tecnologia de pintura UV fosca processada pela mais recente tecnologia de pintura UV fosca sem poeira, com confortável sensação de toque e aparência elegante. A superfície usa design de ponto saliente, resistente ao desgaste, antiderrapante, à prova de poeira, anti-impressão digital e fácil de limpar. Molde aberto de acordo com o telefone móvel real com furos de função precisos.', 90.0, 60.0, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-824jc-mfnn2bd1b2tp02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F285436073%2F40873488217', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398015167', 'Jaqueta Texx Ronin V2 Masculino Conforto e Resistência', 'Jaqueta Texx Ronin V2 Masculina – Proteção e Conforto para o Dia a Dia A Jaqueta Texx Ronin V2 Masculina é a escolha ideal para motociclistas que buscam aliar segurança, conforto e um design moderno. Confeccionada em poliéster 600D de alta resistência, essa jaqueta oferece grande durabilidade e proteção em qualquer condição climática. Abaixo, estão suas principais características: Material de Alta Resistência: Fabricada em poliéster 600D, a jaqueta oferece excelente resistência à abrasão e durabilidade, sendo ideal para o uso diário e em viagens de longa distância. Impermeabilidade STOPWATER®: Com a tecnologia STOPWATER®, ela é resistente a água, mantendo o motociclista seco e protegido em dias chuvosos. Conforto e Ajuste Ergonômico: Projetada com ajuste ergonômico que proporciona conforto e liberdade de movimento, ideal para longas horas de pilotagem. Painéis Ventilados: Sistema AIRTEXX, que permite ventilação interna, garantindo conforto térmico em dias quentes. Forro Térmico: Conta com um forro térmico destacável, ideal para ajustar a jaqueta conforme as condições climáticas. Design Moderno e Discreto: Visual esportivo com cores versáteis e logos refletivos, aumentando a segurança e a visibilidade em condições de baixa luminosidade. A Texx Ronin V2 Masculina é perfeita para o motociclista que procura um equipamento robusto e funcional, pronto para enfrentar qualquer desafio com estilo e proteção.', 520.98, 387.9, NULL, 'Men Clothes > Jackets, Coats & Vests > Jackets', 'https://cf.shopee.com.br/file/sg-11134201-7reoc-m29vwrsdwlgj77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1117095756%2F23398015167', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54311717863', 'Bíblia Infantil | Letras Grandes', 'Bíblia infantil encantadora, especialmente desenvolvida para as crianças explorarem as histórias bíblicas de maneira divertida e envolvente. Com ilustrações coloridas e uma linguagem acessível, este livro proporciona uma introdução cativante aos ensinamentos e valores presentes na Bíblia. Dentro das páginas desta bíblia, as crianças encontrarão uma seleção cuidadosa de histórias bíblicas que abrangem desde o Antigo até o Novo Testamento. Desde a criação do mundo até os ensinamentos de Jesus, cada história é apresentada de forma atraente e adaptada para a compreensão infantil. As ilustrações vivas e expressivas dão vida às histórias bíblicas, permitindo que as crianças visualizem e se conectem com os personagens e eventos descritos. As imagens coloridas estimulam a imaginação e a curiosidade, incentivando as crianças a se envolverem de maneira mais profunda com as lições e os valores apresentados. Título: Bíblia Infantil | Letras Grandes Autor: Grupo Online Páginas: 112 Formato: 15 x 22 cm Edição: 2023 Capa: Dura Peso: 0,250 kg ISBN: 9786555476224 Editora: Grupo Online', 14.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823qh-mp3my3yj9afg51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F54311717863', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
