INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18676930206', 'Coqueteleira Academia 600ml + Galão Tank 2 Litros Bodyaction', 'Kit Bodyaction: Coqueteleira + Galão de 2 Litros - Perfeito para sua Hidratação e Suplementação! 📦 O que inclui? 1x Coqueteleira Bodyaction (600ml): Ideal para misturar seus suplementos como whey protein, BCAA e pré-treinos com praticidade. 1x Galão de 2 Litros Bodyaction: Design ergonômico com alça reforçada para garantir sua hidratação ao longo do dia. 💪 Por que escolher este kit? Qualidade Premium: Fabricados com materiais duráveis e livres de BPA. Estilo e Funcionalidade: Ambos com o logo oficial Bodyaction, demonstrando seu compromisso com o esporte. Praticidade: O galão é perfeito para levar à academia, e a coqueteleira tem um bico de fácil abertura e vedação eficiente. 🎯 Uso ideal: Para treinos intensos, atividades ao ar livre ou até mesmo no dia a dia.', 87.49, 69.9, NULL, 'Home & Living > Dinnerware > Water Bottles & Accessories', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ma2uajtq906xe5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F18676930206', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
